  ('carnes_001', 'Pollo al horno con patatas', 'carnes', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 60, 'facil', 'all', 486, 38, 28, 24, 2, true, true, '{}', '[{"name":"Contramuslos de pollo","amount":400,"unit":"g"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Romero","amount":3,"unit":"g"}]'::jsonb, '{"Cortar patatas y cebolla en gajos gruesos","Colocar en bandeja con aceite, ajo y romero","Disponer el pollo encima, rociar con limón","Hornear a 200°C durante 45 min"}', 'Contramuslos de pollo asados al horno sobre cama de patatas', '[{"appliance":"horno","time":60,"difficulty":"facil","prepSummary":"Marinar el pollo y las patatas con el resto de ingredientes. Hornear a 190-200°C durante 60 minutos, volteando el pollo y las patatas a mitad de cocción para asegurar un dorado uniforme y una cocción perfecta."},{"appliance":"airfryer","time":30,"difficulty":"facil","prepSummary":"Cortar las patatas en cubos pequeños y marinar junto al pollo. Cocinar en la airfryer a 190°C durante 25-30 minutos, agitando la cesta o volteando los ingredientes a mitad para un acabado crujiente y bien cocido."}]'::jsonb, '{}'),
