  ('carnes_003', 'Albóndigas en salsa de tomate', 'carnes', 'cerdo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'principal', NULL, NULL, 40, 'normal', 'all', 438, 28, 18, 28, 2, true, true, '{"gluten","huevo"}', '[{"name":"Carne picada de cerdo","amount":300,"unit":"g"},{"name":"Pan rallado","amount":30,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Tomate triturado","amount":300,"unit":"ml"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Harina","amount":15,"unit":"g"}]'::jsonb, '{"Mezclar carne con pan rallado, huevo y ajo picado","Formar albóndigas y enharinar","Freír en aceite y reservar","Hacer salsa con cebolla y tomate, añadir albóndigas y cocer 20 min"}', 'Albóndigas caseras de cerdo en salsa de tomate', '[{"appliance":"horno","time":50,"difficulty":"normal","prepSummary":"Hornea las albóndigas en una bandeja a 200°C durante 15-20 minutos hasta que doren. Prepara el sofrito y la salsa en una cazuela apta para horno, añade las albóndigas y termina de cocinar a 180°C durante 20-25 minutos."},{"appliance":"thermomix","time":55,"difficulty":"normal","prepSummary":"Prepara el sofrito de cebolla y ajo, luego la salsa de tomate. Incorpora las albóndigas y cocínalas directamente en la salsa a 100°C, velocidad cuchara invertida, durante 20-25 minutos para que se integren bien los sabores."},{"appliance":"olla_express","time":45,"difficulty":"normal","prepSummary":"Dora las albóndigas en la olla abierta, retira. Haz el sofrito y la salsa en la misma olla, reincorpora las albóndigas y cocina a presión durante 10-12 minutos para un resultado tierno y rápido."}]'::jsonb, '{}'),
  ('carnes_004', 'Filetes de lomo empanados', 'carnes', 'cerdo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 462, 34, 22, 26, 2, true, true, '{"gluten","huevo"}', '[{"name":"Lomo de cerdo en filetes","amount":300,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Pan rallado","amount":60,"unit":"g"},{"name":"Harina","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Salpimentar los filetes","Pasar por harina, huevo batido y pan rallado","Freír en abundante aceite caliente","Escurrir sobre papel absorbente"}', 'Filetes de lomo de cerdo empanados y fritos', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Para unos filetes crujientes y con menos aceite, precalienta la airfryer a 190-200°C. Rocía los filetes empanados con un poco de aceite y cocina durante 12-15 minutos, dándoles la vuelta a mitad de cocción para un dorado uniforme."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Hornea los filetes para una versión más ligera. Precalienta el horno a 200°C con calor arriba y abajo. Coloca los filetes sobre una rejilla en una bandeja y hornea durante 20-25 minutos, volteándolos a mitad para que queden dorados por ambos lados."}]'::jsonb, '{}'),
  ('carnes_005', 'Estofado de ternera', 'carnes', 'ternera', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 90, 'normal', 'invierno', 468, 36, 22, 26, 2, true, true, '{}', '[{"name":"Carne de ternera para guisar","amount":350,"unit":"g"},{"name":"Patata","amount":200,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Vino tinto","amount":80,"unit":"ml"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Sellar la carne en aceite caliente y reservar","Pochar cebolla y zanahoria, añadir tomate","Incorporar la carne, vino y laurel, cubrir con agua","Cocer a fuego lento 1 h, añadir patatas y cocer 20 min más"}', 'Ternera guisada a fuego lento con patata, zanahoria y vino tinto', '[{"appliance":"horno","time":110,"difficulty":"normal","prepSummary":"Tras dorar la carne y pochar las verduras en una olla apta para horno, añade el resto de ingredientes y cocina tapado en el horno precalentado a 160°C durante 90-100 minutos hasta que la carne esté muy tierna."},{"appliance":"thermomix","time":85,"difficulty":"normal","prepSummary":"Sofríe las verduras y dora la carne (con mariposa o giro inverso). Añade el resto de ingredientes y cocina a 90-100°C, velocidad cuchara y giro inverso, durante 60-70 minutos hasta que la carne esté tierna y la salsa ligada."},{"appliance":"olla_express","time":45,"difficulty":"facil","prepSummary":"Dora la carne y sofríe las verduras en la olla. Incorpora los líquidos y el laurel, cierra la olla y cocina a presión (nivel 2) durante 25-30 minutos. Deja despresurizar naturalmente para una carne más tierna y jugosa."}]'::jsonb, '{}'),
  ('carnes_006', 'Pollo al ajillo', 'carnes', 'pollo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 30, 'facil', 'all', 398, 36, 4, 26, 2, true, true, '{}', '[{"name":"Pollo troceado","amount":500,"unit":"g"},{"name":"Ajo","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Guindilla","amount":1,"unit":"ud"}]'::jsonb, '{"Dorar el pollo salpimentado en aceite","Añadir ajos laminados y guindilla","Verter vino blanco y laurel","Tapar y cocer 20 min a fuego medio"}', 'Pollo troceado frito con abundante ajo y vino blanco', '[{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Dora el pollo y el ajo en una sartén apta para horno o cazuela. Añade el vino y el laurel, luego hornea a 180°C durante 20-25 minutos hasta que el pollo esté tierno y la salsa reducida."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Dora el pollo y el ajo en la olla express abierta con un poco de aceite. Incorpora el vino y el laurel, cierra la olla y cocina a presión durante 10-12 minutos. Despresuriza y sirve."},{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Sofríe el ajo y luego el pollo en el vaso a temperatura Varoma con giro inverso. Añade el vino y el laurel, y cocina 15-20 minutos a 100°C, velocidad cuchara, giro inverso, hasta que el pollo esté tierno."}]'::jsonb, '{}'),
  ('carnes_007', 'Cinta de lomo adobada', 'carnes', 'cerdo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 346, 34, 3, 22, 2, true, true, '{}', '[{"name":"Cinta de lomo","amount":300,"unit":"g"},{"name":"Pimentón","amount":6,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Orégano","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre","amount":15,"unit":"ml"}]'::jsonb, '{"Macerar la carne con pimentón, ajo, orégano y vinagre 30 min","Calentar aceite en sartén a fuego fuerte","Freír los filetes 2 min por lado","Servir con el jugo de la sartén"}', 'Filetes de cinta de lomo adobados con pimentón y ajo', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Marinar la cinta de lomo. Precalienta la airfryer a 190-200°C y cocina durante 15-20 minutos, dándole la vuelta a mitad para un dorado uniforme y una textura jugosa."},{"appliance":"horno","time":22,"difficulty":"facil","prepSummary":"Tras marinar, hornea la cinta de lomo a 190-200°C (con ventilador si es posible) durante 20-25 minutos. Voltéala una vez para asegurar una cocción pareja y un exterior ligeramente dorado."}]'::jsonb, '{}'),
  ('carnes_008', 'Guiso de ternera con patatas', 'carnes', 'ternera', NULL, ARRAY['plato_unico']::meal_role[], 'completo', 'carnes_005', NULL, 80, 'normal', 'invierno', 492, 34, 30, 24, 2, true, true, '{}', '[{"name":"Carne de ternera para guisar","amount":300,"unit":"g"},{"name":"Patata","amount":250,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Guisantes","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vino blanco","amount":60,"unit":"ml"}]'::jsonb, '{"Sellar la ternera en dados en aceite caliente","Pochar cebolla y zanahoria, añadir tomate","Incorporar vino y agua, cocer 50 min","Añadir patatas y guisantes, cocer 20 min más"}', 'Ternera guisada con patatas, guisantes y zanahoria', '[{"appliance":"horno","time":110,"difficulty":"normal","prepSummary":"Se sella la carne y se sofríen las verduras en una olla apta para horno. Se añade el resto de ingredientes y se cocina tapado en el horno a 160°C durante 100-120 minutos, hasta que la carne esté muy tierna. El truco es el cocinado lento y uniforme para una ternera melosa."},{"appliance":"thermomix","time":80,"difficulty":"normal","prepSummary":"Pica las verduras y sofríelas. Incorpora la carne para sellarla ligeramente, luego añade el resto de ingredientes y programa a 90-100°C, giro inverso, velocidad cuchara, durante 70-90 minutos. El truco es usar el giro inverso para no deshacer la carne y que quede jugosa."},{"appliance":"olla_express","time":50,"difficulty":"normal","prepSummary":"Sella la carne y sofríe las verduras en la olla. Añade el resto de ingredientes (excepto guisantes) y cocina a presión durante 35-45 minutos. Despresuriza, añade los guisantes y cocina unos minutos más. El secreto es el tiempo reducido y la carne excepcionalmente tierna."}]'::jsonb, '{}'),
  ('carnes_009', 'Hamburguesas caseras', 'carnes', 'ternera', NULL, ARRAY['segundo','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 448, 30, 24, 26, 2, true, false, '{"gluten","huevo"}', '[{"name":"Carne picada de ternera","amount":300,"unit":"g"},{"name":"Cebolla","amount":40,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Pan rallado","amount":20,"unit":"g"},{"name":"Pan de hamburguesa","amount":2,"unit":"ud"},{"name":"Tomate","amount":80,"unit":"g"},{"name":"Lechuga","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Mezclar la carne con cebolla rallada, huevo y pan rallado","Formar dos hamburguesas y salpimentar","Cocinar a la plancha 4 min por lado","Montar en pan con tomate y lechuga"}', 'Hamburguesas de ternera caseras con pan, tomate y lechuga', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Forma las hamburguesas y cocínalas en la airfryer precalentada a 190°C durante 12-15 minutos, volteándolas a mitad de cocción para un dorado uniforme. Quedan jugosas por dentro y con una capa exterior ligeramente crujiente."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Prepara las hamburguesas y hornéalas en una bandeja con papel de horno a 200°C durante 15-20 minutos, volteándolas una vez. Es una opción práctica para cocinar varias a la vez, manteniendo la carne tierna y jugosa."}]'::jsonb, '{}'),
  ('carnes_010', 'Pollo con pimientos', 'carnes', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'principal', NULL, NULL, 40, 'facil', 'all', 382, 34, 12, 22, 2, true, true, '{}', '[{"name":"Pollo troceado","amount":500,"unit":"g"},{"name":"Pimiento rojo","amount":120,"unit":"g"},{"name":"Pimiento verde","amount":120,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Dorar el pollo salpimentado en aceite","Retirar y sofreír cebolla, ajo y pimientos","Añadir tomate y devolver el pollo","Tapar y cocer 25 min a fuego medio"}', 'Pollo guisado con pimientos rojos y verdes en salsa de tomate', '[{"appliance":"horno","time":50,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo, dora el pollo en una sartén. Coloca todo en una fuente de horno con los pimientos y el tomate triturado. Hornea a 180°C durante unos 45-50 minutos, removiendo a mitad para una cocción uniforme."},{"appliance":"thermomix","time":45,"difficulty":"facil","prepSummary":"Trocea las verduras y sofríelas en el vaso. Añade el pollo y sofríe brevemente. Incorpora el tomate y cocina todo a temperatura Varoma, giro inverso, velocidad cuchara durante unos 30-35 minutos hasta que el pollo esté tierno."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo en la olla abierta, dora el pollo y añade los pimientos y el tomate. Cierra la olla y cocina a presión durante 10-12 minutos desde que sube la válvula, luego despresuriza y sirve."}]'::jsonb, '{}'),
  ('carnes_011', 'Costillas de cerdo al horno', 'carnes', 'cerdo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, 'horno', 75, 'facil', 'all', 528, 32, 8, 42, 2, true, true, '{}', '[{"name":"Costillas de cerdo","amount":500,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Miel","amount":20,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón","amount":5,"unit":"g"},{"name":"Romero","amount":3,"unit":"g"}]'::jsonb, '{"Marinar costillas con ajo, miel, limón, pimentón y romero","Colocar en bandeja de horno con aceite","Hornear a 180°C tapadas con papel de aluminio 45 min","Destapar y gratinar 15 min hasta dorar"}', 'Costillas de cerdo al horno con miel, limón y pimentón', '[{"appliance":"horno","time":75,"difficulty":"facil","prepSummary":"Marinar las costillas con ajo, miel, limón, aceite, pimentón y romero. Hornear a 180°C durante 75 minutos, volteando a mitad para asegurar un glaseado uniforme y una cocción perfecta."},{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"Marinar las costillas con la mezcla de especias y miel. Cocinar en la airfryer a 190°C durante 35 minutos, volteando y pincelando con la marinada a mitad para un acabado dorado y jugoso."}]'::jsonb, '{}'),
  ('carnes_012', 'San Jacobos caseros', 'carnes', 'cerdo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 25, 'facil', 'all', 498, 36, 20, 30, 2, true, true, '{"gluten","huevo","lactosa"}', '[{"name":"Lomo de cerdo en filetes","amount":250,"unit":"g"},{"name":"Jamón cocido","amount":60,"unit":"g"},{"name":"Queso en lonchas","amount":60,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Pan rallado","amount":50,"unit":"g"},{"name":"Harina","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Rellenar cada filete con jamón y queso y cerrar","Pasar por harina, huevo y pan rallado","Freír en aceite caliente hasta dorar","Escurrir sobre papel absorbente"}', 'Filetes de lomo rellenos de jamón y queso, empanados y fritos', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Rocía ligeramente los San Jacobos empanados con aceite y cocínalos durante 15-18 minutos, dándoles la vuelta a mitad del tiempo, hasta que estén dorados y crujientes."},{"appliance":"horno","time":22,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Coloca los San Jacobos empanados en una bandeja con papel de horno, rociándolos con un poco de aceite. Hornea durante 20-25 minutos, volteándolos a mitad, hasta que estén dorados y bien cocidos."}]'::jsonb, '{}'),
  ('carnes_013', 'Muslos de pollo al horno', 'carnes', 'pollo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, 'horno', 50, 'facil', 'all', 418, 34, 6, 28, 2, true, true, '{}', '[{"name":"Muslos de pollo","amount":500,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Tomillo","amount":3,"unit":"g"}]'::jsonb, '{"Salpimentar los muslos y colocar en bandeja","Rodear con cebolla en gajos y ajos aplastados","Regar con aceite y vino, espolvorear tomillo","Hornear a 190°C durante 40 min"}', 'Muslos de pollo asados al horno con cebolla y tomillo', '[{"appliance":"horno","time":60,"difficulty":"facil","prepSummary":"Precalentar el horno a 190°C. Dorar los muslos en una fuente apta, añadir la cebolla, ajo, vino blanco y tomillo. Hornear durante 40-50 minutos, volteando a mitad, hasta que estén tiernos, dorados y la salsa ligeramente reducida."},{"appliance":"airfryer","time":40,"difficulty":"normal","prepSummary":"Precalentar la airfryer a 180°C. Cocinar los muslos con aceite, sal y tomillo durante 20 minutos. Luego, añadir la cebolla, ajo y vino blanco en la cesta o en un recipiente apto, y cocinar 10-15 minutos más hasta que el pollo esté crujiente y las verduras tiernas."},{"appliance":"olla_express","time":35,"difficulty":"normal","prepSummary":"Dorar los muslos en la olla express con aceite. Añadir la cebolla, ajo, vino blanco y tomillo. Cerrar la olla y cocinar a presión durante 12-15 minutos. Dejar despresurizar, obteniendo un pollo muy tierno con una salsa concentrada."}]'::jsonb, '{}'),
  ('carnes_014', 'Filetes rusos', 'carnes', 'ternera', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 25, 'facil', 'all', 392, 28, 14, 24, 2, true, true, '{"gluten","huevo"}', '[{"name":"Carne picada de ternera","amount":300,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Pan rallado","amount":25,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Mezclar carne con cebolla rallada, huevo, pan rallado y perejil","Formar óvalos aplastados","Cocinar a la plancha con aceite 4 min por lado","Servir con guarnición"}', 'Filetes rusos de ternera con cebolla y perejil a la plancha', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Mezcla los ingredientes, forma los filetes y rocíalos ligeramente con aceite. Cocina en la airfryer precalentada a 190°C durante 18-20 minutos, dándoles la vuelta a mitad de cocción para un dorado uniforme y una textura jugosa."},{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Prepara la mezcla y forma los filetes. Colócalos en una bandeja de horno con papel de hornear y un chorrito de aceite. Hornea a 200°C durante 25-30 minutos, hasta que estén dorados por fuera y bien cocidos por dentro."}]'::jsonb, '{}'),
  ('carnes_015', 'Ternera guisada con zanahorias', 'carnes', 'ternera', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'principal', 'carnes_005', NULL, 80, 'normal', 'invierno', 442, 36, 16, 24, 2, true, true, '{}', '[{"name":"Carne de ternera para guisar","amount":350,"unit":"g"},{"name":"Zanahoria","amount":200,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Vino tinto","amount":80,"unit":"ml"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Sellar la carne en aceite bien caliente","Pochar cebolla y ajo, añadir tomate","Devolver la carne, añadir vino y laurel","Cocer 50 min, añadir zanahoria y cocer 20 min más"}', 'Ternera guisada a fuego lento con abundante zanahoria', '[{"appliance":"horno","time":100,"difficulty":"normal","prepSummary":"Dora la ternera y sofríe las verduras en una cazuela apta para horno. Añade el resto de ingredientes, cubre y cocina a 160°C durante 80-90 minutos hasta que la carne esté tierna y la salsa reducida."},{"appliance":"thermomix","time":80,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el ajo, luego dora la ternera en el vaso. Incorpora el resto de ingredientes y cocina a 100°C, velocidad cuchara, giro inverso, durante 70-80 minutos, o hasta que la carne esté muy tierna."},{"appliance":"olla_express","time":50,"difficulty":"normal","prepSummary":"Dora la ternera y sofríe las verduras en la olla. Añade el vino, tomate y laurel. Cierra la olla y cocina a presión media-alta durante unos 35-40 minutos, dejando que se despresurice sola para una ternera muy tierna."}]'::jsonb, '{}'),
  ('carnes_016', 'Pollo en pepitoria', 'carnes', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'principal', NULL, NULL, 50, 'normal', 'all', 466, 36, 8, 32, 2, true, true, '{"huevo","frutos_secos"}', '[{"name":"Pollo troceado","amount":500,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Almendras","amount":30,"unit":"g"},{"name":"Huevo cocido","amount":1,"unit":"ud"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Azafrán","amount":1,"unit":"g"}]'::jsonb, '{"Dorar el pollo en aceite y reservar","Sofreír cebolla, hacer majada de almendras, ajo, azafrán y yema","Devolver el pollo con vino y caldo","Cocer 25 min, añadir la majada y espesar"}', 'Pollo guisado en salsa de almendras, azafrán y huevo cocido', '[{"appliance":"horno","time":65,"difficulty":"normal","prepSummary":"Dora el pollo y sofríe la cebolla y el ajo en una cazuela apta para horno. Añade el vino, azafrán y líquido, luego cocina tapado en el horno a 170°C durante 45-50 min. Prepara la picada de almendras y huevo cocido aparte y añádela al final para espesar la salsa."},{"appliance":"thermomix","time":50,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el ajo, luego dora el pollo en el vaso. Incorpora el vino, azafrán y líquido, y cocina a temperatura Varoma, giro inverso, velocidad cuchara durante 30-35 min. Tritura las almendras y el huevo cocido con parte de la salsa y reincorpora para espesar."},{"appliance":"olla_express","time":40,"difficulty":"normal","prepSummary":"Dora el pollo y sofríe la cebolla y el ajo en la olla abierta. Añade el vino, azafrán y líquido, cierra y cocina a presión durante 15-20 min. Libera la presión, prepara la picada de almendras y huevo cocido aparte y mézclala con la salsa para espesarla."}]'::jsonb, '{}'),
  ('carnes_017', 'Magro con tomate', 'carnes', 'cerdo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 30, 'facil', 'all', 368, 32, 10, 22, 2, true, true, '{}', '[{"name":"Magro de cerdo","amount":300,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"ml"},{"name":"Pimiento verde","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Cortar el magro en taquitos y dorar en aceite","Añadir cebolla, ajo y pimiento, sofreír","Incorporar tomate triturado","Cocer a fuego lento 15 min"}', 'Taquitos de magro de cerdo guisados en salsa de tomate', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Sofríe la cebolla, pimiento y ajo en una cazuela apta para horno. Añade el magro y dora. Incorpora el tomate triturado, tapa y hornea a 180°C durante 30 minutos hasta que la carne esté tierna y la salsa reducida."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Trocea las verduras y sofríelas. Añade el magro y dora. Incorpora el tomate triturado y cocina a fuego lento (Varoma, giro inverso, velocidad cuchara) durante 20 minutos hasta que la carne esté tierna y la salsa ligada."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Dora el magro en la olla express. Retira y sofríe las verduras. Vuelve a añadir el magro con el tomate triturado, cierra la olla y cocina 10-12 minutos desde que sube la válvula. Despresuriza y sirve."}]'::jsonb, '{}'),
  ('carnes_018', 'Secreto ibérico a la plancha', 'carnes', 'cerdo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 412, 28, 1, 32, 2, true, false, '{}', '[{"name":"Secreto ibérico","amount":350,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Romero","amount":2,"unit":"g"}]'::jsonb, '{"Atemperar la carne 30 min fuera de la nevera","Salpimentar generosamente","Cocinar a la plancha muy caliente 3 min por lado","Dejar reposar 3 min tapada antes de cortar"}', 'Secreto ibérico a la plancha, jugoso y rosado por dentro', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Marina el secreto con aceite, ajo y romero. Precalienta la airfryer a 190-200°C y cocina durante 16-18 minutos, dándole la vuelta a mitad para un dorado uniforme y jugosidad."},{"appliance":"horno","time":22,"difficulty":"facil","prepSummary":"Precalienta el horno a 200-220°C. Marina el secreto y colócalo en una bandeja. Hornea durante 20-25 minutos, girándolo a mitad de cocción para un resultado tierno y ligeramente dorado."}]'::jsonb, '{}'),
  ('carnes_019', 'Alitas de pollo al horno', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, 'horno', 45, 'facil', 'all', 386, 28, 6, 28, 2, true, true, '{}', '[{"name":"Alitas de pollo","amount":500,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Pimentón","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Miel","amount":15,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Marinar alitas con ajo, pimentón, miel y limón","Colocar en bandeja con aceite","Hornear a 200°C durante 35 min dando la vuelta a mitad","Servir con el jugo de la bandeja"}', 'Alitas de pollo al horno con miel, limón y pimentón', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Marinar las alitas con los ingredientes. Hornear a 200°C durante 45 minutos, dándoles la vuelta a mitad de cocción para un dorado uniforme y una piel crujiente."},{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Tras marinar, cocinar las alitas en la airfryer a 190-200°C durante 20-25 minutos, agitándolas o dándoles la vuelta varias veces para una cocción y dorado homogéneos."}]'::jsonb, '{}'),
  ('carnes_020', 'Solomillo de cerdo al Pedro Ximénez', 'carnes', 'cerdo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 30, 'normal', 'all', 388, 34, 12, 18, 2, true, true, '{"lactosa"}', '[{"name":"Solomillo de cerdo","amount":350,"unit":"g"},{"name":"Pedro Ximénez","amount":80,"unit":"ml"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Champiñones","amount":100,"unit":"g"},{"name":"Nata","amount":40,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Sellar el solomillo entero en aceite y reservar","Sofreír cebolla y champiñones","Añadir Pedro Ximénez y reducir a la mitad","Devolver el solomillo, añadir nata y cocer 10 min"}', 'Solomillo de cerdo en salsa de Pedro Ximénez con champiñones', '[{"appliance":"airfryer","time":30,"difficulty":"normal","prepSummary":"Sella el solomillo en la airfryer a 190°C durante 15-20 minutos, dándole la vuelta a mitad. Mientras, sofríe la cebolla y los champiñones en una sartén, añade el Pedro Ximénez y la nata, y reduce la salsa hasta que espese."},{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Sella el solomillo en una sartén apta para horno, luego añade la cebolla y champiñones y hornea a 180°C durante 25-30 minutos. Retira el solomillo, deglasea la bandeja con Pedro Ximénez y nata para la salsa."},{"appliance":"thermomix","time":35,"difficulty":"normal","prepSummary":"Sofríe la cebolla y champiñones en el vaso, luego añade el solomillo troceado y el Pedro Ximénez, cocinando a temperatura Varoma o 100°C. Incorpora la nata al final y programa unos minutos más para espesar la salsa."},{"appliance":"olla_express","time":25,"difficulty":"normal","prepSummary":"Sella el solomillo en la olla abierta, retira y sofríe la cebolla y champiñones. Vuelve a añadir el solomillo, el Pedro Ximénez, cierra la olla y cocina a presión 5-7 minutos. Abre, añade la nata y reduce la salsa a fuego vivo."}]'::jsonb, '{}'),
  ('carnes_021', 'Carne guisada con verduras', 'carnes', 'ternera', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'principal', 'carnes_005', NULL, 80, 'normal', 'invierno', 428, 34, 18, 24, 2, true, true, '{}', '[{"name":"Carne de ternera para guisar","amount":300,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Judías verdes","amount":100,"unit":"g"},{"name":"Guisantes","amount":80,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vino blanco","amount":60,"unit":"ml"}]'::jsonb, '{"Sellar la carne en dados y reservar","Pochar cebolla, añadir tomate y vino","Devolver la carne con agua, cocer 50 min","Añadir verduras y cocer 15 min más"}', 'Ternera guisada con zanahoria, judías verdes y guisantes', '[{"appliance":"horno","time":100,"difficulty":"normal","prepSummary":"Sofríe la carne y las verduras en una cazuela apta para horno. Añade el resto de ingredientes, tapa y cocina a 160-170°C durante unos 90-100 minutos hasta que la carne esté muy tierna."},{"appliance":"thermomix","time":85,"difficulty":"normal","prepSummary":"Trocea las verduras y sofríelas. Incorpora la carne para sellarla y luego añade el resto de ingredientes. Cocina a 100°C, giro inverso y velocidad cuchara durante unos 80-85 minutos hasta que la carne esté tierna."},{"appliance":"olla_express","time":35,"difficulty":"normal","prepSummary":"Sella la carne y sofríe las verduras en la olla. Añade el resto de ingredientes, cierra la olla y cocina a presión durante 25-30 minutos. Deja despresurizar de forma natural para una carne muy tierna."}]'::jsonb, '{}'),
  ('carnes_022', 'Lomo de cerdo en salsa', 'carnes', 'cerdo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 35, 'facil', 'all', 374, 32, 10, 22, 2, true, true, '{}', '[{"name":"Lomo de cerdo en filetes","amount":300,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Dorar los filetes de lomo y reservar","Sofreír cebolla y ajo, añadir tomate","Verter vino y laurel, cocer 5 min","Devolver los filetes y cocer 10 min a fuego lento"}', 'Filetes de lomo de cerdo en salsa de tomate y vino blanco', '[{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Sella el lomo en una sartén y sofríe la cebolla y el ajo. Mezcla con el resto de ingredientes en una fuente apta para horno y hornea a 180°C durante 25-30 minutos, hasta que la carne esté tierna y la salsa reducida."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Trocea la cebolla y el ajo, sofríe con aceite. Sella el lomo, añade el resto de ingredientes y cocina a temperatura Varoma, velocidad cuchara, giro inverso durante 25-30 minutos, hasta que la carne esté hecha y la salsa ligada."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sella el lomo y sofríe la cebolla y el ajo en la olla. Añade el resto de ingredientes, cierra la olla y cocina a presión durante 8-10 minutos. Despresuriza y si es necesario, reduce la salsa sin tapa."}]'::jsonb, '{}'),
  ('carnes_023', 'Escalopines de ternera al limón', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 338, 32, 6, 20, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Escalopines de ternera","amount":300,"unit":"g"},{"name":"Harina","amount":15,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Enharinar ligeramente los escalopines","Dorar en aceite y mantequilla 2 min por lado","Retirar y hacer salsa con zumo de limón en la sartén","Verter la salsa sobre la carne y espolvorear perejil"}', 'Escalopines finos de ternera en salsa de limón y mantequilla', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190-200°C. Enharina los escalopines y rocíalos ligeramente con aceite de oliva. Cocina durante 10-12 minutos, dándoles la vuelta a mitad de cocción, hasta que estén dorados y tiernos. La salsa de limón y mantequilla se prepara aparte en una sartén."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Enharina los escalopines y colócalos en una bandeja de horno ligeramente engrasada. Hornea durante 15-20 minutos, volteándolos una vez, hasta que estén dorados y cocidos. Prepara la salsa de limón y mantequilla en una sartén y viértela sobre los escalopines justo antes de servir."}]'::jsonb, '{}'),
  ('carnes_024', 'Pavo a la plancha', 'carnes', 'pavo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 278, 38, 2, 12, 2, true, true, '{}', '[{"name":"Pechuga de pavo","amount":350,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Ajo en polvo","amount":3,"unit":"g"},{"name":"Orégano","amount":2,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Cortar la pechuga en filetes finos","Sazonar con ajo en polvo y orégano","Cocinar a la plancha con aceite 3 min por lado","Servir con limón"}', 'Filetes de pechuga de pavo a la plancha con hierbas', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Marinar el pavo con aceite y especias. Cocinar en la airfryer precalentada a 190-200°C durante 15-18 minutos, dándole la vuelta a mitad para un dorado uniforme y un interior jugoso."},{"appliance":"horno","time":22,"difficulty":"facil","prepSummary":"Precalentar el horno a 200°C. Colocar el pavo marinado en una bandeja y hornear durante 20-25 minutos, hasta que esté cocido y ligeramente dorado. Se puede usar la función grill al final para un mejor acabado."}]'::jsonb, '{}'),
  ('carnes_025', 'Pollo al curry', 'carnes', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'principal', NULL, NULL, 35, 'facil', 'all', 396, 34, 14, 22, 2, false, true, '{"lactosa"}', '[{"name":"Pechuga de pollo","amount":350,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Nata","amount":60,"unit":"ml"},{"name":"Curry en polvo","amount":8,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Dorar el pollo en dados en aceite","Sofreír cebolla y ajo, añadir curry","Incorporar tomate y cocer 10 min","Añadir nata y el pollo, cocer 10 min más"}', 'Pollo en salsa de curry suave con tomate y nata', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo en una olla apta para horno. Incorpora el pollo y dora ligeramente. Añade el tomate triturado y el curry, y hornea a 180°C durante 25-30 minutos. Termina con la nata fuera del horno para una salsa cremosa."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Pica la cebolla y el ajo, sofríe. Añade el pollo troceado y dora. Incorpora el tomate triturado y el curry, y cocina a 100°C, giro inverso, velocidad cuchara durante 20-25 minutos. Añade la nata al final y mezcla suavemente."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo, dora el pollo en la olla. Añade el tomate triturado y el curry, cierra la olla y cocina a presión durante 8-10 minutos. Despresuriza, incorpora la nata y cocina unos minutos más sin tapa para espesar la salsa."}]'::jsonb, '{}'),
  ('carnes_026', 'Albóndigas de pollo', 'carnes', 'pollo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 35, 'normal', 'all', 378, 32, 16, 20, 2, true, true, '{"gluten","huevo"}', '[{"name":"Carne picada de pollo","amount":300,"unit":"g"},{"name":"Pan rallado","amount":25,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"}]'::jsonb, '{"Mezclar carne de pollo con huevo, pan rallado y ajo","Formar albóndigas pequeñas","Hacer salsa con cebolla, zanahoria y tomate","Incorporar las albóndigas y cocer 20 min"}', 'Albóndigas de pollo en salsa de tomate con zanahoria', '[{"appliance":"airfryer","time":35,"difficulty":"normal","prepSummary":"Forma las albóndigas y cocínalas en la airfryer a 190°C durante 15-20 minutos, girándolas a mitad, hasta que estén doradas. Mientras, prepara la salsa en una sartén y luego incorpora las albóndigas para que se impregnen bien."},{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Hornea las albóndigas a 180°C durante 15 minutos para dorarlas. Luego, transfiérelas a una fuente con la salsa ya preparada (o con los ingredientes de la salsa) y hornea todo junto 20-25 minutos más a 170°C para que los sabores se integren."},{"appliance":"thermomix","time":45,"difficulty":"normal","prepSummary":"Pica las verduras en el vaso. Prepara la salsa sofriendo las verduras y añadiendo el tomate. Luego, incorpora las albóndigas (previamente formadas) al vaso y cocina a temperatura Varoma, velocidad cuchara, giro inverso, durante 20-25 minutos para que se hagan en la salsa."},{"appliance":"olla_express","time":35,"difficulty":"normal","prepSummary":"Dora las albóndigas en la olla express con un poco de aceite. Retira, sofríe la cebolla, zanahoria y ajo. Añade el tomate, reincorpora las albóndigas y un poco de agua si es necesario. Cierra la olla y cocina 10-12 minutos desde que sube la válvula."}]'::jsonb, '{}'),
  ('carnes_027', 'Chuletas de cerdo a la plancha', 'carnes', 'cerdo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 402, 30, 1, 30, 2, true, false, '{}', '[{"name":"Chuletas de cerdo","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Romero","amount":2,"unit":"g"}]'::jsonb, '{"Salpimentar las chuletas con ajo y romero","Calentar la plancha a fuego fuerte","Cocinar 4 min por cada lado","Dejar reposar 2 min antes de servir"}', 'Chuletas de cerdo a la plancha con ajo y romero', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Marinar las chuletas con aceite, ajo y romero. Precalentar la airfryer a 190-200°C y cocinar durante 15-18 minutos, dándoles la vuelta a mitad para un dorado uniforme y jugosidad."},{"appliance":"horno","time":22,"difficulty":"facil","prepSummary":"Marinar las chuletas. Precalentar el horno a 200-220°C con función grill si es posible. Colocar en una bandeja con rejilla y cocinar unos 20-25 minutos, volteándolas a mitad para que se doren por ambos lados."}]'::jsonb, '{}'),
  ('carnes_028', 'Pollo con champiñones', 'carnes', 'pollo', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 30, 'facil', 'all', 362, 36, 8, 20, 2, true, true, '{}', '[{"name":"Pechuga de pollo","amount":350,"unit":"g"},{"name":"Champiñones","amount":200,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Dorar el pollo en filetes y reservar","Saltear champiñones con cebolla y ajo","Añadir vino blanco y dejar reducir","Devolver el pollo y cocer 5 min con perejil"}', 'Pechugas de pollo con champiñones salteados al vino blanco', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Cocina el pollo y los champiñones en la airfryer a 190°C por 15-20 minutos, dándoles la vuelta. Prepara la cebolla, ajo y vino en una sartén aparte y mezcla todo al final para integrar los sabores."},{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Combina el pollo, champiñones, cebolla, ajo y aceite en una fuente apta para horno. Hornea a 180°C durante 25-30 minutos, añadiendo el vino blanco a mitad de cocción para que los sabores se integren."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Trocea la cebolla y el ajo, sofríelos. Añade el pollo y los champiñones, cocina con el vino blanco a temperatura Varoma/100°C hasta que el pollo esté tierno y la salsa reducida."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo en la olla. Incorpora el pollo y los champiñones, añade el vino y cocina a presión durante 8-10 minutos. Deja despresurizar y sirve."}]'::jsonb, '{}'),
  ('carnes_029', 'Redondo de ternera', 'carnes', 'ternera', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'principal', NULL, NULL, 90, 'normal', 'all', 412, 38, 14, 22, 2, true, true, '{}', '[{"name":"Redondo de ternera","amount":400,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Vino tinto","amount":100,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Tomate triturado","amount":80,"unit":"ml"}]'::jsonb, '{"Sellar el redondo entero en aceite bien caliente","Dorar cebolla, zanahoria y ajo alrededor","Añadir vino, tomate, laurel y agua, tapar","Cocer a fuego lento 1 h 15 min, cortar en rodajas"}', 'Redondo de ternera guisado entero con verduras y vino tinto', '[{"appliance":"horno","time":100,"difficulty":"normal","prepSummary":"Sella la ternera en una cazuela apta para horno. Rehoga las verduras, añade el vino, tomate y laurel. Tapa y hornea a 160-170°C durante 80-90 minutos hasta que la carne esté tierna y la salsa reducida."},{"appliance":"thermomix","time":75,"difficulty":"normal","prepSummary":"Sella la ternera (en Thermomix o aparte). Sofreír las verduras. Incorpora la carne, el vino, tomate y laurel. Cocina a 100°C, giro inverso, velocidad cuchara, durante 60-70 minutos hasta que la carne esté tierna."},{"appliance":"olla_express","time":55,"difficulty":"normal","prepSummary":"Sella la ternera en la olla express. Sofreír las verduras. Añade el vino, tomate y laurel. Cierra y cocina a presión durante 35-40 minutos. Deja despresurizar naturalmente para una carne más jugosa."}]'::jsonb, '{}'),
  ('carnes_030', 'Brochetas de pollo', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 25, 'facil', 'verano', 342, 36, 10, 16, 2, true, false, '{}', '[{"name":"Pechuga de pollo","amount":350,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Pimiento verde","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Orégano","amount":3,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Cortar pollo y verduras en dados de 3 cm","Ensartar alternando pollo y verduras","Aliñar con aceite, orégano y limón","Cocinar a la plancha 10 min girando"}', 'Brochetas de pollo con pimientos y cebolla a la plancha', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Cocina las brochetas durante 18-22 minutos, volteándolas a mitad de cocción, hasta que el pollo esté dorado y las verduras tiernas y ligeramente caramelizadas."},{"appliance":"horno","time":28,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Coloca las brochetas en una bandeja con papel de horno y ásalas durante 25-30 minutos, dándoles la vuelta una vez para una cocción uniforme y un buen dorado."}]'::jsonb, '{}'),
  ('carnes_031', 'Fricandó de ternera', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 70, 'normal', 'invierno', 398, 34, 12, 22, 2, true, true, '{"gluten"}', '[{"name":"Filetes finos de ternera","amount":300,"unit":"g"},{"name":"Setas","amount":150,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Vino rancio","amount":60,"unit":"ml"},{"name":"Harina","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Enharinar y dorar los filetes en aceite","Sofreír cebolla y tomate","Añadir vino, laurel y las setas","Devolver la carne y cocer 40 min a fuego lento"}', 'Filetes finos de ternera guisados con setas al estilo catalán', '[{"appliance":"horno","time":80,"difficulty":"normal","prepSummary":"Dora los filetes y sofríe la cebolla y setas en una olla apta para horno. Añade el vino, tomate, harina y laurel. Cubre y hornea a 160°C durante 60-70 minutos hasta que la ternera esté muy tierna y la salsa ligada."},{"appliance":"thermomix","time":65,"difficulty":"normal","prepSummary":"Sofríe la cebolla y setas. Incorpora la ternera en trozos para dorar ligeramente. Añade el vino, tomate, harina y laurel. Cocina a 100°C, velocidad cuchara, giro inverso, durante 50-60 minutos hasta que la carne esté tierna y la salsa espesa."},{"appliance":"olla_express","time":45,"difficulty":"normal","prepSummary":"Dora la ternera y sofríe la cebolla y setas en la olla. Añade el vino, tomate, harina y laurel. Cierra la olla y cocina a presión durante 20-25 minutos. Despresuriza y si es necesario, reduce la salsa a fuego vivo."}]'::jsonb, '{}'),
  ('carnes_032', 'Escalope de pollo', 'carnes', 'pollo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 424, 36, 22, 22, 2, true, true, '{"gluten","huevo"}', '[{"name":"Pechuga de pollo","amount":350,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Pan rallado","amount":50,"unit":"g"},{"name":"Harina","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Aplanar las pechugas finamente","Pasar por harina, huevo batido y pan rallado","Freír en aceite caliente 3 min por lado","Escurrir y servir con limón"}', 'Pechuga de pollo aplastada, empanada y frita', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Rocía los escalopes empanados con un poco de aceite en spray y cocina durante 12-15 minutos, volteando a mitad, hasta que estén dorados y crujientes."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Coloca los escalopes empanados en una bandeja con papel de horno, rocía con un poco de aceite y hornea 20-25 minutos, volteando una vez, hasta que estén cocidos y ligeramente dorados."}]'::jsonb, '{}'),
  ('carnes_033', 'Ragú de ternera', 'carnes', 'ternera', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 90, 'normal', 'invierno', 436, 34, 16, 26, 2, true, true, '{"apio"}', '[{"name":"Carne de ternera para guisar","amount":350,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Apio","amount":50,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Vino tinto","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Sellar la carne en dados en aceite","Sofreír cebolla, zanahoria y apio picados","Añadir tomate, vino y laurel","Cocer tapado a fuego lento 1 h 15 min"}', 'Ragú espeso de ternera con sofrito de verduras y vino tinto', '[{"appliance":"horno","time":120,"difficulty":"normal","prepSummary":"Primero, sella la carne y sofríe las verduras en una olla apta para horno. Luego, añade el resto de ingredientes, cubre y hornea a 160°C durante 1 hora y 45 minutos, removiendo ocasionalmente, para un ragú tierno y lleno de sabor."},{"appliance":"thermomix","time":80,"difficulty":"normal","prepSummary":"Pica las verduras y sofríelas en el vaso con aceite. Añade la carne (previamente sellada para mejor resultado), el vino y el resto de ingredientes. Cocina 70 minutos a 95°C, giro inverso, velocidad cuchara, para un ragú meloso y bien integrado."},{"appliance":"olla_express","time":50,"difficulty":"normal","prepSummary":"Sella la carne y sofríe las verduras en la olla. Incorpora el resto de ingredientes, cierra la olla y cocina a presión (segundo anillo) durante 35 minutos desde que sube la válvula, para un ragú con carne muy tierna en tiempo récord."}]'::jsonb, '{}'),
  ('carnes_034', 'Pollo a la cerveza', 'carnes', 'pollo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'principal', NULL, NULL, 45, 'facil', 'all', 408, 34, 10, 24, 2, true, true, '{"gluten"}', '[{"name":"Pollo troceado","amount":500,"unit":"g"},{"name":"Cerveza","amount":200,"unit":"ml"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Dorar el pollo salpimentado en aceite","Añadir cebolla en juliana y ajo","Verter la cerveza y añadir laurel","Tapar y cocer a fuego lento 30 min"}', 'Pollo troceado guisado en salsa de cerveza con cebolla', '[{"appliance":"horno","time":55,"difficulty":"facil","prepSummary":"Dora el pollo y las verduras en una cazuela apta para horno. Añade la cerveza y el laurel, tapa y cocina a 180°C durante 40-45 minutos. Destapa los últimos 10 minutos para que la salsa espese."},{"appliance":"thermomix","time":45,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo, luego dora ligeramente el pollo en el vaso. Incorpora la cerveza y el laurel, y cocina a 100°C, giro inverso, velocidad cuchara, durante 35-40 minutos hasta que el pollo esté tierno."},{"appliance":"olla_express","time":30,"difficulty":"facil","prepSummary":"Dora el pollo y sofríe la cebolla y el ajo en la olla. Vierte la cerveza y el laurel, cierra la olla y cocina a presión durante 15-20 minutos. Si la salsa está muy líquida, redúcela unos minutos sin tapa."}]'::jsonb, '{}'),
  ('carnes_035', 'Flamenquines cordobeses', 'carnes', 'cerdo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 25, 'normal', 'all', 512, 34, 22, 32, 2, true, true, '{"gluten","huevo"}', '[{"name":"Lomo de cerdo en filetes","amount":250,"unit":"g"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Pan rallado","amount":50,"unit":"g"},{"name":"Harina","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":50,"unit":"ml"}]'::jsonb, '{"Enrollar cada filete con jamón serrano dentro","Sujetar con palillos","Pasar por harina, huevo y pan rallado","Freír en aceite caliente hasta dorar"}', 'Rollitos de lomo rellenos de jamón serrano, empanados y fritos', '[{"appliance":"airfryer","time":20,"difficulty":"normal","prepSummary":"Precalienta la airfryer a 190-200°C. Rocía ligeramente los flamenquines con aceite de oliva y cocina durante unos 15-20 minutos, dándoles la vuelta a mitad de cocción, hasta que estén dorados y crujientes."},{"appliance":"horno","time":30,"difficulty":"normal","prepSummary":"Precalienta el horno a 200°C con calor arriba y abajo. Coloca los flamenquines en una bandeja con papel de horno, rocíalos con un poco de aceite y hornea durante 25-30 minutos, volteándolos a mitad de cocción, hasta que estén dorados."}]'::jsonb, '{}'),
  ('cenas_rapidas_001', 'Sándwich mixto', 'cenas_rapidas', 'none', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 348, 16, 32, 18, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Pan de molde","amount":4,"unit":"ud"},{"name":"Jamón cocido","amount":80,"unit":"g"},{"name":"Queso en lonchas","amount":60,"unit":"g"},{"name":"Mantequilla","amount":10,"unit":"g"}]'::jsonb, '{"Untar las rebanadas con mantequilla","Rellenar con jamón y queso","Tostar en sandwichera o sartén","Cortar en diagonal y servir"}', 'Sándwich tostado de jamón cocido y queso fundido', '[{"appliance":"airfryer","time":9,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Unta el pan con mantequilla, monta el sándwich y cocina durante 8-10 minutos, dándole la vuelta a mitad para un dorado uniforme y queso bien fundido."},{"appliance":"horno","time":12,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con calor arriba y abajo. Unta el pan con mantequilla, monta el sándwich y hornea sobre papel de horno durante 10-12 minutos, o hasta que esté dorado y el queso fundido."}]'::jsonb, '{}'),
  ('cenas_rapidas_002', 'Tosta de tomate con jamón', 'cenas_rapidas', 'none', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 312, 14, 30, 16, 2, true, false, '{"gluten"}', '[{"name":"Pan de hogaza","amount":150,"unit":"g"},{"name":"Tomate maduro","amount":150,"unit":"g"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Tostar las rebanadas de pan","Frotar con tomate maduro partido por la mitad","Añadir un chorrito de aceite y sal","Colocar el jamón encima"}', 'Pan tostado con tomate rallado, aceite y jamón serrano', '[{"appliance":"airfryer","time":10,"difficulty":"facil","prepSummary":"Tuesta las rebanadas de pan en la airfryer a 180°C durante 4-6 minutos, hasta que estén doradas y crujientes. Después, unta el tomate maduro sobre el pan tostado, añade el jamón serrano y finaliza con un chorrito de aceite de oliva virgen extra."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C, preferiblemente con función grill. Tuesta las rebanadas de pan durante 5-8 minutos hasta que estén bien doradas. Una vez tostadas, unta el tomate maduro, coloca el jamón serrano y rocía con aceite de oliva."}]'::jsonb, '{}'),
  ('cenas_rapidas_003', 'Ensalada de quinoa', 'cenas_rapidas', 'none', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'verano', 328, 12, 38, 14, 2, true, true, '{}', '[{"name":"Quinoa","amount":140,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Tomate cherry","amount":100,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Cocer la quinoa 15 min y escurrir, enfriar","Cortar pepino, tomates y aguacate en dados","Mezclar todo con la quinoa","Aliñar con aceite, limón y sal"}', 'Ensalada fría de quinoa con aguacate, pepino y tomate', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Cocina la quinoa con agua en el vaso del Thermomix (15-20 min, 100°C, velocidad cuchara). Mientras, pica los vegetales y mezcla todo con el aderezo."},{"appliance":"vaporera","time":25,"difficulty":"facil","prepSummary":"Coloca la quinoa con el doble de agua en un recipiente apto para vaporera y cocina al vapor durante 20-25 minutos hasta que esté tierna. Luego, mezcla con los vegetales frescos y el aderezo."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Cocina la quinoa con el doble de agua en la olla express durante 5-7 minutos desde que sube la válvula. Deja despresurizar y luego mezcla con los ingredientes frescos y el aliño."},{"appliance":"microondas","time":15,"difficulty":"facil","prepSummary":"Combina la quinoa con el doble de agua en un recipiente apto para microondas, tapa y cocina a máxima potencia durante 10-12 minutos, o hasta que el agua se absorba. Mezcla con el resto de ingredientes."}]'::jsonb, '{}'),
  ('cenas_rapidas_004', 'Pan tumaca con embutido', 'cenas_rapidas', 'none', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 368, 16, 32, 20, 2, true, false, '{"gluten"}', '[{"name":"Pan de payés","amount":150,"unit":"g"},{"name":"Tomate maduro","amount":120,"unit":"g"},{"name":"Fuet","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Cortar el pan en rebanadas y tostar ligeramente","Frotar con tomate partido por la mitad","Aliñar con aceite y una pizca de sal","Acompañar con fuet en rodajas"}', 'Pan catalán con tomate rallado, aceite y fuet', '[{"appliance":"airfryer","time":8,"difficulty":"facil","prepSummary":"Tuesta el pan de payés en la airfryer a 180-200°C durante 3-5 minutos hasta que esté dorado y crujiente. Mientras, ralla el tomate y corta el fuet. Monta el pan con tomate, aceite y fuet."},{"appliance":"horno","time":12,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Tuesta las rebanadas de pan durante 4-6 minutos hasta que estén doradas. Ralla el tomate, aliña con aceite y monta sobre el pan tostado con el fuet."}]'::jsonb, '{}'),
  ('cenas_rapidas_005', 'Tostada de aguacate y tomate', 'cenas_rapidas', 'none', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 298, 6, 28, 18, 2, true, false, '{"gluten"}', '[{"name":"Pan de hogaza","amount":120,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Tomate cherry","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Tostar las rebanadas de pan","Aplastar el aguacate con limón y sal","Untar sobre el pan","Decorar con tomates cherry cortados por la mitad"}', 'Tostada de pan con aguacate machacado y tomate cherry', '[{"appliance":"airfryer","time":10,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Tuesta el pan durante 5-7 minutos, volteándolo a mitad, hasta que esté crujiente y dorado. Un truco es rociar un poco de aceite de oliva antes de tostar para un extra de sabor."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C, preferiblemente con función grill. Tuesta el pan directamente sobre la rejilla durante 5-7 minutos, vigilando que no se queme, para un tostado uniforme. Monta la tostada con el resto de ingredientes."}]'::jsonb, '{}'),
  ('cenas_rapidas_006', 'Salchichas con puré', 'cenas_rapidas', 'cerdo', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 452, 18, 32, 28, 2, true, true, '{"lactosa"}', '[{"name":"Salchichas frescas","amount":250,"unit":"g"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Leche","amount":60,"unit":"ml"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Cocer patatas 20 min y hacer puré con leche y mantequilla","Cocinar las salchichas a la plancha o sartén","Dorar por todos los lados 8 min","Servir sobre el puré"}', 'Salchichas frescas a la plancha con puré de patata casero', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Para las salchichas, precalienta la airfryer a 190°C y cocínalas durante 15-20 minutos, volteándolas a mitad de cocción para que queden doradas y crujientes por fuera."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Cocina las salchichas en una bandeja de horno precalentado a 200°C durante 20-25 minutos, dándoles la vuelta una vez para un dorado uniforme y un interior jugoso."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Prepara un puré de patatas perfecto cociendo las patatas troceadas al vapor en el Varoma (20-25 min) y luego triturándolas en el vaso con la leche y mantequilla hasta lograr una textura cremosa."}]'::jsonb, '{}'),
  ('cenas_rapidas_007', 'Nachos con guacamole', 'cenas_rapidas', 'none', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 382, 8, 36, 24, 2, true, false, '{}', '[{"name":"Nachos de maíz","amount":150,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Tomate","amount":80,"unit":"g"},{"name":"Cebolla","amount":30,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Cilantro","amount":5,"unit":"g"}]'::jsonb, '{"Aplastar aguacate con tenedor","Mezclar con tomate y cebolla picados, limón y cilantro","Salpimentar el guacamole","Servir con los nachos para mojar"}', 'Nachos de maíz con guacamole casero de aguacate', '[{"appliance":"airfryer","time":10,"difficulty":"facil","prepSummary":"Para los nachos, precalienta la airfryer a 180°C y caliéntalos durante 2-3 minutos para que queden extra crujientes. Mientras, prepara el guacamole de forma tradicional."},{"appliance":"horno","time":12,"difficulty":"facil","prepSummary":"Precalienta el horno a 180°C y extiende los nachos en una bandeja. Caliéntalos durante 4-5 minutos hasta que estén ligeramente tostados y crujientes. El guacamole se prepara aparte de forma tradicional."}]'::jsonb, '{}'),
  ('cenas_rapidas_008', 'Bruschetta de tomate', 'cenas_rapidas', 'none', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 268, 6, 30, 14, 2, true, false, '{"gluten"}', '[{"name":"Pan chapata","amount":150,"unit":"g"},{"name":"Tomate maduro","amount":200,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Albahaca","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Tostar rebanadas de chapata","Frotar con ajo crudo","Cubrir con tomate en dados pequeños","Aliñar con aceite, albahaca y sal en escamas"}', 'Tostadas de pan con tomate fresco, ajo y albahaca', '[{"appliance":"airfryer","time":12,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Tuesta las rebanadas de pan durante 5-7 minutos hasta que estén doradas y crujientes, dándoles la vuelta a mitad de cocción. Esto asegura un tostado uniforme y rápido."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con calor arriba y abajo. Coloca las rebanadas de pan en una bandeja y tuéstalas durante 7-10 minutos, o hasta que estén doradas y crujientes. Vigila para que no se quemen."}]'::jsonb, '{}'),
  ('cenas_rapidas_009', 'Rollitos de jamón y queso', 'cenas_rapidas', 'none', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 262, 18, 2, 20, 2, true, true, '{"lactosa"}', '[{"name":"Jamón cocido","amount":120,"unit":"g"},{"name":"Queso en porciones","amount":80,"unit":"g"},{"name":"Pepinillos","amount":30,"unit":"g"}]'::jsonb, '{"Extender las lonchas de jamón","Colocar queso y medio pepinillo en cada una","Enrollar bien apretado","Servir fríos como picoteo o cena ligera"}', 'Lonchas de jamón cocido enrolladas con queso y pepinillo', '[]'::jsonb, '{}'),
  ('cenas_rapidas_010', 'Tabla de quesos y embutidos', 'cenas_rapidas', 'none', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 412, 22, 4, 34, 2, true, false, '{"lactosa","gluten"}', '[{"name":"Queso curado","amount":80,"unit":"g"},{"name":"Chorizo","amount":60,"unit":"g"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Aceitunas","amount":40,"unit":"g"},{"name":"Pan de barra","amount":80,"unit":"g"}]'::jsonb, '{"Cortar el queso en cuñas o tacos","Disponer chorizo y jamón en lonchas","Colocar aceitunas en un bol","Acompañar con pan cortado"}', 'Tabla para compartir con queso curado, chorizo y jamón', '[]'::jsonb, '{}'),
  ('cenas_rapidas_011', 'Ensalada caprese', 'cenas_rapidas', 'none', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'verano', 278, 14, 6, 22, 2, true, true, '{"lactosa"}', '[{"name":"Tomate","amount":250,"unit":"g"},{"name":"Mozzarella fresca","amount":125,"unit":"g"},{"name":"Albahaca","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Cortar tomate y mozzarella en rodajas del mismo grosor","Alternar en plato: tomate, mozzarella, tomate","Añadir hojas de albahaca fresca","Aliñar con aceite y sal en escamas"}', 'Ensalada italiana de tomate y mozzarella fresca con albahaca', '[]'::jsonb, '{}'),
  ('cenas_rapidas_012', 'Gazpacho con picatostes', 'cenas_rapidas', 'none', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 198, 4, 18, 12, 2, true, true, '{"gluten","sulfitos"}', '[{"name":"Tomate maduro","amount":400,"unit":"g"},{"name":"Pepino","amount":60,"unit":"g"},{"name":"Pimiento verde","amount":40,"unit":"g"},{"name":"Ajo","amount":4,"unit":"g"},{"name":"Pan","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre","amount":10,"unit":"ml"}]'::jsonb, '{"Triturar tomate, pepino, pimiento, ajo y pan remojado","Añadir aceite y vinagre emulsionando","Colar y enfriar en nevera","Servir con dados de pan tostado"}', 'Gazpacho frío servido con picatostes crujientes', '[{"appliance":"thermomix","time":10,"difficulty":"facil","prepSummary":"Introduce los tomates, pepino, pimiento, ajo, aceite y vinagre en el vaso de la Thermomix. Tritura a velocidad progresiva 5-10 durante 1-2 minutos hasta lograr una textura fina y homogénea. Sirve muy frío con los picatostes."}]'::jsonb, '{}'),
  ('cenas_rapidas_013', 'Huevos revueltos con tostadas', 'cenas_rapidas', 'huevo', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 358, 16, 28, 20, 2, true, false, '{"huevo","gluten"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Pan de hogaza","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Tomate","amount":80,"unit":"g"}]'::jsonb, '{"Batir los huevos con sal","Cuajar en sartén con aceite removiendo suavemente","Tostar las rebanadas de pan","Servir el revuelto sobre las tostadas con tomate"}', 'Huevos revueltos cremosos sobre pan tostado con tomate', '[{"appliance":"thermomix","time":10,"difficulty":"facil","prepSummary":"Para los huevos revueltos, bate los huevos con un chorrito de aceite y sal en el vaso. Cocina con la mariposa a 90°C, velocidad 2-3, durante 5-7 minutos, ajustando al gusto para una textura cremosa. Las tostadas se prepararían por separado."},{"appliance":"microondas","time":5,"difficulty":"facil","prepSummary":"Para los huevos revueltos, bate los huevos con sal y aceite en un bol apto para microondas. Cocina a máxima potencia (aprox. 800W) durante 1-2 minutos, removiendo a mitad de cocción para asegurar una textura uniforme y jugosa. Las tostadas se prepararían por separado."}]'::jsonb, '{}'),
  ('cenas_rapidas_014', 'Tortilla wrap de atún', 'cenas_rapidas', 'pescado_azul', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 368, 22, 32, 16, 2, true, true, '{"gluten","pescado","huevo"}', '[{"name":"Tortilla de trigo","amount":2,"unit":"ud"},{"name":"Atún en conserva","amount":120,"unit":"g"},{"name":"Lechuga","amount":50,"unit":"g"},{"name":"Tomate","amount":80,"unit":"g"},{"name":"Maíz dulce","amount":40,"unit":"g"},{"name":"Mayonesa","amount":20,"unit":"g"}]'::jsonb, '{"Escurrir el atún y mezclar con mayonesa","Repartir lechuga y tomate en las tortillas","Añadir atún y maíz","Enrollar bien apretado"}', 'Wrap de tortilla de trigo con atún, lechuga y maíz', '[{"appliance":"airfryer","time":12,"difficulty":"facil","prepSummary":"Para darle un toque crujiente y caliente, rellena las tortillas con los ingredientes y dóblalas. Precalienta la airfryer a 180°C y cocina los wraps durante 5-7 minutos, volteándolos a mitad, hasta que estén dorados y crujientes."}]'::jsonb, '{}'),
  ('cenas_rapidas_015', 'Sopa fría de melón', 'cenas_rapidas', 'none', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 178, 6, 22, 8, 2, true, true, '{"lactosa"}', '[{"name":"Melón","amount":400,"unit":"g"},{"name":"Jamón serrano","amount":40,"unit":"g"},{"name":"Yogur natural","amount":80,"unit":"g"},{"name":"Menta","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Triturar el melón pelado con el yogur","Añadir menta y un chorrito de aceite","Enfriar en nevera al menos 30 min","Servir con virutas de jamón por encima"}', 'Sopa fría de melón con yogur, menta y jamón serrano', '[{"appliance":"thermomix","time":10,"difficulty":"facil","prepSummary":"Introduce el melón troceado, el yogur, la menta y el aceite de oliva en el vaso. Tritura a velocidad progresiva 5-10 hasta obtener una crema fina y homogénea. Sirve muy frío, decorado con el jamón serrano."}]'::jsonb, '{}'),
  ('desayunos_001', 'Bol de yogur con fruta y avena', 'desayunos', 'none', NULL, ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 320, 13, 52, 7, 2, true, false, '{"lactosa","gluten"}', '[{"name":"Yogur natural","amount":250,"unit":"g"},{"name":"Plátano","amount":1,"unit":"ud"},{"name":"Fresas","amount":100,"unit":"g"},{"name":"Copos de avena","amount":40,"unit":"g"},{"name":"Miel","amount":15,"unit":"ml"}]'::jsonb, '{"Reparte el yogur en dos boles","Añade el plátano en rodajas y las fresas troceadas","Reparte los copos de avena por encima","Termina con un hilo de miel"}', 'Bol de yogur natural con plátano, fresas, avena y un toque de miel', NULL, '{}'),
  ('desayunos_002', 'Tostada de tomate y aceite', 'desayunos', 'none', NULL, ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 6, 'facil', 'all', 230, 6, 34, 8, 2, true, false, '{"gluten"}', '[{"name":"Pan","amount":160,"unit":"g"},{"name":"Tomate maduro","amount":120,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":1,"unit":"g"}]'::jsonb, '{"Tuesta las rebanadas de pan","Ralla el tomate maduro","Reparte el tomate sobre las tostadas","Añade un hilo de aceite de oliva y una pizca de sal"}', 'Clásica tostada de pan con tomate rallado, aceite de oliva y sal', NULL, '{}'),
  ('desayunos_003', 'Tostada con mantequilla y mermelada', 'desayunos', 'none', NULL, ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 290, 6, 44, 10, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Pan","amount":160,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Mermelada","amount":40,"unit":"g"}]'::jsonb, '{"Tuesta el pan","Unta la mantequilla mientras está caliente","Extiende la mermelada por encima"}', 'Tostada clásica con mantequilla y mermelada', NULL, '{}'),
  ('desayunos_004', 'Tostada de jamón serrano y aceite', 'desayunos', 'none', NULL, ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 6, 'facil', 'all', 300, 15, 32, 12, 2, true, false, '{"gluten"}', '[{"name":"Pan","amount":160,"unit":"g"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Tomate maduro","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Tuesta el pan y frota o unta con tomate rallado","Añade un hilo de aceite de oliva","Coloca las lonchas de jamón serrano por encima"}', 'Tostada con tomate, aceite y jamón serrano', NULL, '{}'),
  ('desayunos_005', 'Tostada de pavo y queso', 'desayunos', 'none', NULL, ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 6, 'facil', 'all', 310, 18, 33, 11, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Pan","amount":160,"unit":"g"},{"name":"Pechuga de pavo","amount":80,"unit":"g"},{"name":"Queso en lonchas","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":5,"unit":"ml"}]'::jsonb, '{"Tuesta el pan","Coloca el queso en lonchas y deja que temple","Añade la pechuga de pavo y un hilo de aceite"}', 'Tostada de fiambre de pavo con queso', NULL, '{}'),
  ('desayunos_006', 'Tostada de aguacate', 'desayunos', 'none', NULL, ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 7, 'facil', 'all', 340, 7, 36, 18, 2, true, false, '{"gluten"}', '[{"name":"Pan","amount":160,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":5,"unit":"ml"},{"name":"Sal","amount":1,"unit":"g"}]'::jsonb, '{"Tuesta el pan","Machaca el aguacate con unas gotas de limón y sal","Extiende sobre la tostada y añade un hilo de aceite"}', 'Tostada de aguacate machacado con limón y aceite de oliva', NULL, '{}'),
  ('desayunos_007', 'Leche con cereales', 'desayunos', 'none', NULL, ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 3, 'facil', 'all', 280, 10, 46, 6, 2, true, false, '{"lactosa","gluten"}', '[{"name":"Leche","amount":400,"unit":"ml"},{"name":"Cereales","amount":80,"unit":"g"}]'::jsonb, '{"Reparte los cereales en dos boles","Vierte la leche por encima","Sirve al momento para que no se ablanden"}', 'Bol de leche con cereales, desayuno rápido de siempre', NULL, '{}'),
  ('desayunos_008', 'Porridge de avena con plátano', 'desayunos', 'none', NULL, ARRAY['desayuno']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 330, 12, 54, 7, 2, true, false, '{"lactosa","gluten"}', '[{"name":"Copos de avena","amount":80,"unit":"g"},{"name":"Leche","amount":350,"unit":"ml"},{"name":"Plátano","amount":1,"unit":"ud"},{"name":"Miel","amount":15,"unit":"ml"}]'::jsonb, '{"Calienta la leche con la avena a fuego suave, removiendo","Cocina 4-5 minutos hasta que espese","Sirve con el plátano en rodajas y un hilo de miel"}', 'Gachas de avena con leche, plátano y miel', NULL, '{}'),
  ('ensaladas_verduras_001', 'Ensalada mixta', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 218, 9, 10, 17, 2, true, false, '{"lactosa","sulfitos"}', '[{"name":"Lechuga","amount":150,"unit":"g"},{"name":"Tomate","amount":150,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Cebolla","amount":40,"unit":"g"},{"name":"Queso fresco","amount":80,"unit":"g"},{"name":"Aceitunas","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre","amount":10,"unit":"ml"}]'::jsonb, '{"Lavar y trocear la lechuga","Cortar el tomate en gajos, el pepino en rodajas y la cebolla en aros","Añadir las aceitunas y el queso fresco en dados","Aliñar con aceite, vinagre y sal"}', 'Ensalada mixta de lechuga, tomate, pepino, cebolla, aceitunas y queso fresco', '[]'::jsonb, '{}'),
  ('ensaladas_verduras_002', 'Pisto manchego', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'verano', 186, 4, 16, 12, 2, true, true, '{}', '[{"name":"Calabacín","amount":200,"unit":"g"},{"name":"Pimiento rojo","amount":120,"unit":"g"},{"name":"Pimiento verde","amount":120,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Tomate maduro","amount":200,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"}]'::jsonb, '{"Cortar todas las verduras en dados pequeños","Sofreír cebolla y ajo, añadir pimientos","Incorporar calabacín y cocer 10 min","Añadir tomate pelado y cocer 15 min más a fuego lento"}', 'Fritada de verduras al estilo manchego con calabacín y pimientos', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Corta las verduras en trozos similares. Rocía con aceite de oliva y cocina en la airfryer a 180-190°C durante 20-25 minutos, removiendo a mitad, hasta que estén tiernas y ligeramente doradas. Añade el tomate al final para que se integre."},{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Mezcla todas las verduras picadas con aceite de oliva, sal y pimienta en una bandeja de horno. Hornea a 190-200°C durante 40-45 minutos, removiendo ocasionalmente, hasta que estén muy tiernas y caramelizadas, añadiendo el tomate a mitad de cocción."},{"appliance":"thermomix","time":40,"difficulty":"facil","prepSummary":"Trocea las verduras en el vaso. Sofríe la cebolla y el ajo con aceite, luego añade los pimientos y el calabacín, y cocina. Incorpora el tomate y programa 20-25 minutos a temperatura Varoma, velocidad cuchara, giro inverso, hasta obtener un pisto tierno."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo en la olla con aceite. Añade los pimientos, calabacín y tomate, cierra la olla y cocina 5-7 minutos desde que sube la válvula. Despresuriza y remueve hasta espesar ligeramente."}]'::jsonb, '{}'),
  ('ensaladas_verduras_003', 'Menestra de verduras con jamón', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 198, 6, 18, 10, 2, true, true, '{"gluten"}', '[{"name":"Alcachofas","amount":150,"unit":"g"},{"name":"Judías verdes","amount":100,"unit":"g"},{"name":"Guisantes","amount":80,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Jamón serrano","amount":40,"unit":"g"},{"name":"Harina","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Cocer las verduras por separado al dente","Sofreír cebolla y jamón, añadir harina","Incorporar un poco de caldo de cocción y las verduras","Cocer todo junto 5 min para que ligue"}', 'Menestra de verduras de temporada rehogadas con jamón', '[{"appliance":"horno","time":35,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el jamón en una sartén. Mezcla con las verduras en una fuente apta para horno, añade un poco de caldo y hornea a 180-200°C hasta que estén tiernas, unos 20-25 minutos."},{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Trocea y sofríe la cebolla y el jamón. Añade las verduras y un poco de caldo, cocinando a temperatura Varoma o 100°C, velocidad cuchara, hasta que estén tiernas, unos 20-25 minutos."},{"appliance":"vaporera","time":35,"difficulty":"facil","prepSummary":"Cocina las verduras al vapor hasta que estén tiernas pero firmes. En una sartén aparte, sofríe la cebolla y el jamón. Mezcla todo con las verduras al vapor y un chorrito de aceite de oliva, añadiendo la harina disuelta en un poco de caldo para ligar si se desea."},{"appliance":"olla_express","time":25,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el jamón en la olla. Añade las verduras más duras con un poco de caldo y cocina a presión 5-7 minutos. Libera la presión, añade los guisantes y la harina disuelta en caldo para espesar, cocinando unos minutos más sin presión."}]'::jsonb, '{}'),
  ('ensaladas_verduras_004', 'Calabacín relleno de carne', 'ensaladas_verduras', 'cerdo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 45, 'normal', 'all', 348, 22, 12, 24, 2, true, true, '{}', '[{"name":"Calabacín","amount":400,"unit":"g"},{"name":"Carne picada de cerdo","amount":200,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Cortar calabacines por la mitad y vaciar la pulpa","Sofreír cebolla, ajo y carne con la pulpa picada","Rellenar las barquitas y cubrir con tomate","Hornear a 190°C durante 25 min"}', 'Calabacines rellenos de carne picada gratinados con tomate', '[{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Prepara el relleno salteando la carne con cebolla, ajo y tomate. Rellena los calabacines ahuecados y hornea a 180-200°C durante 25-30 minutos hasta que el calabacín esté tierno y el relleno bien integrado."},{"appliance":"airfryer","time":40,"difficulty":"normal","prepSummary":"Tras preparar el relleno en sartén, rellena los calabacines y cocina en la airfryer a 180°C durante 20-25 minutos. Vigila que el calabacín quede tierno y el relleno bien caliente, logrando un exterior ligeramente crujiente."},{"appliance":"thermomix","time":45,"difficulty":"normal","prepSummary":"Prepara el sofrito y la carne picada en el vaso de la Thermomix. Cocina los calabacines ahuecados al vapor en el Varoma mientras se hace el relleno. Luego, rellena y sirve, obteniendo un plato jugoso y cocinado de forma eficiente."},{"appliance":"vaporera","time":45,"difficulty":"normal","prepSummary":"Cocina el relleno de carne picada con cebolla, ajo y tomate en una sartén. Ahueca los calabacines y cuécelos al vapor durante 20-25 minutos hasta que estén tiernos. Rellena los calabacines con la carne y sirve un plato ligero y saludable."}]'::jsonb, '{}'),
  ('ensaladas_verduras_005', 'Espinacas a la catalana', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 208, 6, 12, 16, 2, false, true, '{"frutos_secos"}', '[{"name":"Espinacas frescas","amount":300,"unit":"g"},{"name":"Pasas","amount":20,"unit":"g"},{"name":"Piñones","amount":20,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Tostar los piñones en sartén sin aceite","Sofreír ajo laminado, añadir espinacas","Saltear hasta que reduzcan","Añadir pasas y piñones, salpimentar"}', 'Espinacas salteadas con pasas y piñones al estilo catalán', '[{"appliance":"thermomix","time":18,"difficulty":"facil","prepSummary":"Pica el ajo, luego sofríelo con el aceite y los piñones. Añade las espinacas y las pasas, y cocina a 100°C, giro inverso, velocidad cuchara, hasta que las espinacas estén a tu gusto (aprox. 10-12 minutos)."},{"appliance":"vaporera","time":15,"difficulty":"facil","prepSummary":"Cocina las espinacas al vapor hasta que estén tiernas (unos 5-7 minutos). Mientras, saltea el ajo picado, los piñones y las pasas en una sartén con aceite de oliva hasta dorar. Mezcla las espinacas cocidas con el sofrito."}]'::jsonb, '{}'),
  ('ensaladas_verduras_006', 'Pimientos rellenos de carne', 'ensaladas_verduras', 'ternera', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 50, 'normal', 'all', 382, 24, 18, 24, 2, true, true, '{}', '[{"name":"Pimientos rojos","amount":4,"unit":"ud"},{"name":"Carne picada de ternera","amount":250,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Vaciar los pimientos por la parte del tallo","Sofreír cebolla, ajo y carne, salpimentar","Rellenar los pimientos y colocar en bandeja con tomate","Hornear a 180°C durante 35 min"}', 'Pimientos rojos rellenos de carne picada al horno con tomate', '[{"appliance":"horno","time":65,"difficulty":"normal","prepSummary":"Sofreír la cebolla, ajo, carne y tomate para el relleno en una sartén. Rellenar los pimientos y hornear a 180-200°C durante 40-50 minutos, hasta que estén tiernos y ligeramente dorados."},{"appliance":"airfryer","time":45,"difficulty":"normal","prepSummary":"Preparar el relleno sofriéndolo previamente en una sartén. Rellenar los pimientos cortados por la mitad y cocinar en la airfryer a 185°C durante 25-35 minutos, hasta que los pimientos estén tiernos y el relleno caliente. Un truco es rociar con un poco de aceite para un mejor dorado."},{"appliance":"thermomix","time":55,"difficulty":"normal","prepSummary":"Preparar el relleno en el vaso de la Thermomix (picar cebolla/ajo, sofreír, añadir carne y tomate, cocinar). Rellenar los pimientos y cocinarlos al vapor en el Varoma durante 25-35 minutos, velocidad Varoma, hasta que estén tiernos. El truco es asegurarse de que los pimientos no se deshagan durante la cocción al vapor."}]'::jsonb, '{}'),
  ('ensaladas_verduras_007', 'Berenjenas rellenas', 'ensaladas_verduras', 'cerdo', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 50, 'normal', 'all', 362, 20, 16, 24, 2, true, true, '{"lactosa"}', '[{"name":"Berenjena","amount":400,"unit":"g"},{"name":"Carne picada de cerdo","amount":200,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Queso rallado","amount":30,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Cortar berenjenas por la mitad y vaciar la pulpa","Hornear las cáscaras 10 min a 190°C","Sofreír cebolla, ajo, carne y pulpa con tomate","Rellenar, añadir queso y gratinar 15 min"}', 'Berenjenas rellenas de carne picada gratinadas con queso', '[{"appliance":"horno","time":50,"difficulty":"normal","prepSummary":"Vacía las berenjenas y hornéalas a 180°C unos 30-35 min hasta que estén tiernas. Prepara el sofrito con la carne y rellena. Gratina a 200°C o con función grill durante 10-15 min hasta dorar. El truco es no pasarse con la cocción inicial de la berenjena para que mantenga su forma."},{"appliance":"airfryer","time":45,"difficulty":"normal","prepSummary":"Corta las berenjenas por la mitad, vacía y cocínalas en la airfryer a 180°C durante 20-25 min. Mientras, prepara el sofrito de carne y verduras en una sartén. Rellena las berenjenas y gratina en la airfryer a 190°C por 8-10 min. Un truco es pincelar las berenjenas con aceite para"},{"appliance":"thermomix","time":50,"difficulty":"normal","prepSummary":"Prepara el sofrito de carne y verduras en la Thermomix (velocidad cuchara, 120°C, 15 min). Cocina las berenjenas cortadas por la mitad al vapor en el Varoma (25-30 min, Varoma, vel 1). Luego, rellena y gratina en el horno o airfryer. El truco es usar el Varoma para una cocción un"}]'::jsonb, '{}'),
  ('ensaladas_verduras_008', 'Verduras a la plancha', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'verano', 156, 4, 12, 10, 2, true, true, '{}', '[{"name":"Calabacín","amount":150,"unit":"g"},{"name":"Berenjena","amount":150,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Espárragos trigueros","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Cortar verduras en láminas de medio cm","Calentar la plancha a fuego fuerte","Cocinar cada verdura 3 min por lado","Aliñar con aceite y sal en escamas"}', 'Verduras de temporada asadas a la plancha con aceite', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Corta las verduras en trozos similares, mézclalas con el aceite de oliva y sazona. Cocina en la airfryer precalentada a 190°C durante 15-18 minutos, agitando la cesta a mitad para un dorado uniforme y una textura tierna por dentro."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Corta las verduras, úntalas con aceite de oliva y sazona. Extiéndelas en una bandeja de horno y ásalas durante 20-25 minutos, dándoles la vuelta a mitad, hasta que estén tiernas y ligeramente caramelizadas."}]'::jsonb, '{}'),
  ('ensaladas_verduras_009', 'Escalivada', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, 'horno', 50, 'facil', 'verano', 168, 3, 14, 12, 2, true, true, '{}', '[{"name":"Berenjena","amount":200,"unit":"g"},{"name":"Pimiento rojo","amount":200,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Tomate","amount":150,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Asar las verduras enteras al horno a 200°C 40 min","Dejar templar y pelar la piel","Cortar en tiras y disponer en fuente","Aliñar generosamente con aceite y sal"}', 'Verduras asadas al horno, peladas y aliñadas al estilo catalán', '[{"appliance":"horno","time":50,"difficulty":"facil","prepSummary":"Asa las verduras enteras o en trozos grandes a 180-200°C durante 45-50 minutos, hasta que estén muy tiernas y ligeramente chamuscadas. Pela y aliña con aceite de oliva."},{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"Corta las verduras en trozos grandes, úntalas con aceite y cocínalas en la airfryer a 190°C durante 30-35 minutos, volteando a mitad de cocción, hasta que estén tiernas y doradas."}]'::jsonb, '{}'),
  ('ensaladas_verduras_010', 'Judías verdes rehogadas', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 132, 4, 10, 8, 2, true, true, '{}', '[{"name":"Judías verdes","amount":350,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Jamón serrano","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Cocer las judías en agua con sal 10 min","Escurrir bien","Saltear con ajo laminado y jamón en taquitos","Servir con un chorrito de aceite"}', 'Judías verdes cocidas y rehogadas con ajo y jamón', '[{"appliance":"thermomix","time":25,"difficulty":"normal","prepSummary":"Cocina las judías verdes al vapor en el Varoma durante 18-20 minutos. Mientras, sofríe el ajo picado y el jamón serrano en el vaso con aceite de oliva a 120°C, 5 min, Vel. Cuchara. Incorpora las judías cocidas y mezcla."},{"appliance":"vaporera","time":22,"difficulty":"facil","prepSummary":"Cocina las judías verdes al vapor hasta que estén tiernas (15-20 min). En una sartén aparte, sofríe el ajo picado y el jamón serrano con el aceite de oliva hasta que el jamón esté crujiente. Mezcla las judías con el sofrito."},{"appliance":"olla_express","time":18,"difficulty":"facil","prepSummary":"Cocina las judías verdes en la olla express con un poco de agua durante 3-5 minutos desde que sube la válvula. Escurre bien. En la misma olla abierta o en una sartén, sofríe el ajo y el jamón con el aceite hasta dorar, luego añade las judías y saltea brevemente."}]'::jsonb, '{}'),
  ('ensaladas_verduras_011', 'Brócoli gratinado', 'ensaladas_verduras', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 25, 'facil', 'invierno', 212, 10, 10, 14, 2, true, true, '{"lactosa","gluten"}', '[{"name":"Brócoli","amount":400,"unit":"g"},{"name":"Bechamel","amount":100,"unit":"ml"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Cocer el brócoli en ramilletes 5 min al dente","Colocar en fuente de horno","Cubrir con bechamel y queso rallado","Gratinar a 220°C 10 min hasta dorar"}', 'Brócoli al vapor gratinado con bechamel y queso', '[{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Cocina el brócoli al vapor o hervido hasta que esté tierno. Mézclalo con la bechamel en una fuente apta para horno, cubre con el queso rallado y gratina a 190-200°C durante 15-20 minutos, hasta que esté dorado y burbujeante."},{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Cuece el brócoli al vapor. En un recipiente pequeño apto para airfryer, mezcla el brócoli con la bechamel, cubre con el queso rallado y cocina a 180°C durante 10-15 minutos, hasta que el queso esté fundido y dorado."}]'::jsonb, '{}'),
  ('ensaladas_verduras_012', 'Coliflor rebozada', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'invierno', 238, 8, 18, 14, 2, true, true, '{"gluten","huevo"}', '[{"name":"Coliflor","amount":400,"unit":"g"},{"name":"Harina","amount":30,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Separar la coliflor en ramilletes y cocer 8 min","Escurrir y enfriar","Pasar por harina y huevo batido","Freír en aceite caliente hasta dorar"}', 'Ramilletes de coliflor cocidos, rebozados y fritos', '[{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"Precocina la coliflor al vapor hasta que esté tierna. Reboza los floretes, rocíalos con aceite y cocínalos en la airfryer a 190°C durante 18-20 minutos, volteando a mitad, hasta que estén dorados y crujientes."},{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Hierve o cuece la coliflor hasta que esté tierna. Reboza los trozos, colócalos en una bandeja de horno con papel y rocía con aceite. Hornea a 200°C durante 25-30 minutos, volteando a mitad, hasta que estén bien dorados."}]'::jsonb, '{}'),
  ('ensaladas_verduras_013', 'Ensalada campera', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'verano', 248, 6, 26, 14, 2, true, true, '{"sulfitos"}', '[{"name":"Patata","amount":250,"unit":"g"},{"name":"Tomate","amount":120,"unit":"g"},{"name":"Pimiento verde","amount":80,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Aceitunas","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre","amount":10,"unit":"ml"}]'::jsonb, '{"Cocer las patatas enteras con piel 25 min","Pelar y cortar en rodajas gruesas","Añadir tomate, pimiento, cebolla y aceitunas","Aliñar con aceite y vinagre templada"}', 'Ensalada templada de patata con verduras y aceitunas', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Corta las patatas en dados, rocíalas con un poco de aceite y sal. Cocínalas en la airfryer a 190°C durante 20-22 minutos, agitándolas a mitad de cocción, hasta que estén tiernas y ligeramente doradas."},{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Corta las patatas en dados, mézclalas con un chorrito de aceite y sal. Hornea a 200°C durante 30-35 minutos, removiendo ocasionalmente, hasta que estén tiernas y ligeramente doradas."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Trocea las patatas y cuécelas al vapor en el Varoma durante 20-25 minutos. Mientras, pica el resto de las verduras con la Thermomix para un montaje rápido."},{"appliance":"vaporera","time":25,"difficulty":"facil","prepSummary":"Corta las patatas en dados y cuécelas al vapor durante 20-25 minutos hasta que estén tiernas. Este método conserva mejor sus nutrientes y textura para la ensalada."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Corta las patatas en dados, añade un vaso de agua a la olla y cuécelas al vapor o sumergidas durante 5-7 minutos desde que sube la válvula, para una cocción ultrarrápida."}]'::jsonb, '{}'),
  ('ensaladas_verduras_014', 'Champiñones al ajillo', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 12, 'facil', 'all', 128, 5, 4, 10, 2, false, false, '{}', '[{"name":"Champiñones","amount":300,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Guindilla","amount":1,"unit":"ud"}]'::jsonb, '{"Limpiar y laminar los champiñones","Calentar aceite con ajo laminado y guindilla","Añadir champiñones a fuego fuerte","Saltear 5 min y servir con perejil"}', 'Champiñones laminados salteados con ajo y perejil', '[]'::jsonb, '{}'),
  ('ensaladas_verduras_015', 'Ensaladilla rusa', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'verano', 312, 8, 28, 18, 2, true, true, '{"huevo","pescado"}', '[{"name":"Patata","amount":250,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Guisantes","amount":60,"unit":"g"},{"name":"Atún en conserva","amount":60,"unit":"g"},{"name":"Huevo cocido","amount":1,"unit":"ud"},{"name":"Mayonesa","amount":60,"unit":"g"},{"name":"Aceitunas","amount":20,"unit":"g"}]'::jsonb, '{"Cocer patata, zanahoria y guisantes, enfriar","Cortar en dados pequeños","Mezclar con atún, aceitunas y huevo picado","Añadir mayonesa y refrigerar 1 h antes de servir"}', 'Ensaladilla rusa con patata, zanahoria, atún y mayonesa', '[{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Cocina las patatas, zanahorias y guisantes al vapor en el Varoma durante 20-25 minutos a temperatura Varoma, mientras hierves el huevo en el vaso. Luego trocea y mezcla con el resto de ingredientes."},{"appliance":"vaporera","time":30,"difficulty":"facil","prepSummary":"Cuece al vapor las patatas y zanahorias troceadas junto con los guisantes y el huevo durante 20-25 minutos hasta que estén tiernos. Enfría, trocea y mezcla con la mayonesa y el resto de ingredientes."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Cocina las patatas, zanahorias, guisantes y el huevo en la olla express con un poco de agua durante 6-8 minutos desde que sube la válvula. Despresuriza, enfría, trocea y mezcla con el resto."}]'::jsonb, '{}'),
  ('ensaladas_verduras_016', 'Alcachofas salteadas', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'invierno', 168, 5, 14, 10, 2, false, true, '{}', '[{"name":"Alcachofas","amount":400,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Jamón serrano","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Limpiar alcachofas dejando el corazón y frotar con limón","Cortar en cuartos y cocer 10 min al vapor","Saltear con ajo y jamón en taquitos","Servir con perejil"}', 'Corazones de alcachofa salteados con ajo y jamón', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Prepara las alcachofas limpias y troceadas. Mézclalas con aceite, ajo picado, sal y pimienta. Cocina en la airfryer precalentada a 190°C durante 15-18 minutos, removiendo a mitad. Añade el jamón serrano los últimos 3-4 minutos para que quede crujiente y sirve con limón y perejil."},{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Limpia y trocea las alcachofas, mézclalas con aceite de oliva, ajo picado, sal y pimienta. Extiéndelas en una bandeja de horno y asa a 200°C durante 25-30 minutos, hasta que estén tiernas y doradas. Incorpora el jamón serrano los últimos 5 minutos para que se dore y termina con l"}]'::jsonb, '{}'),
  ('ensaladas_verduras_017', 'Tumbet mallorquín', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, 'horno', 40, 'normal', 'verano', 268, 4, 24, 18, 2, true, true, '{}', '[{"name":"Patata","amount":200,"unit":"g"},{"name":"Berenjena","amount":200,"unit":"g"},{"name":"Pimiento rojo","amount":150,"unit":"g"},{"name":"Tomate maduro","amount":200,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Freír patata, berenjena y pimiento por separado","Hacer salsa de tomate con ajo","Montar en capas: patata, berenjena, pimiento","Cubrir con la salsa y hornear 10 min a 180°C"}', 'Capas de verduras fritas con salsa de tomate al estilo balear', '[{"appliance":"horno","time":60,"difficulty":"normal","prepSummary":"Corta las verduras y ásalas en el horno a 200°C con aceite de oliva durante unos 30-40 minutos, hasta que estén tiernas y ligeramente doradas. Luego, monta las capas de verduras con la salsa de tomate y hornea 15-20 minutos más para que los sabores se integren bien."},{"appliance":"airfryer","time":55,"difficulty":"normal","prepSummary":"Prepara las verduras cortadas y cocínalas en la airfryer a 190°C en varias tandas (unos 10-15 min por tanda) hasta que estén tiernas y con un toque dorado. Haz la salsa de tomate aparte y luego monta el tumbet en capas para servir."}]'::jsonb, '{}'),
  ('ensaladas_verduras_018', 'Espárragos a la plancha con ajo', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 108, 4, 4, 8, 2, true, false, '{}', '[{"name":"Espárragos trigueros","amount":300,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Sal en escamas","amount":2,"unit":"g"}]'::jsonb, '{"Lavar espárragos y cortar la parte leñosa","Calentar la plancha a fuego fuerte","Cocinar con aceite 4 min girando","Servir con ajo picado y sal en escamas"}', 'Espárragos trigueros a la plancha con aceite y ajo', '[{"appliance":"airfryer","time":12,"difficulty":"facil","prepSummary":"Mezcla los espárragos con el aceite de oliva, ajo picado y sal. Cocina en la airfryer precalentada a 190°C durante 10-12 minutos, agitando la cesta a mitad del tiempo, hasta que estén tiernos y ligeramente dorados."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. En una bandeja, extiende los espárragos mezclados con aceite de oliva, ajo picado y sal. Asa durante 15-20 minutos, volteándolos a mitad, hasta que estén tiernos y con puntas ligeramente crujientes."}]'::jsonb, '{}'),
  ('ensaladas_verduras_019', 'Pimientos del padrón', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 118, 2, 6, 10, 2, true, false, '{}', '[{"name":"Pimientos de padrón","amount":250,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Sal gorda","amount":5,"unit":"g"}]'::jsonb, '{"Lavar y secar bien los pimientos","Freír en aceite muy caliente hasta que ampollen","Escurrir sobre papel absorbente","Salar con sal gorda y servir"}', 'Pimientos de padrón fritos con sal gorda', '[]'::jsonb, '{}'),
  ('ensaladas_verduras_020', 'Acelgas rehogadas', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'invierno', 138, 5, 8, 10, 2, true, true, '{}', '[{"name":"Acelgas","amount":400,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón","amount":3,"unit":"g"}]'::jsonb, '{"Lavar y trocear las acelgas separando pencas y hojas","Cocer pencas y patata 10 min, añadir hojas 3 min más","Escurrir bien","Rehogar con ajo y pimentón en aceite"}', 'Acelgas cocidas rehogadas con ajo, patata y pimentón', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Cocina las patatas y acelgas al vapor en el Varoma. Luego, sofríe el ajo y pimentón en el vaso con aceite, añade las verduras cocidas y mezcla a velocidad cuchara hasta integrar."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Sofríe el ajo y pimentón en la olla con aceite. Añade las patatas y acelgas con un poco de agua, cierra la olla y cocina a presión durante 3-5 minutos. Libera la presión y mezcla bien."}]'::jsonb, '{}'),
  ('ensaladas_verduras_021', 'Ensalada de tomate', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'verano', 152, 2, 8, 12, 2, true, false, '{}', '[{"name":"Tomate maduro","amount":400,"unit":"g"},{"name":"Cebolla","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Orégano","amount":2,"unit":"g"}]'::jsonb, '{"Cortar los tomates en rodajas gruesas","Añadir cebolla en aros finos","Aliñar con aceite, sal y orégano","Dejar reposar 5 min antes de servir"}', 'Ensalada simple de tomate maduro con cebolla y orégano', '[]'::jsonb, '{}'),
  ('ensaladas_verduras_022', 'Lombarda rehogada', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'invierno', 152, 3, 18, 8, 2, true, true, '{}', '[{"name":"Lombarda","amount":400,"unit":"g"},{"name":"Manzana","amount":100,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Vinagre","amount":15,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Cortar la lombarda en juliana fina","Pochar cebolla y añadir lombarda con vinagre","Incorporar manzana en dados","Cocer tapado 25 min a fuego lento"}', 'Lombarda estofada con manzana y vinagre', '[{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Trocea la cebolla y sofríe con aceite. Añade la lombarda y manzana troceadas, el vinagre y cocina a temperatura Varoma, giro inverso, velocidad cuchara durante 20-25 minutos hasta que esté tierna."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla con aceite en la olla abierta. Incorpora la lombarda, manzana y vinagre, cierra la olla y cocina a presión durante 8-10 minutos. Despresuriza y sirve."}]'::jsonb, '{}'),
  ('ensaladas_verduras_023', 'Coles de Bruselas salteadas', 'ensaladas_verduras', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'invierno', 162, 6, 10, 10, 2, false, true, '{}', '[{"name":"Coles de Bruselas","amount":350,"unit":"g"},{"name":"Panceta","amount":40,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Limpiar las coles y cortar por la mitad","Cocer 8 min al vapor o hervidas","Saltear con ajo y panceta en taquitos","Dorar a fuego fuerte hasta que caramelicen"}', 'Coles de Bruselas salteadas con panceta crujiente', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Mezcla las coles de Bruselas cortadas, la panceta, el ajo y el aceite. Cocina durante 15-20 minutos, agitando la cesta a mitad del tiempo para un acabado crujiente y dorado."},{"appliance":"horno","time":28,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Extiende las coles de Bruselas, la panceta y el ajo con el aceite en una bandeja de horno. Hornea durante 25-30 minutos, removiendo a mitad, hasta que estén tiernas y bien doradas."}]'::jsonb, '{}'),
  ('ensaladas_verduras_024', 'Ensalada César', 'ensaladas_verduras', 'pollo', NULL, ARRAY['primero','plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 328, 24, 12, 22, 2, true, false, '{"gluten","huevo","lactosa"}', '[{"name":"Lechuga romana","amount":200,"unit":"g"},{"name":"Pechuga de pollo","amount":200,"unit":"g"},{"name":"Pan","amount":40,"unit":"g"},{"name":"Queso parmesano","amount":20,"unit":"g"},{"name":"Mayonesa","amount":30,"unit":"g"},{"name":"Ajo","amount":4,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Hacer la pechuga a la plancha y cortar en tiras","Tostar dados de pan con ajo y aceite","Mezclar mayonesa con limón y parmesano para la salsa","Montar la lechuga con pollo, picatostes y salsa"}', 'Ensalada de lechuga romana con pollo, picatostes y salsa César', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Cocina el pollo cortado en tiras o dados a 180°C durante 15-18 minutos, dándole la vuelta. Luego, tuesta los dados de pan con un poco de aceite y ajo a 180°C durante 5-8 minutos hasta que estén crujientes."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Hornea el pollo a 200°C durante 20-25 minutos hasta que esté dorado y cocido. Al mismo tiempo, tuesta los dados de pan con aceite y ajo a 180°C durante 10-15 minutos hasta obtener unos picatostes crujientes."}]'::jsonb, '{}'),
