  ('guarniciones_022', 'Pepino con yogur y menta', 'guarniciones', 'none', NULL, ARRAY['guarnicion']::meal_role[], 'guarnicion', NULL, NULL, 5, 'facil', 'verano', 60, 3, 6, 2, 2, true, false, '{"lactosa"}', '[{"name":"Pepino","amount":200,"unit":"g"},{"name":"Yogur natural","amount":80,"unit":"g"},{"name":"Menta fresca","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":8,"unit":"ml"}]'::jsonb, '{"Cortar el pepino en rodajas finas o medias lunas","Mezclar el yogur con menta picada y aceite","Combinar con el pepino","Servir frío"}', 'Pepino fresco con salsa de yogur, menta y aceite de oliva', NULL, '{}'),
  ('huevos_001', 'Tortilla española', 'huevos', 'huevo', NULL, ARRAY['segundo','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'normal', 'all', 386, 16, 28, 24, 2, true, true, '{"huevo"}', '[{"name":"Patata","amount":300,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":60,"unit":"ml"}]'::jsonb, '{"Pelar y cortar patatas y cebolla en láminas finas","Confitar en aceite a fuego lento 20 min","Escurrir, mezclar con huevo batido y salpimentar","Cuajar en sartén 3 min por cada lado"}', 'Tortilla de patata con cebolla, jugosa por dentro', '[]'::jsonb, '{}'),
  ('huevos_002', 'Tortilla francesa', 'huevos', 'huevo', NULL, ARRAY['cena']::meal_role[], 'principal', NULL, NULL, 5, 'facil', 'all', 232, 14, 1, 18, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Batir los huevos con sal","Calentar aceite en sartén antiadherente","Verter el huevo y cuajar 1 min por cada lado","Doblar por la mitad y servir"}', 'Tortilla francesa sencilla, cuajada por fuera y jugosa', '[]'::jsonb, '{}'),
  ('huevos_003', 'Huevos rotos con jamón', 'huevos', 'huevo', NULL, ARRAY['segundo','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 482, 22, 32, 30, 2, true, false, '{"huevo"}', '[{"name":"Patata","amount":300,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":60,"unit":"ml"}]'::jsonb, '{"Cortar patatas en bastones y freír hasta dorar","Freír los huevos en aceite con la yema líquida","Colocar las patatas en plato, los huevos encima","Romper las yemas y añadir el jamón en virutas"}', 'Huevos fritos con yema líquida sobre patatas fritas y jamón', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Corta las patatas en dados finos, rocíalas con un poco de aceite y sal, y cocínalas en la airfryer a 190°C durante 18-20 minutos, agitando a mitad. Fríe los huevos en una sartén aparte hasta que la clara cuaje y la yema quede líquida. Sirve las patatas con los huevos rotos y el jamón por encima."},{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Corta las patatas en dados, mézclalas con aceite de oliva y sal, y extiéndelas en una bandeja de horno. Hornea a 200°C durante 25-30 minutos, hasta que estén tiernas y doradas. Retira, haz huecos y casca los huevos, horneando 5-8 minutos más hasta que la clara cuaje y la yema esté al gusto. Rompe los huevos sobre las patatas y reparte el jamón por encima."}]'::jsonb, '{}'),
  ('huevos_004', 'Revuelto de champiñones', 'huevos', 'huevo', NULL, ARRAY['cena','primero']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 268, 16, 4, 22, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Champiñones","amount":200,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Saltear champiñones laminados con ajo a fuego fuerte","Bajar el fuego y añadir los huevos batidos","Remover suavemente hasta que cuajen cremosos","Servir con perejil picado"}', 'Revuelto cremoso de huevos con champiñones y ajo', '[]'::jsonb, '{}'),
  ('huevos_005', 'Revuelto de ajetes', 'huevos', 'huevo', NULL, ARRAY['cena','primero']::meal_role[], 'principal', NULL, NULL, 12, 'facil', 'all', 248, 14, 4, 20, 2, false, false, '{"huevo","marisco"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Ajetes tiernos","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Gambas","amount":80,"unit":"g"}]'::jsonb, '{"Saltear ajetes troceados en aceite 3 min","Añadir las gambas y saltear 2 min","Verter los huevos batidos","Remover a fuego suave hasta cuajar cremoso"}', 'Revuelto cremoso de ajetes tiernos con gambas', '[]'::jsonb, '{}'),
  ('huevos_006', 'Tortilla de calabacín', 'huevos', 'huevo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 278, 14, 8, 22, 2, true, true, '{"huevo"}', '[{"name":"Calabacín","amount":250,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Cortar calabacín y cebolla en medias lunas finas","Pochar en aceite a fuego lento 10 min","Escurrir, mezclar con huevo batido y salpimentar","Cuajar en sartén 3 min por cada lado"}', 'Tortilla de calabacín y cebolla pochada', '[]'::jsonb, '{}'),
  ('huevos_007', 'Huevos fritos con puntillas', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 10, 'facil', 'all', 312, 14, 1, 28, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Aceite de oliva","amount":60,"unit":"ml"}]'::jsonb, '{"Calentar abundante aceite en sartén pequeña","Cascar cada huevo cuando el aceite esté muy caliente","Bañar la clara con aceite para que haga puntillas","Retirar con la yema aún líquida"}', 'Huevos fritos en abundante aceite con bordes crujientes', '[]'::jsonb, '{}'),
  ('huevos_008', 'Revuelto de espárragos', 'huevos', 'huevo', NULL, ARRAY['cena','primero']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 238, 14, 6, 18, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Espárragos trigueros","amount":200,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Cortar espárragos desechando la parte leñosa","Saltear con ajo laminado en aceite 5 min","Añadir huevos batidos","Remover a fuego suave hasta cuajar cremoso"}', 'Revuelto cremoso de huevos con espárragos trigueros', '[]'::jsonb, '{}'),
  ('huevos_009', 'Huevos al plato', 'huevos', 'huevo', NULL, ARRAY['cena']::meal_role[], 'principal', NULL, 'horno', 20, 'facil', 'all', 328, 18, 10, 24, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Jamón serrano","amount":40,"unit":"g"},{"name":"Tomate triturado","amount":120,"unit":"ml"},{"name":"Guisantes","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Chorizo","amount":30,"unit":"g"}]'::jsonb, '{"Repartir tomate en dos cazuelitas de barro","Añadir guisantes, jamón y chorizo en rodajas","Cascar dos huevos en cada cazuelita","Hornear a 200°C 10 min hasta que la clara cuaje"}', 'Huevos horneados en cazuelita con tomate, jamón y guisantes', '[{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 180°C. En cazuelitas individuales, vierte el tomate, guisantes, jamón y chorizo. Haz un hueco y casca el huevo. Hornea 15-20 minutos hasta que la clara esté cuajada y la yema líquida."},{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 170°C. En una cazuelita apta para airfryer, distribuye el tomate, guisantes, jamón y chorizo, y casca el huevo. Cocina durante 12-15 minutos hasta que la clara esté firme y la yema a tu gusto."}]'::jsonb, '{}'),
  ('huevos_010', 'Huevos rellenos', 'huevos', 'huevo', NULL, ARRAY['primero','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'verano', 298, 18, 6, 22, 2, true, true, '{"huevo","pescado"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Atún en conserva","amount":80,"unit":"g"},{"name":"Mayonesa","amount":40,"unit":"g"},{"name":"Tomate triturado","amount":60,"unit":"ml"},{"name":"Pimiento morrón","amount":30,"unit":"g"}]'::jsonb, '{"Cocer los huevos 10 min, enfriar y pelar","Cortar por la mitad y sacar las yemas","Mezclar yemas con atún, mayonesa y pimiento picado","Rellenar las claras y napar con tomate"}', 'Huevos cocidos rellenos de atún y mayonesa con tomate', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Cocina los huevos en el vaso con agua (13-15 min, Varoma/100°C, vel 1). Pela, retira las yemas y mézclalas con el atún y la mayonesa en el vaso (unos segundos, vel 4) para un relleno homogéneo."},{"appliance":"vaporera","time":22,"difficulty":"facil","prepSummary":"Cuece los huevos al vapor durante 12-15 minutos para que queden perfectos y fáciles de pelar. Luego, solo tienes que preparar el relleno manualmente y montar los huevos."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Cocina los huevos en la olla express con un poco de agua durante 5-7 minutos a presión alta. Enfría rápidamente para facilitar el pelado y luego procede con el relleno manual."}]'::jsonb, '{}'),
  ('huevos_011', 'Revuelto de gambas', 'huevos', 'huevo', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 12, 'facil', 'all', 288, 22, 2, 22, 2, true, false, '{"huevo","marisco"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Gambas peladas","amount":150,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Saltear las gambas con ajo laminado 2 min","Añadir los huevos batidos","Remover suavemente a fuego medio-bajo","Retirar cuando estén cremosos y servir con perejil"}', 'Revuelto cremoso de huevos con gambas al ajillo', '[]'::jsonb, '{}'),
  ('huevos_012', 'Tortilla de espinacas', 'huevos', 'huevo', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 256, 16, 4, 20, 2, true, true, '{"huevo"}', '[{"name":"Espinacas frescas","amount":200,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Saltear las espinacas con ajo hasta que reduzcan","Escurrir bien y picar grueso","Mezclar con los huevos batidos y salpimentar","Cuajar en sartén con aceite 3 min por lado"}', 'Tortilla jugosa de espinacas salteadas con ajo', '[]'::jsonb, '{}'),
  ('huevos_013', 'Huevos a la flamenca', 'huevos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, 'horno', 30, 'facil', 'all', 372, 20, 18, 24, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Tomate triturado","amount":200,"unit":"ml"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Guisantes","amount":60,"unit":"g"},{"name":"Jamón serrano","amount":40,"unit":"g"},{"name":"Chorizo","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Cebolla","amount":50,"unit":"g"}]'::jsonb, '{"Sofreír cebolla y pimiento, añadir tomate y cocer 10 min","Repartir en cazuelitas con guisantes, jamón y chorizo","Cascar dos huevos en cada cazuelita","Hornear a 200°C 10 min"}', 'Huevos al horno sobre sofrito con pimiento, jamón y chorizo', '[{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Prepara un sofrito con la cebolla, pimiento y tomate. Distribúyelo en cazuelitas individuales con los guisantes, jamón y chorizo. Haz un hueco, casca los huevos y hornea a 180°C durante 15-20 minutos hasta que las claras estén cuajadas y las yemas a tu gusto."},{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Prepara el sofrito en una sartén o microondas. Distribúyelo en ramequines aptos para airfryer con el resto de ingredientes, casca los huevos y cocina a 160-170°C durante 10-12 minutos. Vigila para que las yemas queden a tu gusto."},{"appliance":"microondas","time":20,"difficulty":"normal","prepSummary":"Prepara el sofrito en un bol apto para microondas. Distribúyelo en tazas o ramequines individuales con el resto de ingredientes. Casca los huevos, pincha ligeramente las yemas y cocina a media potencia (500W) en intervalos de 1 minuto hasta que las claras cuajen, vigilando para no sobrecocer las yemas."}]'::jsonb, '{}'),
  ('huevos_014', 'Huevos cocidos con ensalada', 'huevos', 'huevo', NULL, ARRAY['cena','primero']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'verano', 286, 16, 8, 22, 2, true, true, '{"huevo","sulfitos"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Lechuga","amount":100,"unit":"g"},{"name":"Tomate","amount":120,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Aceitunas","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre","amount":10,"unit":"ml"}]'::jsonb, '{"Cocer los huevos 10 min y enfriar en agua","Pelar y cortar en cuartos","Montar la ensalada con lechuga, tomate, pepino y aceitunas","Aliñar con aceite y vinagre"}', 'Huevos cocidos en cuartos sobre ensalada mixta aliñada', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Coloca los huevos directamente en la cesta de la airfryer. Cocina a 135°C durante 14-16 minutos para huevos duros perfectos, luego enfría en agua helada para un pelado fácil."},{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Pon 500g de agua en el vaso y coloca los huevos en el cestillo. Programa 15-18 minutos/Varoma/velocidad 1 para huevos duros, luego enfría rápidamente para parar la cocción."},{"appliance":"vaporera","time":20,"difficulty":"facil","prepSummary":"Calienta agua en la base de la vaporera hasta que hierva. Coloca los huevos en la cesta y cocina al vapor durante 12-15 minutos para huevos duros fáciles de pelar."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Coloca los huevos en la rejilla de la olla express con 1 vaso de agua. Cocina 5-7 minutos a alta presión, luego libera la presión y enfría los huevos para un resultado perfecto."}]'::jsonb, '{}'),
  ('huevos_015', 'Revuelto de setas', 'huevos', 'huevo', NULL, ARRAY['cena','primero']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'invierno', 274, 15, 4, 22, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Setas variadas","amount":200,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Saltear las setas troceadas con ajo a fuego fuerte","Salpimentar y bajar el fuego","Añadir los huevos batidos y remover suavemente","Retirar cuando estén cremosos y añadir perejil"}', 'Revuelto cremoso de setas de temporada con ajo y perejil', '[]'::jsonb, '{}'),
  ('legumbres_001', 'Lentejas con verduras', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'facil', 'all', 348, 18, 46, 7, 2, true, true, '{}', '[{"name":"Lentejas","amount":200,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón","amount":5,"unit":"g"}]'::jsonb, '{"Lavar y escurrir las lentejas","Pochar cebolla, pimiento y zanahoria en aceite","Añadir tomate y pimentón, rehogar 2 min","Incorporar lentejas y patata, cubrir con agua y cocer 35 min"}', 'Lentejas guisadas con zanahoria, patata y pimiento', '[{"appliance":"thermomix","time":50,"difficulty":"facil","prepSummary":"Pica las verduras y sofríelas con aceite. Añade las lentejas, tomate, pimentón y agua (o caldo), y cocina a 100°C o Varoma, giro inverso y velocidad cuchara durante 35-45 minutos, hasta que las lentejas estén tiernas."},{"appliance":"olla_express","time":35,"difficulty":"facil","prepSummary":"Sofríe las verduras picadas en la olla. Incorpora las lentejas, tomate, pimentón y agua (o caldo). Cierra la olla y cocina a presión durante 15-20 minutos desde que sube la válvula, luego deja despresurizar."}]'::jsonb, '{}'),
  ('legumbres_002', 'Lentejas con chorizo', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 50, 'facil', 'invierno', 432, 22, 44, 18, 2, true, true, '{}', '[{"name":"Lentejas","amount":200,"unit":"g"},{"name":"Chorizo","amount":80,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Patata","amount":120,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Pimentón","amount":5,"unit":"g"}]'::jsonb, '{"Pochar la cebolla y la zanahoria","Añadir tomate, pimentón y chorizo en rodajas","Incorporar lentejas y patata con agua","Cocer 40 min a fuego lento"}', 'Lentejas tradicionales guisadas con chorizo y patata', '[{"appliance":"thermomix","time":50,"difficulty":"facil","prepSummary":"Sofríe la cebolla, zanahoria y chorizo. Añade el tomate, pimentón, lentejas, patata y agua. Programa 30-35 min a 100°C, velocidad cuchara, giro inverso. Quedarán unas lentejas cremosas y con todo el sabor."},{"appliance":"olla_express","time":40,"difficulty":"facil","prepSummary":"Prepara un sofrito con cebolla, zanahoria y chorizo en la olla. Incorpora el tomate, pimentón, lentejas, patata y agua. Cierra y cocina a presión durante 20-25 minutos. El resultado son unas lentejas tiernas y sabrosas en mucho menos tiempo."}]'::jsonb, '{}'),
  ('legumbres_003', 'Garbanzos con espinacas', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 384, 16, 42, 16, 2, true, true, '{"gluten"}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Espinacas","amount":200,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Pan del día anterior","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"},{"name":"Comino","amount":2,"unit":"g"}]'::jsonb, '{"Freír el pan con ajo y triturar con pimentón y comino","Rehogar las espinacas con tomate","Añadir los garbanzos y la majada","Cocer 10 min hasta que espese"}', 'Garbanzos con espinacas y majada de pan frito al estilo andaluz', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Sofríe el ajo y las espinacas en una sartén. Traslada a una cazuela de horno con los garbanzos, tomate, especias y el pan tostado. Hornea a 180°C durante unos 30-35 minutos para que los sabores se integren bien, cubierto para mantener la humedad."},{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Trocea el ajo y sofríelo con aceite. Añade el tomate y cocina unos minutos. Incorpora las espinacas, garbanzos, especias y el pan desmenuzado, cocinando a 100°C, velocidad cuchara, giro inverso, durante 15-20 minutos para que los sabores se fundan."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sofríe el ajo en la olla abierta con aceite. Añade el tomate, las espinacas, los garbanzos, especias y el pan. Cierra la olla y cocina a presión durante 5-7 minutos. Despresuriza y remueve para integrar los sabores."}]'::jsonb, '{}'),
  ('legumbres_004', 'Cocido madrileño', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 120, 'elaborada', 'invierno', 618, 38, 40, 32, 2, true, true, '{}', '[{"name":"Garbanzos","amount":250,"unit":"g"},{"name":"Morcillo de ternera","amount":150,"unit":"g"},{"name":"Pollo","amount":120,"unit":"g"},{"name":"Tocino","amount":50,"unit":"g"},{"name":"Chorizo","amount":60,"unit":"g"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Repollo","amount":150,"unit":"g"}]'::jsonb, '{"Cocer carnes y tocino 1 h espumando","Añadir garbanzos remojados y zanahoria","Incorporar patata y cocer 40 min más","Servir caldo, garbanzos y carnes por separado"}', 'Cocido tradicional de garbanzos con carnes y verduras en tres vuelcos', '[{"appliance":"horno","time":210,"difficulty":"elaborada","prepSummary":"Cocinar en una olla de hierro fundido o cazuela apta para horno a 150°C durante 3.5 a 4 horas. Este método asegura una cocción lenta y uniforme, logrando carnes y garbanzos extremadamente tiernos y un caldo profundo."},{"appliance":"thermomix","time":100,"difficulty":"normal","prepSummary":"Permite cocer los garbanzos y las carnes en el vaso, y las verduras en el Varoma, optimizando tiempos. Cocinar a 100°C, velocidad cuchara, durante 90-120 minutos, añadiendo los ingredientes en fases para una cocción perfecta y controlada."},{"appliance":"olla_express","time":75,"difficulty":"normal","prepSummary":"Ideal para acortar drásticamente los tiempos de cocción. Cocinar los garbanzos y carnes a presión durante 45-60 minutos, añadiendo las verduras (repollo, patata, zanahoria) al final para que no se deshagan, logrando una ternura excepcional en menos tiempo."}]'::jsonb, '{}'),
  ('legumbres_005', 'Potaje de garbanzos con bacalao', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 60, 'normal', 'invierno', 412, 30, 40, 12, 2, true, true, '{"pescado"}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Bacalao desalado","amount":150,"unit":"g"},{"name":"Espinacas","amount":150,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón","amount":5,"unit":"g"}]'::jsonb, '{"Sofreír ajo, cebolla y pimentón","Añadir tomate y espinacas, rehogar","Incorporar garbanzos y bacalao desmigado","Cocer 15 min a fuego suave"}', 'Potaje de vigilia con garbanzos, bacalao y espinacas', '[{"appliance":"horno","time":75,"difficulty":"normal","prepSummary":"Comienza el sofrito de cebolla y ajo en una cazuela apta para horno. Incorpora el resto de ingredientes y cocina a 180°C durante 60 minutos, permitiendo que los sabores se integren lentamente."},{"appliance":"thermomix","time":55,"difficulty":"facil","prepSummary":"Pica y sofríe la cebolla y el ajo. Añade el tomate, garbanzos, bacalao y espinacas, y cocina a 100°C, velocidad cuchara, giro inverso durante 45 minutos para una cocción homogénea."},{"appliance":"olla_express","time":35,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el ajo en la olla. Incorpora el resto de ingredientes, cierra la olla y cocina a presión durante 10-12 minutos desde que sube la válvula para un potaje rápido y sabroso."}]'::jsonb, '{}'),
