  ('legumbres_015', 'Ensalada de garbanzos', 'legumbres', 'legumbre', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'verano', 328, 14, 32, 16, 2, true, true, '{"sulfitos"}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Tomate","amount":120,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Cebolla morada","amount":40,"unit":"g"},{"name":"Aceitunas negras","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre de Jerez","amount":10,"unit":"ml"}]'::jsonb, '{"Escurrir los garbanzos","Cortar tomate, pepino y cebolla en dados","Mezclar todo con aceitunas","Aliñar con aceite y vinagre de Jerez"}', 'Ensalada fría de garbanzos con verduras y aceitunas', '[]'::jsonb, '{}'),
  ('legumbres_016', 'Potaje de habichuelas', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 55, 'facil', 'invierno', 378, 20, 46, 10, 2, true, true, '{}', '[{"name":"Alubias blancas","amount":250,"unit":"g"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":18,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Cocer las alubias remojadas con zanahoria y laurel 45 min","Añadir patata en trozos y cocer 15 min","Hacer sofrito de cebolla, ajo y tomate","Incorporar el sofrito y dejar ligar 5 min"}', 'Potaje sencillo de alubias blancas con patata y verduras', '[{"appliance":"horno","time":70,"difficulty":"normal","prepSummary":"Prepara un sofrito inicial con cebolla, ajo, zanahoria y tomate en una olla apta para horno. Añade las alubias, patata, laurel y caldo/agua. Cocina tapado en el horno a 180°C durante unos 50-60 minutos, o hasta que las alubias estén tiernas, removiendo ocasionalmente y ajustando el líquido si es necesario."},{"appliance":"thermomix","time":65,"difficulty":"facil","prepSummary":"Trocea las verduras en el vaso, sofríe con aceite. Añade las alubias (previamente remojadas o cocidas), patata, laurel y caldo/agua. Programa 45-50 minutos, 100°C, giro inverso, velocidad cuchara, hasta que el potaje esté en su punto."},{"appliance":"olla_express","time":45,"difficulty":"facil","prepSummary":"Realiza un sofrito con la cebolla, ajo, zanahoria y tomate en la olla a presión. Incorpora las alubias (remojadas), patata, laurel y suficiente agua/caldo. Cierra la olla y cocina a fuego medio-alto durante 20-25 minutos desde que sube la válvula, dejando despresurizar de forma natural."}]'::jsonb, '{}'),
  ('legumbres_017', 'Lentejas con pollo', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 50, 'facil', 'all', 422, 32, 38, 14, 2, true, true, '{}', '[{"name":"Lentejas","amount":180,"unit":"g"},{"name":"Contramuslo de pollo","amount":200,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Patata","amount":120,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"}]'::jsonb, '{"Dorar el pollo troceado en aceite","Añadir cebolla, zanahoria y tomate","Incorporar lentejas y patata con agua","Cocer 35 min a fuego lento"}', 'Lentejas guisadas con trozos de pollo y verduras', '[{"appliance":"horno","time":65,"difficulty":"facil","prepSummary":"Prepara un sofrito con las verduras y el pollo en una olla apta para horno. Añade las lentejas, tomate, pimentón y caldo. Hornea tapado a 180°C durante unos 60-70 minutos, removiendo ocasionalmente, hasta que las lentejas estén tiernas."},{"appliance":"thermomix","time":55,"difficulty":"facil","prepSummary":"Trocea las verduras y sofríelas en el vaso. Incorpora el pollo, lentejas, tomate, pimentón y agua/caldo. Cocina a 100°C, giro inverso, velocidad cuchara, durante unos 50-55 minutos o hasta que las lentejas estén tiernas."},{"appliance":"olla_express","time":35,"difficulty":"facil","prepSummary":"Sofríe las verduras y el pollo en la olla. Incorpora las lentejas, tomate, pimentón y agua/caldo. Cierra la olla y cocina a presión durante 15-20 minutos desde que sube la válvula. Despresuriza y sirve."}]'::jsonb, '{}'),
  ('legumbres_018', 'Garbanzos con tomate', 'legumbres', 'legumbre', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 342, 14, 40, 14, 2, true, true, '{}', '[{"name":"Garbanzos cocidos","amount":300,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"ml"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Comino","amount":3,"unit":"g"}]'::jsonb, '{"Sofreír cebolla, ajo y pimiento","Añadir tomate y comino, cocer 10 min","Incorporar los garbanzos","Guisar 10 min hasta que ligue"}', 'Garbanzos en salsa de tomate casera con comino', '[{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Prepara el sofrito en una sartén, luego transfiere todo a una cazuela apta para horno. Hornea a 180°C durante 25 minutos para que los sabores se integren y el guiso espese ligeramente."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Pica las verduras en el vaso, sofríelas con aceite. Añade el tomate, garbanzos y comino, y cocina a 100°C, velocidad cuchara, giro inverso durante 14 minutos para un guiso perfecto."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla, ajo y pimiento en la olla abierta. Incorpora el tomate, garbanzos y comino, cierra la olla y cocina 5 minutos desde que sube la válvula para potenciar los sabores."}]'::jsonb, '{}'),
  ('legumbres_019', 'Alubias blancas con almejas', 'legumbres', 'legumbre', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 386, 24, 40, 13, 2, false, true, '{"moluscos","gluten"}', '[{"name":"Alubias blancas cocidas","amount":300,"unit":"g"},{"name":"Almejas","amount":200,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Harina","amount":10,"unit":"g"}]'::jsonb, '{"Abrir las almejas con vino blanco y reservar","Sofreír cebolla y ajo, añadir harina","Incorporar caldo de las almejas y las alubias","Añadir las almejas y perejil, calentar 3 min"}', 'Alubias blancas guisadas con almejas en salsa de vino blanco', '[{"appliance":"thermomix","time":40,"difficulty":"normal","prepSummary":"Pica la cebolla y el ajo, sofríelos con aceite. Añade la harina, el vino, las alubias y las almejas. Cocina a temperatura y velocidad suaves (giro inverso) hasta que las almejas se abran y la salsa espese, unos 20-25 minutos."},{"appliance":"olla_express","time":25,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el ajo en la olla abierta. Incorpora la harina, el vino y las alubias. Añade las almejas, cierra la olla y cocina a presión baja solo 2-3 minutos desde que sube la válvula, para que las almejas se abran sin sobrecocer."}]'::jsonb, '{}'),
  ('legumbres_020', 'Lentejas pardinas en ensalada templada', 'legumbres', 'legumbre', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 336, 16, 32, 15, 2, true, true, '{"mostaza","sulfitos"}', '[{"name":"Lentejas pardinas cocidas","amount":300,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Calabacín","amount":100,"unit":"g"},{"name":"Cebolla morada","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre de Módena","amount":10,"unit":"ml"},{"name":"Mostaza","amount":5,"unit":"g"}]'::jsonb, '{"Saltear pimiento y calabacín en dados","Calentar las lentejas y mezclar con las verduras","Preparar vinagreta con aceite, vinagre y mostaza","Aliñar y servir templada con cebolla morada cruda"}', 'Lentejas pardinas templadas con verduras salteadas y vinagreta', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Corta el pimiento, calabacín y cebolla en trozos. Mézclalos con aceite de oliva, sal y pimienta. Cocínalos en la airfryer a 190°C durante 15-18 minutos, agitando la cesta a mitad del tiempo, hasta que estén tiernos y ligeramente dorados. Mezcla con las lentejas y el aliño."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Trocea el pimiento, calabacín y cebolla, mézclalos con aceite de oliva, sal y pimienta. Extiéndelos en una bandeja y ásalos durante 15-20 minutos hasta que estén tiernos y ligeramente caramelizados. Combina con las lentejas cocidas y el aliño."},{"appliance":"thermomix","time":20,"difficulty":"normal","prepSummary":"Trocea la cebolla, pimiento y calabacín. Sofríelos en el vaso de la Thermomix con aceite a 120°C, velocidad cuchara, durante 10-12 minutos hasta que estén tiernos. Prepara el aliño en el vaso y luego mezcla todo con las lentejas cocidas."}]'::jsonb, '{}'),
  ('meriendas_001', 'Smoothie de kéfir y fruta', 'meriendas', 'none', NULL, ARRAY['merienda']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 210, 9, 34, 4, 2, true, false, '{"lactosa"}', '[{"name":"Kéfir","amount":300,"unit":"ml"},{"name":"Plátano","amount":1,"unit":"ud"},{"name":"Fresas","amount":120,"unit":"g"},{"name":"Miel","amount":10,"unit":"ml"}]'::jsonb, '{"Pela el plátano y limpia las fresas","Pon el kéfir y la fruta en la batidora","Añade la miel y tritura hasta que quede cremoso","Sirve bien frío"}', 'Batido cremoso de kéfir con plátano y fresas endulzado con miel', NULL, '{}'),
