  ('meriendas_006', 'Batido de leche y cacao', 'meriendas', 'none', NULL, ARRAY['merienda']::meal_role[], 'completo', NULL, NULL, 3, 'facil', 'all', 220, 9, 32, 6, 2, true, false, '{"lactosa"}', '[{"name":"Leche","amount":400,"unit":"ml"},{"name":"Cacao en polvo","amount":30,"unit":"g"}]'::jsonb, '{"Calienta o enfría la leche a tu gusto","Disuelve bien el cacao en polvo","Remueve y sirve"}', 'Vaso de leche con cacao, la merienda clásica de la infancia', NULL, '{}'),
  ('pasta_arroces_001', 'Macarrones con tomate', 'pasta_arroces', 'none', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 412, 14, 62, 12, 2, true, true, '{"gluten"}', '[{"name":"Macarrones","amount":200,"unit":"g"},{"name":"Tomate triturado","amount":250,"unit":"ml"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Orégano","amount":3,"unit":"g"}]'::jsonb, '{"Cocer los macarrones en agua con sal","Sofreír cebolla y ajo, añadir tomate y orégano","Cocer la salsa 10 min a fuego lento","Mezclar con la pasta escurrida"}', 'Macarrones con salsa de tomate casera y orégano', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo, luego añade el tomate triturado y el orégano para la salsa. Incorpora los macarrones y el agua, cocinando a 100°C, velocidad cuchara, giro inverso, hasta que la pasta esté al dente."}]'::jsonb, '{}'),
  ('pasta_arroces_002', 'Espaguetis a la boloñesa', 'pasta_arroces', 'ternera', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 518, 26, 58, 20, 2, true, true, '{"gluten"}', '[{"name":"Espaguetis","amount":200,"unit":"g"},{"name":"Carne picada de ternera","amount":200,"unit":"g"},{"name":"Tomate triturado","amount":250,"unit":"ml"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vino tinto","amount":40,"unit":"ml"}]'::jsonb, '{"Sofreír cebolla, ajo y zanahoria rallada","Añadir la carne y dorar desmenuzando","Incorporar tomate y vino, cocer 20 min","Servir sobre los espaguetis cocidos"}', 'Espaguetis con ragú de carne picada, tomate y zanahoria', '[{"appliance":"horno","time":120,"difficulty":"normal","prepSummary":"Prepara el sofrito y dora la carne en una olla apta para horno en la encimera. Añade el resto de ingredientes de la salsa y hornea a 150°C durante 1.5-2 horas para una boloñesa de sabor profundo. Los espaguetis se cuecen aparte."},{"appliance":"thermomix","time":45,"difficulty":"facil","prepSummary":"Pica las verduras en el vaso, sofríelas con aceite, añade la carne y el vino para dorar. Incorpora el tomate y cocina la salsa a temperatura y velocidad controladas. Los espaguetis se pueden cocer en el vaso o cestillo."}]'::jsonb, '{}'),
  ('pasta_arroces_003', 'Arroz blanco con tomate', 'pasta_arroces', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 342, 6, 58, 8, 2, true, true, '{}', '[{"name":"Arroz","amount":180,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"}]'::jsonb, '{"Rehogar el ajo en aceite","Añadir el arroz y sofreírlo 1 min sin dejar de remover","Incorporar tomate y agua, salpimentar","Cocer tapado 18 min a fuego lento"}', 'Arroz blanco cocido con salsa de tomate frito', '[{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Sofríe el ajo y el tomate en una cazuela apta para horno. Añade el arroz y el doble de agua, lleva a ebullición, tapa y hornea a 180°C durante 18-20 minutos hasta que el líquido se absorba."},{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Sofríe el ajo y el tomate en el vaso. Añade el arroz y el doble de agua, programa 18-20 minutos, 100°C, giro inverso, velocidad cuchara para un arroz suelto y bien integrado."},{"appliance":"olla_express","time":18,"difficulty":"facil","prepSummary":"Sofríe el ajo y el tomate en la olla. Añade el arroz y 1.5 veces su volumen de agua, cierra la olla y cocina a presión durante 6-7 minutos. Deja despresurizar de forma natural para un arroz perfecto."}]'::jsonb, '{}'),
  ('pasta_arroces_004', 'Arroz al horno', 'pasta_arroces', 'cerdo', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, 'horno', 50, 'normal', 'invierno', 528, 24, 56, 22, 2, true, true, '{}', '[{"name":"Arroz","amount":180,"unit":"g"},{"name":"Costilla de cerdo","amount":150,"unit":"g"},{"name":"Morcilla","amount":60,"unit":"g"},{"name":"Garbanzos cocidos","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón","amount":5,"unit":"g"}]'::jsonb, '{"Dorar la costilla y la morcilla en cazuela de barro","Añadir tomate y pimentón, sofreír","Incorporar arroz, garbanzos, patata y caldo","Hornear a 200°C 25 min hasta que el arroz esté seco"}', 'Arroz al horno valenciano con costilla, morcilla y garbanzos', '[{"appliance":"horno","time":65,"difficulty":"normal","prepSummary":"Prepara un sofrito con la costilla y el tomate, añade el arroz y el caldo (o agua con pimentón) en una cazuela de barro. Hornea a 190°C durante 45-50 minutos, incorporando la morcilla y las patatas cortadas a mitad de cocción para que se doren y el arroz quede suelto y con socarrat en el fondo."}]'::jsonb, '{}'),
  ('pasta_arroces_005', 'Espaguetis carbonara', 'pasta_arroces', 'cerdo', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 548, 22, 56, 26, 2, true, false, '{"gluten","huevo","lactosa"}', '[{"name":"Espaguetis","amount":200,"unit":"g"},{"name":"Panceta","amount":100,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Queso parmesano","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Cocer los espaguetis al dente","Dorar la panceta en dados sin aceite extra","Mezclar huevos con parmesano rallado","Juntar pasta caliente con panceta y mezcla de huevo fuera del fuego"}', 'Espaguetis carbonara con panceta, huevo y parmesano', '[]'::jsonb, '{}'),
  ('pasta_arroces_006', 'Macarrones con atún', 'pasta_arroces', 'pescado_azul', NULL, ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 448, 24, 58, 14, 2, true, true, '{"gluten","pescado"}', '[{"name":"Macarrones","amount":200,"unit":"g"},{"name":"Atún en conserva","amount":120,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"ml"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Orégano","amount":2,"unit":"g"}]'::jsonb, '{"Cocer los macarrones en agua con sal","Sofreír cebolla y ajo, añadir tomate","Incorporar el atún escurrido y orégano","Mezclar con la pasta"}', 'Macarrones con salsa de tomate y atún en conserva', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Pica la cebolla y el ajo, sofríelos con aceite. Añade el tomate triturado, orégano y un poco de agua, cocina unos minutos. Incorpora los macarrones y cocina el tiempo indicado en el paquete. Finalmente, añade el atún escurrido y mezcla."}]'::jsonb, '{}'),
  ('pasta_arroces_007', 'Arroz con pollo', 'pasta_arroces', 'pollo', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'facil', 'all', 498, 30, 54, 16, 2, true, true, '{}', '[{"name":"Arroz","amount":180,"unit":"g"},{"name":"Contramuslo de pollo","amount":250,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Guisantes","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"}]'::jsonb, '{"Dorar el pollo troceado y reservar","Sofreír cebolla, pimiento y tomate con pimentón","Añadir arroz, sofreír removiendo 1 min, incorporar caldo y pollo","Cocer 18 min a fuego lento sin remover"}', 'Arroz caldoso con trozos de pollo, pimiento y guisantes', '[{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Prepara un sofrito con el pollo y las verduras en una cazuela apta para horno. Añade el arroz, tomate, pimentón y el doble de caldo caliente que de arroz, y hornea a 190°C durante 25-30 minutos hasta que el arroz absorba el líquido y esté tierno."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Trocea y sofríe las verduras, luego dora el pollo. Incorpora el arroz, tomate, pimentón y el caldo (doble de agua que de arroz), y cocina a 100°C, giro inverso, velocidad cuchara, durante 20-22 minutos, hasta que el arroz esté en su punto."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sofríe el pollo y las verduras en la olla abierta. Añade el arroz, tomate, pimentón y el caldo (1.5 veces el volumen de arroz), cierra la olla y cocina a presión media-alta durante 8-10 minutos desde que sube la válvula. Deja reposar unos minutos antes de abrir."}]'::jsonb, '{}'),
  ('pasta_arroces_008', 'Fideos con carne', 'pasta_arroces', 'cerdo', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 472, 24, 54, 18, 2, true, true, '{"gluten"}', '[{"name":"Fideos gruesos","amount":180,"unit":"g"},{"name":"Carne picada de cerdo","amount":200,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"}]'::jsonb, '{"Dorar la carne picada y reservar","Sofreír cebolla, pimiento y ajo, añadir tomate y pimentón","Tostar los fideos en la salsa, añadir caldo","Incorporar la carne y cocer 12 min"}', 'Fideos gruesos guisados con carne picada y sofrito', '[{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Pica la cebolla, pimiento y ajo. Sofríe con aceite, añade la carne y sofríe. Incorpora el tomate, pimentón, fideos y agua/caldo. Cocina a temperatura y tiempo indicados para los fideos."}]'::jsonb, '{}'),
  ('pasta_arroces_009', 'Arroz a la cubana', 'pasta_arroces', 'huevo', NULL, ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 468, 14, 62, 18, 2, true, false, '{"huevo"}', '[{"name":"Arroz","amount":180,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Tomate triturado","amount":200,"unit":"ml"},{"name":"Plátano macho","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"}]'::jsonb, '{"Cocer el arroz blanco 18 min","Hacer salsa de tomate con ajo","Freír los huevos y el plátano en rodajas","Servir arroz con tomate, huevo y plátano"}', 'Arroz blanco con tomate frito, huevo frito y plátano', '[]'::jsonb, '{}'),
