  ('pasta_arroces_011', 'Arroz con verduras', 'pasta_arroces', 'none', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 368, 8, 58, 12, 2, true, true, '{}', '[{"name":"Arroz","amount":180,"unit":"g"},{"name":"Judías verdes","amount":80,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Pimiento rojo","amount":60,"unit":"g"},{"name":"Guisantes","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"}]'::jsonb, '{"Sofreír las verduras troceadas 5 min","Añadir tomate y pimentón, rehogar","Incorporar arroz y caldo caliente","Cocer 18 min a fuego lento sin remover"}', 'Arroz seco con verduras de temporada al estilo paella', '[{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Sofríe las verduras en una cazuela apta para horno. Añade el arroz, tomate, pimentón y el doble de agua caliente. Cubre bien y hornea a 190°C durante 30-35 minutos, hasta que el arroz absorba el líquido y quede suelto."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Trocea las verduras en el vaso y sofríelas con aceite. Incorpora el arroz, tomate, pimentón y el agua (aprox. el doble que de arroz). Cocina a 100°C, giro inverso, velocidad cuchara, durante unos 20-25 minutos, hasta que el arroz esté cocido."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sofríe las verduras en la olla abierta con aceite. Añade el arroz, tomate, pimentón y 1.5 veces su volumen de agua caliente. Cierra la olla y cocina a presión (posición 2) durante 5-7 minutos. Apaga el fuego y deja despresurizar sola."}]'::jsonb, '{}'),
  ('pasta_arroces_012', 'Espaguetis con gambas', 'pasta_arroces', 'marisco', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 438, 24, 56, 14, 2, true, true, '{"gluten","marisco"}', '[{"name":"Espaguetis","amount":200,"unit":"g"},{"name":"Gambas peladas","amount":200,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Guindilla","amount":1,"unit":"ud"},{"name":"Vino blanco","amount":40,"unit":"ml"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Cocer los espaguetis al dente","Saltear ajo y guindilla en aceite, añadir gambas","Verter vino blanco y dejar reducir","Mezclar con la pasta y perejil"}', 'Espaguetis salteados con gambas al ajillo y vino blanco', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Cocina la pasta en el vaso con agua y sal. Luego, en el mismo vaso, sofríe el ajo y la guindilla, añade las gambas y el vino blanco para hacer la salsa, y finalmente mezcla todo."}]'::jsonb, '{}'),
  ('pasta_arroces_013', 'Arroz negro', 'pasta_arroces', 'marisco', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 432, 20, 56, 14, 2, false, false, '{"moluscos","pescado"}', '[{"name":"Arroz","amount":180,"unit":"g"},{"name":"Sepia","amount":200,"unit":"g"},{"name":"Tinta de calamar","amount":8,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Caldo de pescado","amount":400,"unit":"ml"}]'::jsonb, '{"Sofreír sepia troceada con cebolla y ajo","Añadir tomate y la tinta disuelta en caldo","Incorporar el arroz y repartir bien","Cocer 18 min a fuego medio sin remover"}', 'Arroz teñido con tinta de calamar y sepia troceada', '[{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Se prepara el sofrito con la sepia en una cazuela apta para horno. Se añade el arroz, la tinta y el caldo caliente, se lleva a ebullición y se hornea a 180°C durante 20-25 minutos hasta que el arroz absorba el líquido y quede en su punto."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Pica cebolla y ajo, sofríe con aceite. Añade la sepia y tomate, luego el arroz, la tinta y el caldo, programando 20-22 minutos a 100°C, giro inverso y velocidad cuchara hasta que el arroz esté cocido y jugoso."},{"appliance":"olla_express","time":25,"difficulty":"normal","prepSummary":"Se sofríen las verduras y la sepia en la olla. Se añade el arroz, la tinta y el caldo, se cierra la olla y se cocina a presión durante 7-8 minutos. Se despresuriza y se deja reposar unos minutos antes de servir."}]'::jsonb, '{}'),
