  ('pasta_arroces_017', 'Lasaña de carne', 'pasta_arroces', 'ternera', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, 'horno', 60, 'normal', 'all', 562, 28, 42, 30, 2, true, true, '{"gluten","lactosa","huevo"}', '[{"name":"Placas de lasaña","amount":120,"unit":"g"},{"name":"Carne picada de ternera","amount":250,"unit":"g"},{"name":"Tomate triturado","amount":250,"unit":"ml"},{"name":"Bechamel","amount":200,"unit":"ml"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Hacer boloñesa con carne, cebolla y tomate","Montar capas: placa, boloñesa, bechamel, repetir","Terminar con bechamel y queso rallado","Hornear a 190°C 30 min hasta gratinar"}', 'Lasaña de placas con ragú de ternera, bechamel y queso gratinado', '[{"appliance":"horno","time":65,"difficulty":"normal","prepSummary":"Prepara la carne y la bechamel por separado, monta la lasaña por capas en una fuente y hornea a 180-200°C durante 30-40 minutos hasta que el queso esté gratinado y burbujeante."},{"appliance":"airfryer","time":55,"difficulty":"normal","prepSummary":"Monta la lasaña en un molde pequeño apto para airfryer. Cocina a 170-180°C durante 25-30 minutos, vigilando que no se dore demasiado rápido y cubriendo si es necesario para un gratinado perfecto."}]'::jsonb, '{}'),
