  ('pasta_arroces_023', 'Fideuá de pollo', 'pasta_arroces', 'pollo', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 462, 28, 52, 16, 2, true, false, '{"gluten"}', '[{"name":"Fideos n°2","amount":180,"unit":"g"},{"name":"Contramuslo de pollo","amount":250,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Pimentón","amount":4,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Caldo de pollo","amount":400,"unit":"ml"}]'::jsonb, '{"Dorar el pollo troceado y reservar","Sofreír pimiento, ajo y tomate con pimentón","Tostar los fideos en la salsa, añadir caldo","Incorporar el pollo y cocer 12 min"}', 'Fideos tostados con pollo y pimiento en caldo', '[{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Sofreír el pollo y las verduras en una sartén apta para horno. Añadir los fideos y el caldo, llevar a ebullición y hornear a 200°C durante unos 15-20 minutos, hasta que los fideos absorban el líquido y se doren."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Sofreír el pollo y las verduras en el vaso. Incorporar los fideos y el caldo, programar temperatura Varoma, giro inverso y velocidad cuchara durante el tiempo necesario para que la pasta absorba el líquido."}]'::jsonb, '{}'),
  ('pasta_arroces_024', 'Ensalada de pasta', 'pasta_arroces', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'verano', 382, 12, 52, 14, 2, true, true, '{"gluten","sulfitos"}', '[{"name":"Fusilli","amount":200,"unit":"g"},{"name":"Tomate cherry","amount":100,"unit":"g"},{"name":"Aceitunas negras","amount":30,"unit":"g"},{"name":"Maíz dulce","amount":50,"unit":"g"},{"name":"Pepino","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vinagre","amount":10,"unit":"ml"}]'::jsonb, '{"Cocer la pasta al dente y enfriar bajo agua","Cortar tomates cherry, pepino y aceitunas","Mezclar todo con maíz","Aliñar con aceite y vinagre"}', 'Ensalada fría de pasta con tomate, aceitunas y maíz', '[]'::jsonb, '{}'),
  ('pasta_arroces_025', 'Risotto de champiñones', 'pasta_arroces', 'none', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'normal', 'invierno', 428, 10, 56, 18, 2, true, false, '{"lactosa"}', '[{"name":"Arroz arborio","amount":180,"unit":"g"},{"name":"Champiñones","amount":200,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Queso parmesano","amount":30,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Caldo de verduras","amount":500,"unit":"ml"}]'::jsonb, '{"Sofreír cebolla y champiñones en mantequilla","Añadir arroz, sofreír removiendo 1 min y verter vino","Ir añadiendo caldo caliente cucharón a cucharón removiendo","Fuera del fuego añadir parmesano y mantequilla"}', 'Risotto cremoso de champiñones con parmesano', '[{"appliance":"thermomix","time":28,"difficulty":"facil","prepSummary":"Sofríe la cebolla y los champiñones, luego tuesta el arroz con el vino. Incorpora el caldo y cocina 15-18 min a 100°C, velocidad cuchara, giro inverso, hasta obtener la cremosidad deseada, finalizando con mantequilla y parmesano."}]'::jsonb, '{}'),
  ('pescados_001', 'Merluza en salsa verde', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 25, 'facil', 'all', 286, 28, 6, 16, 2, true, true, '{"pescado","gluten"}', '[{"name":"Merluza en rodajas","amount":350,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Harina","amount":10,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Perejil","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Guisantes","amount":50,"unit":"g"}]'::jsonb, '{"Dorar ajos laminados en aceite y añadir harina","Verter vino y caldo de pescado, mover la cazuela","Colocar la merluza y los guisantes","Cocer 10 min a fuego suave moviendo la cazuela para ligar"}', 'Merluza en salsa verde con ajo, perejil y guisantes', '[{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Prepara la salsa verde en una cazuela apta para horno, sofriendo el ajo y añadiendo el resto de ingredientes. Incorpora las rodajas de merluza y los guisantes, y hornea a 190°C durante 20-25 minutos. Cubre con papel de aluminio los primeros 15 minutos para mantener la humedad y q"},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Sofríe el ajo en el vaso, añade la harina, el vino y el caldo para la salsa, cocinando a 100°C. Luego, incorpora la merluza y los guisantes, y cocina a 100°C, giro inverso, velocidad cuchara durante 8-10 minutos, asegurando que el pescado se cocine suavemente sin deshacerse."}]'::jsonb, '{}'),
  ('pescados_002', 'Salmón al horno con patatas', 'pescados', 'pescado_azul', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 35, 'facil', 'all', 468, 32, 26, 24, 2, true, true, '{"pescado"}', '[{"name":"Lomos de salmón","amount":300,"unit":"g"},{"name":"Patata","amount":250,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Eneldo","amount":3,"unit":"g"}]'::jsonb, '{"Cortar patatas y cebolla finas y colocar en bandeja con aceite","Hornear a 200°C durante 15 min","Colocar el salmón encima, rociar con limón y eneldo","Hornear 15 min más"}', 'Lomos de salmón asados al horno sobre cama de patatas', '[{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Precalienta el horno a 190°C. Cocina las patatas y cebolla en rodajas finas con aceite y sal durante 20 minutos, luego añade el salmón con limón y eneldo y hornea todo junto 15-20 minutos más hasta que el salmón esté tierno y las patatas doradas."},{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"Corta las patatas en rodajas finas y la cebolla en juliana. Cocínalas en la airfryer a 180°C durante 15-20 minutos, agitando a mitad. Añade el salmón con limón y eneldo, y cocina todo junto 10-12 minutos más a 190°C para un acabado crujiente y jugoso."}]'::jsonb, '{}'),
  ('pescados_003', 'Bacalao con tomate', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 30, 'facil', 'all', 312, 30, 12, 16, 2, true, true, '{"pescado"}', '[{"name":"Bacalao desalado","amount":350,"unit":"g"},{"name":"Tomate triturado","amount":250,"unit":"ml"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Sofreír cebolla, ajo y pimiento","Añadir tomate y cocer 10 min","Colocar el bacalao sobre la salsa","Tapar y cocer 12 min a fuego suave"}', 'Bacalao desalado guisado en salsa de tomate casera', '[{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Prepara un sofrito con las verduras en sartén, añade el tomate y el bacalao en una fuente de horno. Hornea a 180°C durante 20-25 minutos hasta que el bacalao esté tierno y la salsa reducida. Un truco es cubrir con papel de aluminio al principio para que el pescado no se seque."},{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Sofríe las verduras picadas en el vaso con aceite (10-12 min, Varoma, vel 1). Añade el tomate y cocina unos minutos. Incorpora el bacalao y programa 15-18 min, 100°C, giro inverso, vel cuchara. Asegúrate de que el bacalao quede jugoso."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Haz un sofrito con las verduras en la olla abierta. Añade el tomate y el bacalao. Cierra la olla y cocina a presión durante 3-5 minutos desde que sube la válvula, dependiendo del grosor del bacalao. Despresuriza y sirve. El truco es no sobrecocer el pescado para que no se deshaga"}]'::jsonb, '{}'),
  ('pescados_004', 'Sardinas a la plancha', 'pescados', 'pescado_azul', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'verano', 342, 26, 1, 26, 2, false, false, '{"pescado"}', '[{"name":"Sardinas","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Limpiar y salar las sardinas","Calentar la plancha a fuego fuerte","Cocinar 3 min por cada lado","Servir con aceite, ajo picado, perejil y limón"}', 'Sardinas frescas a la plancha con ajo y limón', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Cocina las sardinas previamente salpimentadas y untadas en aceite durante 10-12 minutos, volteándolas a mitad para un dorado uniforme y crujiente."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con función grill si es posible. Coloca las sardinas en una bandeja con papel de horno y cocina 10-12 minutos, dándoles un golpe de grill al final para un exterior dorado."}]'::jsonb, '{}'),
  ('pescados_005', 'Lubina al horno', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'completo', NULL, 'horno', 35, 'facil', 'all', 298, 32, 8, 14, 2, true, false, '{"pescado"}', '[{"name":"Lubina entera","amount":500,"unit":"g"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Hacer una cama de patata y cebolla en rodajas finas","Hornear las verduras 15 min a 200°C","Colocar la lubina encima con limón y perejil","Hornear 18 min más"}', 'Lubina entera al horno sobre cama de patata y cebolla', '[{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Precalienta el horno a 190°C. Dispón la lubina sobre una cama de patatas y cebolla laminadas, riega con aceite y limón, y hornea hasta que esté tierna y dorada."},{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 180°C. Coloca la lubina y las verduras cortadas finas en la cesta, rocía con aceite y cocina unos 25 minutos, volteando las verduras a mitad para una cocción uniforme."}]'::jsonb, '{}'),
  ('pescados_006', 'Atún a la plancha', 'pescados', 'pescado_azul', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 10, 'facil', 'all', 308, 36, 1, 18, 2, true, true, '{"pescado"}', '[{"name":"Rodajas de atún fresco","amount":300,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Salpimentar las rodajas de atún","Calentar la plancha a fuego fuerte con aceite","Cocinar 2 min por cada lado dejando el centro rosado","Servir con ajo picado y limón"}', 'Rodajas de atún fresco a la plancha, rosadas por dentro', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Marinar el atún con aceite de oliva, ajo picado, sal y pimienta. Precalentar la airfryer a 190-200°C. Cocinar el atún unos 8-12 minutos, volteando a mitad, para lograr un exterior dorado y un interior jugoso, sirviendo con limón."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Marinar el atún con aceite de oliva, ajo picado, sal y pimienta. Precalentar el horno a 200-220°C, preferiblemente con función grill. Colocar el atún en una bandeja y cocinar 8-12 minutos, según el grosor, hasta que esté sellado por fuera y tierno por dentro, sirviendo con limón."}]'::jsonb, '{}'),
  ('pescados_007', 'Merluza rebozada', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 368, 28, 18, 20, 2, true, true, '{"pescado","gluten","huevo"}', '[{"name":"Merluza en rodajas","amount":350,"unit":"g"},{"name":"Harina","amount":40,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Salpimentar la merluza y secar con papel","Pasar por harina y huevo batido","Freír en aceite caliente hasta dorar","Escurrir y servir con limón"}', 'Rodajas de merluza rebozadas en huevo y harina', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Reboza la merluza como de costumbre. Rocía ligeramente con aceite de oliva y cocina en la airfryer precalentada a 190-200°C durante 15-18 minutos, dándole la vuelta a mitad de cocción para un dorado uniforme y crujiente."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200-220°C. Reboza la merluza, rocíala con un poco de aceite y colócala en una bandeja con papel de horno. Hornea durante 20-25 minutos, volteando a mitad, hasta que esté dorada y crujiente."}]'::jsonb, '{}'),
  ('pescados_008', 'Dorada al horno', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'completo', NULL, 'horno', 35, 'facil', 'all', 306, 34, 6, 14, 2, true, false, '{"pescado"}', '[{"name":"Dorada entera","amount":500,"unit":"g"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Tomate","amount":100,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Hacer cama de patata, cebolla y tomate en rodajas","Hornear las verduras 15 min a 200°C","Colocar la dorada con limón dentro","Hornear 18 min más"}', 'Dorada entera al horno con patata, tomate y cebolla', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Precalienta el horno a 190°C. Coloca la dorada con las patatas y verduras cortadas en una bandeja, riega con aceite y limón. Hornea durante 35-40 minutos hasta que esté tierna y dorada."},{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Corta las patatas muy finas y las verduras en juliana. Cocina la dorada con las verduras y un chorrito de aceite durante 20-25 minutos, volteando a mitad para una cocción uniforme y piel crujiente."}]'::jsonb, '{}'),
  ('pescados_009', 'Salmón a la plancha', 'pescados', 'pescado_azul', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 12, 'facil', 'all', 378, 30, 1, 28, 2, true, true, '{"pescado"}', '[{"name":"Lomos de salmón","amount":300,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Eneldo","amount":3,"unit":"g"}]'::jsonb, '{"Salpimentar los lomos de salmón","Cocinar a la plancha con aceite, piel abajo, 4 min","Dar la vuelta y cocinar 2 min más","Servir con limón y eneldo"}', 'Lomos de salmón a la plancha con la piel crujiente', '[{"appliance":"airfryer","time":12,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Unta el salmón con aceite de oliva, eneldo y un poco de sal. Cocina durante 10-12 minutos, volteando a mitad, hasta que esté dorado y jugoso. Sirve con limón."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Coloca el salmón untado con aceite de oliva y eneldo en una bandeja. Hornea durante 12-15 minutos hasta que esté cocido y ligeramente dorado. Sirve con un chorrito de limón."}]'::jsonb, '{}'),
  ('pescados_010', 'Bacalao al pil-pil', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 25, 'elaborada', 'all', 362, 28, 2, 26, 2, false, false, '{"pescado"}', '[{"name":"Bacalao desalado","amount":350,"unit":"g"},{"name":"Aceite de oliva","amount":80,"unit":"ml"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Guindilla","amount":1,"unit":"ud"}]'::jsonb, '{"Confitar ajos laminados y guindilla en aceite a fuego lento","Retirar ajos y colocar el bacalao piel arriba","Cocer a fuego muy suave 10 min","Mover la cazuela en vaivén para que ligue la salsa"}', 'Bacalao confitado en aceite de oliva ligado con su gelatina', '[{"appliance":"thermomix","time":20,"difficulty":"normal","prepSummary":"Confitar el bacalao a baja temperatura (aprox. 80°C) con el aceite, ajo y guindilla durante unos 15 minutos. Retirar el bacalao y emulsionar el aceite restante a velocidad progresiva (3-4) hasta obtener la salsa pil-pil, unos 5 minutos."}]'::jsonb, '{}'),
  ('pescados_011', 'Calamares a la romana', 'pescados', 'marisco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 356, 22, 26, 18, 2, true, false, '{"moluscos","gluten","huevo"}', '[{"name":"Calamares","amount":300,"unit":"g"},{"name":"Harina","amount":60,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":50,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Limpiar y cortar los calamares en anillas","Pasar por harina y huevo batido","Freír en aceite muy caliente 2 min","Escurrir y servir con limón"}', 'Anillas de calamar rebozadas en harina y huevo, fritas', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190-200°C. Rocía los calamares rebozados con un poco de aceite y cocínalos en tandas durante 12-15 minutos, dándoles la vuelta a mitad, hasta que estén dorados y crujientes."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con ventilador. Coloca los calamares rebozados en una bandeja con papel de horno, rocía con aceite y hornea 15-20 minutos, volteándolos a mitad, hasta que estén dorados."}]'::jsonb, '{}'),
  ('pescados_012', 'Gambas al ajillo', 'pescados', 'marisco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 10, 'facil', 'all', 268, 22, 3, 18, 2, true, false, '{"marisco"}', '[{"name":"Gambas peladas","amount":250,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Guindilla","amount":1,"unit":"ud"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Calentar aceite con ajos laminados y guindilla","Cuando el ajo empiece a dorar, añadir las gambas","Saltear 2 min a fuego fuerte","Retirar del fuego y añadir perejil"}', 'Gambas salteadas en aceite de oliva con ajo y guindilla', '[{"appliance":"horno","time":18,"difficulty":"facil","prepSummary":"Combina las gambas, ajo laminado, guindilla y aceite en una cazuela de barro o fuente apta para horno. Hornea a 200°C durante 10-12 minutos hasta que las gambas estén rosadas y el ajo ligeramente dorado. Sirve espolvoreado con perejil."},{"appliance":"airfryer","time":13,"difficulty":"facil","prepSummary":"En un recipiente pequeño apto para airfryer (tipo ramekin o cazuelita), mezcla las gambas, ajo laminado, guindilla y aceite. Cocina en la airfryer precalentada a 190°C durante 8-10 minutos, agitando a mitad, hasta que las gambas estén hechas y el ajo fragante. Añade perejil al se"}]'::jsonb, '{}'),
  ('pescados_013', 'Merluza al horno con verduras', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 35, 'facil', 'all', 296, 30, 14, 12, 2, true, true, '{"pescado"}', '[{"name":"Merluza en lomos","amount":350,"unit":"g"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Tomate","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Colocar verduras en rodajas en bandeja con aceite","Hornear 15 min a 200°C","Poner la merluza encima con limón","Hornear 15 min más"}', 'Lomos de merluza al horno sobre verduras asadas', '[{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Precalienta el horno a 180-200°C. Dispón las patatas y verduras cortadas en una bandeja con aceite, hornea unos 15-20 min, luego añade la merluza y hornea 15-20 min más hasta que el pescado esté tierno y las verduras doradas."},{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Corta las patatas y verduras muy finas para asegurar una cocción uniforme. Precalienta la airfryer a 180°C, cocina las verduras con un poco de aceite durante 10-15 min, luego añade la merluza y cocina 8-10 min más hasta que esté cocida y ligeramente dorada."}]'::jsonb, '{}'),
  ('pescados_014', 'Bacalao rebozado', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 388, 30, 20, 22, 2, true, true, '{"pescado","gluten","huevo"}', '[{"name":"Bacalao desalado","amount":350,"unit":"g"},{"name":"Harina","amount":40,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":45,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Cortar el bacalao en trozos y secar bien","Pasar por harina y huevo batido","Freír en aceite caliente hasta dorar","Escurrir y servir con limón"}', 'Trozos de bacalao desalado rebozados en harina y huevo', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190-200°C. Rocía ligeramente el bacalao rebozado con aceite y cocina durante 15-18 minutos, dándole la vuelta a mitad de cocción, hasta que esté dorado y crujiente."},{"appliance":"horno","time":22,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con calor arriba y abajo. Coloca el bacalao rebozado en una bandeja con papel de horno y hornea durante 20-25 minutos, o hasta que esté dorado y cocido por dentro. Un chorrito de aceite sobre el rebozado ayuda a que quede más crujiente."}]'::jsonb, '{}'),
  ('pescados_015', 'Trucha a la navarra', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 392, 34, 8, 24, 2, true, false, '{"pescado","gluten"}', '[{"name":"Truchas enteras","amount":400,"unit":"g"},{"name":"Jamón serrano","amount":60,"unit":"g"},{"name":"Harina","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Rellenar cada trucha con lonchas de jamón","Enharinar por fuera","Freír en aceite con ajo 5 min por lado","Servir con limón"}', 'Trucha entera rellena de jamón serrano, enharinada y frita', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Rellena la trucha enharinada con el jamón, pincela con aceite y cocina 18 minutos, volteando a mitad, hasta que esté dorada. El truco es un ligero pincelado de aceite para el crujiente exterior."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Rellena la trucha con el jamón, sazona, rocía con aceite y hornea 20 minutos hasta que esté hecha y ligeramente dorada. El truco es un refrito de ajo en sartén para verter por encima al servir."}]'::jsonb, '{}'),
  ('pescados_016', 'Rape en salsa marinera', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 30, 'normal', 'all', 312, 30, 10, 16, 2, true, true, '{"pescado","moluscos","gluten"}', '[{"name":"Rape","amount":350,"unit":"g"},{"name":"Almejas","amount":100,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Harina","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Sofreír cebolla y ajo, añadir harina","Incorporar vino blanco y caldo","Añadir el rape troceado y cocer 10 min","Incorporar las almejas y cocer hasta que se abran"}', 'Rape guisado en salsa marinera con almejas y vino blanco', '[{"appliance":"horno","time":30,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el ajo en una cazuela apta para horno. Añade la harina, el vino y un poco de caldo, integra el rape y las almejas. Hornea a 180°C durante 15-20 minutos hasta que el pescado esté tierno y las almejas se abran. Un truco es cubrir con papel de aluminio para que n"},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Trocea cebolla y ajo, sofríe en el vaso con aceite. Añade la harina, el vino y un poco de agua o caldo, y cocina la salsa. Incorpora el rape y las almejas, cocinando a temperatura Varoma o a 90°C, velocidad cuchara, hasta que el pescado esté en su punto y las almejas abiertas. El"}]'::jsonb, '{}'),
  ('pescados_017', 'Palitos de merluza caseros', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 348, 26, 22, 18, 2, true, true, '{"pescado","gluten","huevo"}', '[{"name":"Merluza en lomos","amount":300,"unit":"g"},{"name":"Pan rallado","amount":50,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Harina","amount":25,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Cortar la merluza en bastones gruesos","Pasar por harina, huevo y pan rallado","Freír en aceite caliente hasta dorar","Escurrir sobre papel absorbente"}', 'Bastones de merluza empanados caseros, ideal para niños', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C y cocina los palitos de merluza durante 12-15 minutos, volteándolos a mitad de cocción para un dorado uniforme y una textura crujiente."},{"appliance":"horno","time":18,"difficulty":"facil","prepSummary":"Hornea los palitos a 200°C con calor arriba y abajo durante 15-20 minutos, o hasta que estén bien dorados y crujientes, dándoles la vuelta una vez a mitad de cocción."}]'::jsonb, '{}'),
  ('pescados_018', 'Salmón en papillote', 'pescados', 'pescado_azul', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, 'horno', 25, 'facil', 'all', 382, 30, 8, 26, 2, true, true, '{"pescado"}', '[{"name":"Lomos de salmón","amount":300,"unit":"g"},{"name":"Calabacín","amount":100,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Puerro","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Eneldo","amount":3,"unit":"g"}]'::jsonb, '{"Cortar verduras en juliana fina","Colocar cada lomo sobre papel de horno con las verduras","Aliñar con aceite, limón y eneldo, cerrar el paquete","Hornear a 200°C durante 18 min"}', 'Salmón cocinado al vapor en papillote con verduras en juliana', '[{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 180-200°C. Envuelve el salmón y las verduras con aceite, limón y eneldo en papel de horno o aluminio, sellando bien. Hornea durante 20-25 minutos para un resultado jugoso."},{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 180°C. Prepara los papillotes en papel de aluminio bien sellado para evitar que se abran. Cocina durante 15-20 minutos, comprobando que el pescado esté en su punto."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Vierte 500-700ml de agua en el vaso. Coloca los papillotes (en papel de horno o aluminio) en el recipiente Varoma. Cocina 20-25 minutos, Varoma, velocidad 1, asegurando una cocción uniforme al vapor."},{"appliance":"vaporera","time":22,"difficulty":"facil","prepSummary":"Prepara los papillotes con todos los ingredientes bien sellados. Llena la base de la vaporera con agua y coloca los paquetes en la cesta. Cocina al vapor durante 20-25 minutos hasta que el salmón esté tierno."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Añade 250ml de agua a la olla y coloca una rejilla. Pon los papillotes bien cerrados sobre la rejilla. Cocina a presión alta durante 5-7 minutos y libera la presión rápidamente para evitar que el salmón se seque."}]'::jsonb, '{}'),
  ('pescados_019', 'Atún encebollado', 'pescados', 'pescado_azul', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 25, 'facil', 'all', 362, 34, 10, 20, 2, true, true, '{"pescado"}', '[{"name":"Atún fresco","amount":300,"unit":"g"},{"name":"Cebolla","amount":200,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Pochar la cebolla en juliana a fuego lento 15 min","Añadir tomate, vino y laurel","Colocar el atún sobre la cebolla","Tapar y cocer 8 min a fuego suave"}', 'Atún fresco guisado sobre cama de cebolla pochada al vino', '[{"appliance":"horno","time":35,"difficulty":"normal","prepSummary":"Sofríe la cebolla en una cazuela apta para horno hasta que esté tierna. Añade el resto de ingredientes, cubre y hornea a 180°C durante 25-30 minutos, o hasta que el atún esté cocido y la salsa reducida, para una cocción uniforme y sabores concentrados."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Trocea la cebolla y sofríela con aceite a 120°C, velocidad cuchara, durante 10 min. Incorpora el resto de ingredientes (excepto el atún), programa 10 min, 100°C, velocidad cuchara. Añade el atún en trozos y cocina 5-7 min más, 100°C, giro inverso, velocidad cuchara, para un guiso"},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Sofríe la cebolla en la olla abierta con aceite. Añade el tomate, vino y laurel, cierra y cocina a presión durante 5 minutos. Abre, incorpora el atún en trozos y cocina sin tapa a fuego medio otros 5-7 minutos hasta que el atún esté hecho y la salsa reducida, logrando un guiso rá"}]'::jsonb, '{}'),
  ('pescados_020', 'Emperador a la plancha', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 12, 'facil', 'all', 282, 32, 1, 16, 2, true, true, '{"pescado"}', '[{"name":"Rodajas de emperador","amount":300,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Salpimentar las rodajas de emperador","Cocinar a la plancha con aceite 3 min por lado","Hacer salsa rápida con ajo, perejil y limón","Verter sobre el pescado al servir"}', 'Rodajas de pez espada a la plancha con ajo y perejil', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Marina el emperador con el aceite, ajo y perejil. Precalienta la airfryer a 190°C y cocina el pescado durante 12-15 minutos, dándole la vuelta a mitad para un dorado uniforme y una textura jugosa."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con función grill o calor arriba y abajo. Coloca el emperador marinado con aceite, ajo y perejil en una bandeja y hornea/gratina durante 10-15 minutos hasta que esté cocido y ligeramente dorado."}]'::jsonb, '{}'),
  ('pescados_021', 'Fideuá', 'pescados', 'marisco', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'normal', 'all', 448, 24, 48, 18, 2, true, false, '{"gluten","marisco","pescado","moluscos"}', '[{"name":"Fideos n°2","amount":180,"unit":"g"},{"name":"Gambas","amount":150,"unit":"g"},{"name":"Sepia","amount":100,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"},{"name":"Caldo de pescado","amount":400,"unit":"ml"}]'::jsonb, '{"Sofreír sepia y gambas y reservar","Tostar los fideos con ajo y tomate","Añadir pimentón y caldo caliente","Cocer 10 min, incorporar el marisco y dejar reposar"}', 'Fideos tostados con gambas y sepia en caldo de pescado', '[{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Sella las gambas y la sepia, y sofríe el ajo y tomate en una paellera o cazuela apta para horno. Añade los fideos y tuéstalos ligeramente antes de incorporar el caldo caliente. Termina la cocción en el horno precalentado a 200°C durante unos 15-20 minutos, hasta que los fideos ab"}]'::jsonb, '{}'),
  ('pescados_022', 'Rosada al horno con limón', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, 'horno', 25, 'facil', 'all', 262, 30, 4, 14, 2, true, true, '{"pescado"}', '[{"name":"Rosada en lomos","amount":350,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Vino blanco","amount":40,"unit":"ml"}]'::jsonb, '{"Colocar los lomos en bandeja de horno","Aliñar con aceite, ajo laminado, limón y vino","Hornear a 190°C durante 18 min","Espolvorear perejil al servir"}', 'Lomos de rosada al horno con limón, ajo y vino blanco', '[{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 190°C. Coloca la rosada en una bandeja de horno junto con el limón en rodajas, ajo picado, perejil, un chorrito de aceite y el vino blanco. Hornea durante 20-25 minutos hasta que el pescado esté tierno y jugoso, evitando el sobrecocinado para mantener su te"},{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 180°C. Dispón la rosada en la cesta con el resto de ingredientes, asegurándote de que el limón y el ajo estén bien distribuidos. Cocina por 12-15 minutos, revisando el punto de cocción para que quede jugosa por dentro y ligeramente dorada por fuera."}]'::jsonb, '{}'),
  ('pescados_023', 'Boquerones en vinagre', 'pescados', 'pescado_azul', NULL, ARRAY['primero','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'verano', 218, 20, 2, 14, 2, false, true, '{"pescado","sulfitos"}', '[{"name":"Boquerones frescos","amount":300,"unit":"g"},{"name":"Vinagre","amount":150,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Limpiar y abrir los boquerones en mariposa","Cubrir con vinagre y dejar marinar 4 h en nevera","Escurrir bien y aliñar con ajo, perejil y aceite","Servir fríos"}', 'Boquerones marinados en vinagre con ajo y perejil', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Utiliza la Thermomix para picar finamente el ajo y el perejil (unos segundos a velocidad 7). Luego, añade el aceite de oliva y emulsiona a velocidad 4-5 para crear un aliño homogéneo y aromático para los boquerones ya limpios y marinados."}]'::jsonb, '{}'),
  ('pescados_024', 'Pescadilla al horno', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'completo', NULL, 'horno', 30, 'facil', 'all', 272, 28, 10, 12, 2, true, true, '{"pescado"}', '[{"name":"Pescadilla en lomos","amount":350,"unit":"g"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Disponer patata y cebolla en rodajas en bandeja","Hornear 15 min a 200°C","Colocar la pescadilla encima con limón y aceite","Hornear 12 min más y servir con perejil"}', 'Lomos de pescadilla al horno con patata y cebolla', '[{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Precalentar el horno a 190°C. Extender las patatas y cebolla en rodajas finas con aceite en una bandeja y hornear 15-20 min. Añadir la pescadilla, salpimentar, rociar con limón y aceite, y hornear 10-12 min más hasta que el pescado esté en su punto."},{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Precalentar la airfryer a 180°C. Cocinar las patatas y cebolla en rodajas finas con un poco de aceite durante 15-18 minutos, removiendo a mitad. Incorporar la pescadilla, salpimentar y rociar con limón, cocinando 7-9 minutos adicionales hasta que el pescado esté tierno y dorado."}]'::jsonb, '{}'),
  ('pescados_025', 'Calamares encebollados', 'pescados', 'marisco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 30, 'facil', 'all', 298, 22, 12, 18, 2, true, true, '{"moluscos"}', '[{"name":"Calamares","amount":300,"unit":"g"},{"name":"Cebolla","amount":200,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Pochar la cebolla en juliana a fuego lento 10 min","Añadir los calamares en anillas con ajo","Verter el vino y añadir laurel","Tapar y cocer 15 min a fuego suave"}', 'Calamares en anillas guisados con abundante cebolla pochada', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Pocha la cebolla y el ajo en una cazuela apta para horno. Añade los calamares, el vino, el laurel y un poco de agua si es necesario. Tapa y cocina en el horno precalentado a 180°C durante 30-35 minutos, hasta que los calamares estén tiernos."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Pica la cebolla y el ajo, sofríe con aceite. Incorpora los calamares troceados, el vino blanco y el laurel. Cocina a temperatura Varoma, giro inverso, velocidad cuchara durante 25-30 minutos, hasta que los calamares estén tiernos y la salsa reducida."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo en la olla a presión. Añade los calamares, el vino, el laurel y un chorrito de agua. Cierra la olla y cocina durante 8-10 minutos desde que sube la válvula. Despresuriza y, si es necesario, reduce la salsa a fuego vivo sin tapa."}]'::jsonb, '{}'),
  ('platos_unicos_001', 'Paella valenciana', 'platos_unicos', 'pollo', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 528, 28, 58, 18, 2, true, false, '{}', '[{"name":"Arroz","amount":200,"unit":"g"},{"name":"Contramuslo de pollo","amount":200,"unit":"g"},{"name":"Judías verdes","amount":80,"unit":"g"},{"name":"Garrofón","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"},{"name":"Azafrán","amount":1,"unit":"g"}]'::jsonb, '{"Dorar el pollo en aceite en la paella","Añadir judías y garrofón, sofreír con tomate y pimentón","Verter agua caliente con azafrán y cocer 20 min","Añadir arroz, distribuir y cocer 18 min sin remover"}', 'Paella valenciana de pollo con judías verdes y garrofón', '[{"appliance":"horno","time":55,"difficulty":"normal","prepSummary":"Comienza dorando el pollo y las verduras en una paellera sobre la encimera. Añade el tomate, pimentón y arroz, luego el caldo con azafrán. Tras un hervor, hornea a 180°C durante 20-25 minutos hasta que el arroz absorba el líquido, logrando una cocción uniforme."}]'::jsonb, '{}'),
  ('platos_unicos_002', 'Pizza casera', 'platos_unicos', 'none', NULL, ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 40, 'normal', 'all', 518, 18, 62, 22, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Harina","amount":250,"unit":"g"},{"name":"Levadura fresca","amount":10,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Mozzarella","amount":125,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Orégano","amount":3,"unit":"g"}]'::jsonb, '{"Amasar harina con levadura, agua, sal y aceite","Dejar reposar 30 min tapada","Estirar la masa, cubrir con tomate y mozzarella","Hornear a 230°C durante 10 min"}', 'Pizza casera con masa fina, tomate y mozzarella', '[{"appliance":"horno","time":40,"difficulty":"normal","prepSummary":"Prepara la masa siguiendo la receta y estírala sobre una bandeja. Hornea la pizza en un horno precalentado a 200-220°C durante 15-20 minutos, hasta que la base esté dorada y el queso burbujeante y fundido."},{"appliance":"airfryer","time":35,"difficulty":"normal","prepSummary":"Amasa y forma una o varias pizzas pequeñas que quepan en la cesta de la airfryer. Cocínalas en la airfryer precalentada a 180-190°C durante 10-15 minutos, vigilando que la masa quede crujiente y el queso bien fundido."}]'::jsonb, '{}'),
  ('platos_unicos_003', 'Croquetas de jamón', 'platos_unicos', 'none', NULL, ARRAY['cena','plato_unico']::meal_role[], 'principal', NULL, NULL, 45, 'normal', 'all', 428, 14, 32, 28, 2, true, true, '{"gluten","lactosa","huevo"}', '[{"name":"Jamón serrano","amount":80,"unit":"g"},{"name":"Leche","amount":300,"unit":"ml"},{"name":"Harina","amount":50,"unit":"g"},{"name":"Mantequilla","amount":40,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Pan rallado","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":50,"unit":"ml"},{"name":"Nuez moscada","amount":2,"unit":"g"}]'::jsonb, '{"Hacer bechamel con mantequilla, harina y leche, añadir jamón picado","Enfriar la masa al menos 3 h en nevera","Formar croquetas y pasar por huevo y pan rallado","Freír en aceite caliente hasta dorar"}', 'Croquetas cremosas de bechamel con jamón serrano', '[{"appliance":"thermomix","time":40,"difficulty":"normal","prepSummary":"La Thermomix es ideal para la bechamel: funde la mantequilla, sofríe la harina y añade la leche progresivamente a 90°C, velocidad 4, durante unos 7-8 minutos hasta obtener una crema perfecta y sin grumos. Luego, se enfría la masa, se forman las croquetas y se fríen de forma tradicional en abundante aceite caliente."},{"appliance":"airfryer","time":50,"difficulty":"normal","prepSummary":"Una vez formadas y empanadas las croquetas, rocíalas ligeramente con aceite de oliva y cocínalas en la airfryer precalentada a 190-200°C durante 12-15 minutos, dándoles la vuelta a mitad de cocción, hasta que estén doradas y crujientes."},{"appliance":"horno","time":55,"difficulty":"normal","prepSummary":"Para una versión más ligera, hornea las croquetas ya empanadas. Precalienta el horno a 200°C con calor arriba y abajo, rocía las croquetas con un poco de aceite y hornea durante 20-25 minutos, girándolas una vez, hasta que estén doradas."}]'::jsonb, '{}'),
  ('platos_unicos_004', 'Empanada gallega de atún', 'platos_unicos', 'pescado_azul', NULL, ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 60, 'normal', 'all', 468, 20, 46, 22, 2, true, true, '{"gluten","pescado","huevo"}', '[{"name":"Harina","amount":250,"unit":"g"},{"name":"Atún en conserva","amount":160,"unit":"g"},{"name":"Cebolla","amount":120,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Huevo","amount":1,"unit":"ud"}]'::jsonb, '{"Hacer masa con harina, agua, aceite y sal","Sofreír cebolla, pimiento y tomate, añadir atún","Estirar la masa, rellenar y cerrar con otra capa","Pintar con huevo y hornear a 190°C 30 min"}', 'Empanada gallega de masa casera rellena de atún y pimiento', '[{"appliance":"horno","time":65,"difficulty":"normal","prepSummary":"Prepara la masa y el relleno. Hornea la empanada a 180-190°C durante 35-40 minutos, o hasta que esté dorada y crujiente. Un truco es pintar con huevo batido para un acabado brillante."},{"appliance":"airfryer","time":55,"difficulty":"normal","prepSummary":"Elabora la masa y el relleno. Forma una empanada de tamaño adecuado para tu airfryer y cocina a 170-180°C durante 20-25 minutos, volteándola a mitad, hasta que esté dorada. Asegúrate de no sobrecargar la cesta."}]'::jsonb, '{}'),
  ('platos_unicos_005', 'Empanadillas de atún', 'platos_unicos', 'pescado_azul', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 412, 18, 38, 22, 2, true, true, '{"gluten","pescado","huevo"}', '[{"name":"Obleas de empanadilla","amount":8,"unit":"ud"},{"name":"Atún en conserva","amount":120,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Pimiento verde","amount":50,"unit":"g"},{"name":"Huevo cocido","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Sofreír cebolla y pimiento, añadir tomate y atún","Incorporar huevo cocido picado y enfriar","Rellenar las obleas y cerrar con tenedor","Freír en aceite caliente u hornear a 200°C 15 min"}', 'Empanadillas rellenas de atún con pimiento y huevo', '[{"appliance":"airfryer","time":30,"difficulty":"facil","prepSummary":"Prepara el sofrito en sartén. Rellena las obleas y cocina en la airfryer precalentada a 180-190°C durante 12-15 minutos, dándoles la vuelta a mitad para un dorado uniforme y crujiente."},{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Elabora el sofrito en una sartén. Rellena las obleas, séllalas y píntalas con huevo o aceite antes de hornear a 190-200°C durante 15-20 minutos, hasta que estén doradas y crujientes."}]'::jsonb, '{}'),
  ('platos_unicos_006', 'Crepes de jamón y queso', 'platos_unicos', 'none', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 398, 18, 32, 22, 2, true, false, '{"gluten","huevo","lactosa"}', '[{"name":"Harina","amount":100,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Leche","amount":200,"unit":"ml"},{"name":"Jamón cocido","amount":80,"unit":"g"},{"name":"Queso en lonchas","amount":60,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"}]'::jsonb, '{"Batir harina, huevos y leche hasta masa fina","Hacer crepes finas en sartén con mantequilla","Rellenar con jamón y queso","Doblar y calentar para fundir el queso"}', 'Crepes finas rellenas de jamón cocido y queso fundido', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"La Thermomix es perfecta para preparar la masa de los crepes de forma rápida y sin grumos. Mezcla todos los ingredientes (harina, huevos, leche, mantequilla derretida) durante 30 segundos a velocidad 5. Luego, cocina los crepes en una sartén tradicional."},{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Tras cocinar los crepes en sartén y rellenarlos con jamón y queso, colócalos en una fuente apta para horno. Gratina a 180°C durante 8-10 minutos hasta que el queso se funda y los crepes estén calientes y ligeramente dorados."}]'::jsonb, '{}'),
  ('platos_unicos_007', 'Quiche de verduras', 'platos_unicos', 'huevo', NULL, ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 50, 'normal', 'all', 412, 14, 28, 28, 2, true, true, '{"gluten","huevo","lactosa"}', '[{"name":"Masa quebrada","amount":200,"unit":"g"},{"name":"Calabacín","amount":100,"unit":"g"},{"name":"Puerro","amount":80,"unit":"g"},{"name":"Huevo","amount":3,"unit":"ud"},{"name":"Nata","amount":100,"unit":"ml"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Forrar molde con masa quebrada y pinchar el fondo","Saltear calabacín y puerro en aceite","Batir huevos con nata y queso, mezclar con verduras","Verter sobre la masa y hornear a 180°C 30 min"}', 'Quiche de masa quebrada con calabacín, puerro y queso', '[{"appliance":"horno","time":65,"difficulty":"normal","prepSummary":"Precalienta el horno a 180°C. Hornea la masa quebrada unos minutos en blanco, luego añade el relleno de verduras sofritas con huevo, nata y queso. Hornea durante 45-50 minutos hasta que esté dorado y cuajado."},{"appliance":"airfryer","time":50,"difficulty":"normal","prepSummary":"Utiliza un molde apto para airfryer que quepa bien. Precalienta a 170°C. Cocina la masa quebrada unos 5-7 minutos, luego vierte el relleno y hornea por 30-35 minutos, vigilando que no se dore demasiado rápido por encima."}]'::jsonb, '{}'),
  ('platos_unicos_008', 'Patatas rellenas de carne', 'platos_unicos', 'ternera', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, 'horno', 50, 'normal', 'all', 462, 24, 38, 24, 2, true, true, '{"lactosa"}', '[{"name":"Patata grande","amount":4,"unit":"ud"},{"name":"Carne picada de ternera","amount":200,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Hornear patatas enteras 30 min a 200°C","Vaciar parcialmente y reservar la pulpa","Sofreír carne con cebolla y tomate, mezclar con pulpa","Rellenar, añadir queso y gratinar 10 min"}', 'Patatas asadas rellenas de carne picada gratinadas con queso', '[{"appliance":"horno","time":60,"difficulty":"normal","prepSummary":"Hornea las patatas enteras a 200°C hasta que estén tiernas (aprox. 40-50 min). Vacía la pulpa, mezcla con el sofrito de carne y cebolla, rellena las patatas, cubre con queso y gratina a 180°C durante 15-20 min hasta dorar."},{"appliance":"airfryer","time":50,"difficulty":"normal","prepSummary":"Cocina las patatas en la airfryer a 190°C durante 30-40 min hasta que estén tiernas. Vacía la pulpa, mezcla con el relleno de carne previamente cocinado, rellena las patatas, espolvorea queso y cocina en la airfryer a 180°C por 10-15 min hasta que el queso esté fundido y dorado."}]'::jsonb, '{}'),
  ('platos_unicos_009', 'Wrap de pollo', 'platos_unicos', 'pollo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 382, 28, 32, 16, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Tortilla de trigo","amount":2,"unit":"ud"},{"name":"Pechuga de pollo","amount":200,"unit":"g"},{"name":"Lechuga","amount":50,"unit":"g"},{"name":"Tomate","amount":80,"unit":"g"},{"name":"Yogur natural","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Hacer el pollo a la plancha y cortar en tiras","Trocear lechuga y tomate","Mezclar yogur con un poco de limón y sal","Montar los wraps y enrollar"}', 'Tortilla de trigo enrollada con pollo a la plancha y verduras', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Corta la pechuga en tiras, rocía con aceite y cocina en la airfryer a 190°C durante 12-15 minutos, volteando a mitad, hasta que esté dorada y jugosa. Calienta las tortillas brevemente al final para que queden flexibles."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Hornea la pechuga de pollo cortada en tiras a 200°C durante 15-20 minutos, dándole la vuelta para que se dore uniformemente y quede cocida. Puedes calentar las tortillas en el horno durante los últimos minutos para ablandarlas."}]'::jsonb, '{}'),
  ('platos_unicos_010', 'Croquetas de bacalao', 'platos_unicos', 'pescado_blanco', NULL, ARRAY['cena','plato_unico']::meal_role[], 'principal', NULL, NULL, 45, 'normal', 'all', 418, 18, 30, 26, 2, true, true, '{"gluten","lactosa","huevo","pescado"}', '[{"name":"Bacalao desalado","amount":120,"unit":"g"},{"name":"Leche","amount":300,"unit":"ml"},{"name":"Harina","amount":50,"unit":"g"},{"name":"Mantequilla","amount":40,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Pan rallado","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":50,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Hacer bechamel con mantequilla, harina y leche","Añadir bacalao desmigado y perejil, enfriar 3 h","Formar croquetas y empanar con huevo y pan rallado","Freír en aceite caliente hasta dorar"}', 'Croquetas cremosas de bechamel con bacalao desmigado', '[{"appliance":"airfryer","time":45,"difficulty":"normal","prepSummary":"Una vez formadas y empanadas, las croquetas se cocinan en la airfryer a 195°C durante 12-15 minutos, rociadas ligeramente con aceite, hasta que estén doradas y crujientes, volteándolas a mitad de cocción."},{"appliance":"horno","time":50,"difficulty":"normal","prepSummary":"Tras formar y empanar las croquetas, se hornean a 200°C durante 18-22 minutos en una bandeja con papel de horno y un poco de aceite, hasta que estén doradas y crujientes, volteándolas a mitad de cocción."},{"appliance":"thermomix","time":40,"difficulty":"normal","prepSummary":"La Thermomix es ideal para cocer el bacalao y elaborar la bechamel de forma rápida y sin grumos. Una vez lista la masa de croquetas, se enfría, se forman y se fríen de la manera tradicional o se cocinan en airfryer/horno para el acabado final."}]'::jsonb, '{}'),
  ('platos_unicos_011', 'Migas manchegas', 'platos_unicos', 'cerdo', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'normal', 'invierno', 498, 16, 42, 28, 2, true, false, '{"gluten"}', '[{"name":"Pan del día anterior","amount":200,"unit":"g"},{"name":"Chorizo","amount":60,"unit":"g"},{"name":"Panceta","amount":60,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Pimentón","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Uvas","amount":60,"unit":"g"}]'::jsonb, '{"Humedecer el pan desmigado la noche anterior","Freír ajo, panceta y chorizo en aceite","Añadir pimentón y el pan húmedo","Remover a fuego medio hasta que las migas queden sueltas"}', 'Migas de pan con chorizo, panceta y uvas', '[]'::jsonb, '{}'),
  ('platos_unicos_012', 'Pimientos rellenos de arroz', 'platos_unicos', 'none', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, 'horno', 45, 'normal', 'all', 368, 10, 48, 14, 2, true, true, '{}', '[{"name":"Pimientos rojos","amount":4,"unit":"ud"},{"name":"Arroz","amount":150,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Champiñones","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"}]'::jsonb, '{"Cocer el arroz y mezclar con cebolla, ajo y champiñones sofritos","Vaciar los pimientos por arriba","Rellenar con el arroz y cubrir con tomate","Hornear a 190°C 25 min"}', 'Pimientos rojos rellenos de arroz con champiñones', '[{"appliance":"horno","time":65,"difficulty":"normal","prepSummary":"Prepara el sofrito con cebolla, ajo, champiñones, arroz y tomate triturado. Rellena los pimientos partidos por la mitad y hornea a 180-190°C durante unos 45-50 minutos, hasta que los pimientos estén tiernos y el relleno ligeramente gratinado."},{"appliance":"airfryer","time":55,"difficulty":"normal","prepSummary":"Prepara el relleno en una sartén. Rellena los pimientos y colócalos en la cesta de la airfryer. Cocina a 170-180°C durante 30-35 minutos, girando a mitad de cocción y añadiendo un poco de agua en la base si es necesario para mantener la humedad y evitar que se sequen."}]'::jsonb, '{}'),
  ('platos_unicos_013', 'Calzone casero', 'platos_unicos', 'none', NULL, ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 40, 'normal', 'all', 492, 20, 56, 22, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Harina","amount":250,"unit":"g"},{"name":"Levadura fresca","amount":10,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Mozzarella","amount":100,"unit":"g"},{"name":"Jamón cocido","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Hacer masa de pizza con harina, levadura, agua y aceite","Estirar en círculo y rellenar la mitad con tomate, mozzarella y jamón","Doblar y sellar los bordes con tenedor","Hornear a 220°C 15 min hasta dorar"}', 'Pizza cerrada rellena de tomate, mozzarella y jamón', '[{"appliance":"horno","time":95,"difficulty":"normal","prepSummary":"Precalienta el horno a 190-200°C. Hornea el calzone durante 35-40 minutos o hasta que esté bien dorado y el queso burbujee."},{"appliance":"airfryer","time":80,"difficulty":"normal","prepSummary":"Precalienta la airfryer a 175-185°C. Cocina el calzone (o calzones pequeños) durante 25-30 minutos, volteándolo a mitad del tiempo para un dorado uniforme."}]'::jsonb, '{}'),
  ('platos_unicos_014', 'Tostas de aguacate y huevo', 'platos_unicos', 'huevo', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 342, 14, 28, 20, 2, true, false, '{"gluten","huevo"}', '[{"name":"Pan de hogaza","amount":120,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Tomate cherry","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Tostar las rebanadas de pan","Aplastar aguacate con limón y sal","Hacer los huevos a la plancha o poché","Montar las tostas con aguacate, huevo y tomates cherry"}', 'Tostadas de pan con aguacate machacado y huevo', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Tuesta el pan a 190°C durante 4-5 minutos hasta que esté dorado. Para el huevo, fríelo en un molde apto para airfryer a 160°C durante 8-10 minutos, logrando una yema jugosa."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Tuesta las rebanadas de pan directamente en la rejilla durante 5-7 minutos. Para los huevos, hornéalos en cuencos individuales ligeramente engrasados durante 10-12 minutos hasta que la clara esté cuajada y la yema líquida."}]'::jsonb, '{}'),
  ('platos_unicos_015', 'Patatas bravas con huevo', 'platos_unicos', 'huevo', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 448, 14, 42, 26, 2, true, false, '{"huevo"}', '[{"name":"Patata","amount":400,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Aceite de oliva","amount":50,"unit":"ml"},{"name":"Pimentón picante","amount":4,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"}]'::jsonb, '{"Cortar patatas en dados y freír hasta dorar","Hacer salsa brava con tomate, ajo y pimentón picante","Freír los huevos con la yema líquida","Servir patatas con salsa y huevo encima"}', 'Patatas fritas en dados con salsa brava y huevo frito', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Para las patatas, córtalas en dados, rocía con aceite y pimentón, y cocínalas en la airfryer a 190°C durante 20-25 minutos, agitándolas a mitad para un dorado uniforme. La salsa y el huevo se preparan aparte en sartén mientras las patatas se cocinan."},{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Asa las patatas cortadas en dados con aceite y pimentón en el horno precalentado a 200°C durante 35-40 minutos, volteándolas para que doren por todos lados. Prepara la salsa brava y el huevo frito en la sartén mientras las patatas se hornean."}]'::jsonb, '{}'),
  ('platos_unicos_016', 'Bocadillo de tortilla', 'platos_unicos', 'huevo', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 512, 16, 52, 26, 2, true, true, '{"gluten","huevo"}', '[{"name":"Pan de barra","amount":200,"unit":"g"},{"name":"Patata","amount":200,"unit":"g"},{"name":"Huevo","amount":3,"unit":"ud"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Confitar patata y cebolla en aceite","Cuajar la tortilla jugosa","Abrir el pan y rellenar con la tortilla","Presionar ligeramente y servir"}', 'Bocadillo de pan crujiente con tortilla de patata jugosa', '[]'::jsonb, '{}'),
  ('platos_unicos_017', 'Burritos caseros de pollo', 'platos_unicos', 'pollo', NULL, ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 468, 30, 42, 20, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Tortilla de trigo","amount":2,"unit":"ud"},{"name":"Pechuga de pollo","amount":250,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Arroz cocido","amount":100,"unit":"g"},{"name":"Queso rallado","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Saltear pollo en tiras con pimiento a fuego fuerte","Calentar las tortillas en sartén seca","Rellenar con pollo, arroz y queso","Enrollar cerrando los extremos"}', 'Burritos de tortilla de trigo con pollo, arroz y queso', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Cocina el pollo troceado y el pimiento a 180°C durante 15-18 min. Luego, rellena las tortillas y calienta los burritos montados en la airfryer a 180°C por 5-7 min para que se doren y el queso se funda."},{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Asa el pollo troceado y el pimiento en una bandeja a 200°C por 20-25 min. Rellena las tortillas y hornea los burritos a 180°C durante 10-12 min hasta que el queso se derrita y las tortillas estén ligeramente doradas."},{"appliance":"thermomix","time":25,"difficulty":"normal","prepSummary":"Prepara el sofrito de pimiento y cocina el pollo troceado en el vaso. Añade el arroz cocido para integrarlo y calentarlo, obteniendo un relleno jugoso. Las tortillas se calientan aparte."}]'::jsonb, '{}'),
  ('platos_unicos_018', 'Paella de marisco', 'platos_unicos', 'marisco', NULL, ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 482, 26, 56, 16, 2, false, false, '{"marisco","moluscos","pescado"}', '[{"name":"Arroz","amount":200,"unit":"g"},{"name":"Gambas","amount":150,"unit":"g"},{"name":"Mejillones","amount":150,"unit":"g"},{"name":"Sepia","amount":100,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Azafrán","amount":1,"unit":"g"}]'::jsonb, '{"Sofreír sepia con ajo y tomate en la paella","Añadir caldo con azafrán, cocer 5 min","Incorporar arroz, repartir y cocer 12 min","Añadir gambas y mejillones, cocer 6 min más"}', 'Paella de arroz con gambas, mejillones y sepia', '[{"appliance":"horno","time":50,"difficulty":"normal","prepSummary":"Prepara el sofrito y saltea el marisco en una paellera apta para horno en la encimera. Añade el arroz y el caldo caliente, luego hornea a 200°C durante 20-25 minutos para una cocción uniforme y un socarrat perfecto."}]'::jsonb, '{}'),
  ('platos_unicos_019', 'Quesadillas caseras', 'platos_unicos', 'none', NULL, ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 388, 16, 34, 22, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Tortilla de trigo","amount":2,"unit":"ud"},{"name":"Queso rallado","amount":100,"unit":"g"},{"name":"Jamón cocido","amount":60,"unit":"g"},{"name":"Pimiento rojo","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Calentar la tortilla en sartén con un poco de aceite","Repartir queso, jamón y pimiento en media tortilla","Doblar por la mitad y cocinar 2 min por lado","Cortar en triángulos y servir"}', 'Tortilla de trigo doblada con queso fundido, jamón y pimiento', '[{"appliance":"airfryer","time":12,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Cocina la quesadilla montada durante 10-12 minutos, dándole la vuelta a mitad de cocción, hasta que el queso se derrita y la tortilla esté dorada y crujiente."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Hornea la quesadilla montada sobre papel de horno durante 10-12 minutos, hasta que el queso esté fundido y la tortilla ligeramente dorada y crujiente."}]'::jsonb, '{}'),
  ('platos_unicos_020', 'Huevos a la riojana', 'platos_unicos', 'huevo', NULL, ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 378, 16, 18, 26, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Pimiento choricero","amount":2,"unit":"ud"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Chorizo","amount":50,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Sofreír cebolla, ajo y chorizo en rodajas","Freír la patata cortada en dados hasta que esté tierna e incorporarla a la salsa","Añadir pimiento choricero y tomate, cocer 15 min","Hacer huecos en la salsa y cascar los huevos","Tapar y cocer 5 min hasta que la clara cuaje"}', 'Huevos escalfados en salsa de tomate con chorizo, pimiento y patata en dados', '[{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Sofríe la cebolla, ajo y chorizo en una cazuela apta para horno. Incorpora el pimiento choricero y el tomate, cocina unos minutos. Haz huecos, casca los huevos y hornea a 180°C durante 10-15 minutos hasta que las claras estén cuajadas."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Trocea y sofríe la cebolla y el ajo. Añade el chorizo, pimiento choricero y tomate triturado, y cocina la salsa a temperatura Varoma. Haz huecos en la salsa, casca los huevos y cocina a baja velocidad y temperatura suave hasta que cuajen."}]'::jsonb, '{}'),
  ('postres_001', 'Macedonia de fruta fresca', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 140, 2, 33, 1, 4, true, true, '{}', '[{"name":"Manzana","amount":1,"unit":"ud"},{"name":"Plátano","amount":1,"unit":"ud"},{"name":"Naranja","amount":2,"unit":"ud"},{"name":"Fresas","amount":150,"unit":"g"},{"name":"Zumo de limón","amount":15,"unit":"ml"}]'::jsonb, '{"Pela y trocea la manzana, el plátano y una naranja","Limpia y parte las fresas","Exprime la otra naranja y el limón sobre la fruta","Mezcla con cuidado y enfría antes de servir"}', 'Macedonia fresca de manzana, plátano, naranja y fresas con un toque de cítrico', NULL, '{}'),
  ('postres_002', 'Yogur con miel y nueces', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 4, 'facil', 'all', 280, 11, 28, 14, 2, false, false, '{"lactosa","frutos_secos"}', '[{"name":"Yogur natural","amount":250,"unit":"g"},{"name":"Miel","amount":20,"unit":"ml"},{"name":"Nueces","amount":40,"unit":"g"}]'::jsonb, '{"Reparte el yogur en dos cuencos","Trocea ligeramente las nueces","Reparte las nueces sobre el yogur","Termina con un hilo de miel"}', 'Yogur natural con nueces troceadas y miel, un postre sencillo y saciante', NULL, '{}'),
  ('postres_003', 'Fruta fresca', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 3, 'facil', 'all', 90, 1, 22, 0, 2, true, true, '{}', '[{"name":"Manzana","amount":1,"unit":"ud"},{"name":"Naranja","amount":1,"unit":"ud"}]'::jsonb, '{"Lava la fruta","Pela o trocea según la pieza","Sirve"}', 'Pieza de fruta fresca de temporada como postre ligero', NULL, '{}'),
  ('postres_004', 'Natillas caseras', 'postres', 'huevo', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 25, 'normal', 'all', 260, 9, 34, 9, 4, true, true, '{"lactosa","huevo"}', '[{"name":"Leche","amount":500,"unit":"ml"},{"name":"Huevo","amount":3,"unit":"ud"},{"name":"Azúcar","amount":90,"unit":"g"},{"name":"Maicena","amount":20,"unit":"g"}]'::jsonb, '{"Bate las yemas con el azúcar y la maicena","Añade la leche caliente poco a poco sin dejar de remover","Cocina a fuego suave hasta que espese, sin que hierva","Reparte en cuencos y enfría"}', 'Natillas caseras de huevo y leche', NULL, '{"Natillas","Natillas de vainilla"}'),
  ('postres_005', 'Flan de huevo', 'postres', 'huevo', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 240, 8, 32, 8, 4, true, true, '{"lactosa","huevo"}', '[{"name":"Leche","amount":500,"unit":"ml"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Azúcar","amount":120,"unit":"g"}]'::jsonb, '{"Prepara un caramelo con parte del azúcar y forra los moldes","Bate los huevos con el resto del azúcar y la leche","Reparte en los moldes y cuece al baño maría en el horno","Enfría bien antes de desmoldar"}', 'Flan de huevo casero al baño maría', NULL, '{"Flan"}'),
  ('postres_006', 'Arroz con leche', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 300, 7, 54, 6, 4, true, true, '{"lactosa"}', '[{"name":"Arroz","amount":150,"unit":"g"},{"name":"Leche","amount":800,"unit":"ml"},{"name":"Azúcar","amount":100,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Cuece el arroz con la leche y la piel de limón a fuego suave","Remueve a menudo durante unos 35-40 minutos","Añade el azúcar al final y mezcla","Reparte en cuencos y enfría"}', 'Arroz con leche tradicional aromatizado con limón', NULL, '{}'),
  ('postres_007', 'Manzana asada', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 40, 'facil', 'invierno', 160, 1, 38, 1, 4, true, true, '{}', '[{"name":"Manzana","amount":4,"unit":"ud"},{"name":"Azúcar","amount":40,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Descorazona las manzanas y colócalas en una fuente","Reparte azúcar y unas gotas de limón sobre cada una","Hornea a 180°C unos 35 minutos hasta que estén tiernas"}', 'Manzanas asadas al horno con azúcar y limón', '[{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Precalienta el horno a 180°C. Descorazona las manzanas, colócalas en una fuente con un poco de azúcar y unas gotas de limón, y hornea unos 35-40 minutos hasta que estén tiernas."}]'::jsonb, '{}'),
  ('sopas_cremas_001', 'Crema de calabacín', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'all', 168, 4, 14, 10, 2, true, true, '{"lactosa"}', '[{"name":"Calabacín","amount":400,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Quesito en porciones","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pochar cebolla en aceite","Añadir calabacín y patata troceados, cubrir con agua","Cocer 15 min hasta que estén tiernos","Triturar con el quesito hasta textura fina"}', 'Crema suave de calabacín con patata y quesito', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla, añade el resto de verduras troceadas con agua o caldo y cocina a temperatura Varoma durante 20 minutos. Tritura a velocidad progresiva hasta obtener una crema fina, incorporando el quesito al final."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla en la olla, añade el resto de verduras troceadas con agua o caldo. Cierra y cocina a presión durante 5-7 minutos. Una vez despresurizada, tritura hasta obtener una crema fina y añade el quesito."}]'::jsonb, '{}'),
  ('sopas_cremas_002', 'Sopa de fideos', 'sopas_cremas', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'invierno', 182, 6, 28, 4, 2, true, true, '{"gluten"}', '[{"name":"Fideos finos","amount":80,"unit":"g"},{"name":"Caldo de pollo","amount":600,"unit":"ml"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Calentar el caldo con zanahoria rallada","Cuando hierva, añadir los fideos","Cocer 5 min a fuego medio","Servir con un chorrito de aceite y perejil"}', 'Sopa caliente de fideos finos en caldo de pollo', '[{"appliance":"thermomix","time":18,"difficulty":"facil","prepSummary":"Pica la zanahoria 3 seg/vel 5. Sofríe con aceite 3 min/120°C/vel 1. Añade el caldo y los fideos, cocina 12 min/100°C/giro inverso/vel cuchara. Sirve con perejil."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Sofríe la zanahoria en la olla con aceite. Añade el caldo y los fideos, cierra la olla y cocina 3-4 minutos desde que sube la válvula. Despresuriza y sirve con perejil."}]'::jsonb, '{}'),
  ('sopas_cremas_003', 'Crema de calabaza', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'invierno', 178, 3, 22, 8, 2, true, true, '{}', '[{"name":"Calabaza","amount":400,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Nuez moscada","amount":2,"unit":"g"}]'::jsonb, '{"Pochar cebolla en aceite","Añadir calabaza, patata y zanahoria troceadas","Cubrir con agua y cocer 20 min","Triturar con nuez moscada hasta textura cremosa"}', 'Crema de calabaza con zanahoria y un toque de nuez moscada', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Asa las verduras troceadas con un chorrito de aceite de oliva en el horno precalentado a 200°C durante 30-40 minutos, hasta que estén muy tiernas y ligeramente doradas. Luego, tritura con caldo caliente hasta obtener una crema suave y con un sabor más profundo."},{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Trocea las verduras en la Thermomix y sofríelas con aceite. Añade agua o caldo y cocina a 100°C, velocidad cuchara, durante 20-25 minutos. Finalmente, tritura a velocidad progresiva hasta obtener una crema fina y homogénea."},{"appliance":"vaporera","time":35,"difficulty":"facil","prepSummary":"Cocina las verduras troceadas en la vaporera hasta que estén muy tiernas (aproximadamente 25-30 minutos). Después, tritura con un poco del agua de cocción o caldo caliente y un chorrito de aceite de oliva para una crema ligera y nutritiva."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe las verduras en la olla express con aceite. Añade agua o caldo, cierra la olla y cocina a presión durante 5-7 minutos desde que sube la válvula. Libera la presión y tritura hasta obtener una crema homogénea en tiempo récord."}]'::jsonb, '{}'),
  ('sopas_cremas_004', 'Gazpacho andaluz', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 15, 'facil', 'verano', 152, 3, 12, 10, 2, true, true, '{"gluten","sulfitos"}', '[{"name":"Tomate maduro","amount":500,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Pan del día anterior","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Vinagre de Jerez","amount":15,"unit":"ml"}]'::jsonb, '{"Remojar el pan en agua","Triturar tomate, pepino, pimiento y ajo con el pan","Añadir aceite y vinagre emulsionando","Colar si se desea, servir muy frío"}', 'Sopa fría de tomate, pepino y pimiento al estilo andaluz', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"La Thermomix es perfecta para el gazpacho. Introduce todos los ingredientes troceados y tritura a velocidad progresiva 1-10 durante 2-3 minutos hasta obtener una textura muy fina. Sirve bien frío."}]'::jsonb, '{"Gazpacho"}'),
  ('sopas_cremas_005', 'Salmorejo cordobés', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 10, 'facil', 'verano', 228, 5, 18, 16, 2, true, true, '{"gluten","huevo","sulfitos"}', '[{"name":"Tomate maduro","amount":500,"unit":"g"},{"name":"Pan del día anterior","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":50,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Vinagre de Jerez","amount":10,"unit":"ml"},{"name":"Jamón serrano","amount":20,"unit":"g"},{"name":"Huevo cocido","amount":1,"unit":"ud"}]'::jsonb, '{"Triturar tomate, pan remojado, ajo y vinagre","Ir añadiendo el aceite en hilo mientras se tritura","Enfriar en nevera al menos 1 h","Servir con picatostes de jamón y huevo cocido picado"}', 'Crema fría espesa de tomate y pan con jamón y huevo', '[{"appliance":"thermomix","time":10,"difficulty":"facil","prepSummary":"Introduce los tomates, pan, ajo, vinagre y sal en el vaso y tritura a velocidad progresiva hasta obtener una crema muy fina. Añade el aceite en hilo mientras sigues batiendo a velocidad media para emulsionar perfectamente."}]'::jsonb, '{"Salmorejo"}'),
  ('sopas_cremas_006', 'Crema de zanahoria', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'all', 158, 3, 18, 8, 2, true, true, '{}', '[{"name":"Zanahoria","amount":400,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Jengibre fresco","amount":5,"unit":"g"}]'::jsonb, '{"Pochar cebolla en aceite","Añadir zanahoria, patata y jengibre","Cubrir con agua y cocer 20 min","Triturar hasta textura cremosa"}', 'Crema suave de zanahoria con un toque de jengibre', '[{"appliance":"horno","time":50,"difficulty":"facil","prepSummary":"Asa las zanahorias, patatas y cebolla con el aceite y jengibre a 200°C durante 25-30 minutos para intensificar su sabor. Luego, hierve brevemente con agua o caldo y tritura hasta obtener una crema suave."},{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el jengibre con el aceite, añade las zanahorias y patatas, cubre con agua o caldo y cocina a 100°C, velocidad cuchara, durante 20-25 minutos. Finalmente, tritura a velocidad progresiva hasta obtener una crema fina."},{"appliance":"vaporera","time":35,"difficulty":"facil","prepSummary":"Cocina al vapor las zanahorias, patatas, cebolla y jengibre hasta que estén muy tiernas, unos 25-30 minutos. Luego, tritura los vegetales con el aceite de oliva y un poco de agua o caldo hasta conseguir la textura deseada."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el jengibre en la olla, añade las zanahorias y patatas, cubre con agua o caldo. Cierra la olla y cocina 5-7 minutos desde que sube la válvula. Despresuriza y tritura hasta obtener una crema homogénea."}]'::jsonb, '{}'),
  ('sopas_cremas_007', 'Sopa castellana', 'sopas_cremas', 'huevo', NULL, ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'invierno', 248, 12, 22, 12, 2, true, false, '{"gluten","huevo"}', '[{"name":"Pan del día anterior","amount":80,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Pimentón","amount":6,"unit":"g"},{"name":"Jamón serrano","amount":40,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Caldo de carne","amount":500,"unit":"ml"}]'::jsonb, '{"Dorar ajos y jamón en aceite, añadir pimentón","Incorporar pan en rebanadas y caldo caliente","Cocer 10 min a fuego suave","Cascar los huevos encima y hornear 5 min a 200°C"}', 'Sopa de ajo con pan, jamón y huevo escalfado', '[{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"En una cazuela apta para horno, sofríe el ajo y el jamón. Añade el pimentón y el caldo, luego hornea a 180°C durante 20 minutos para que los sabores se integren, añadiendo los huevos al final para que se escalfen con el calor residual."},{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Sofríe el ajo y el jamón en el vaso a 120°C, velocidad cuchara. Incorpora el pimentón, el caldo y el pan, cocinando a 100°C, velocidad cuchara, durante 15 minutos. Añade los huevos al final y cocina 2-3 minutos más."},{"appliance":"olla_express","time":22,"difficulty":"facil","prepSummary":"Sofríe el ajo y el jamón en la olla abierta. Añade el pimentón, el pan y el caldo, cierra la olla y cocina 5 minutos desde que suba la válvula. Despresuriza, abre y escalfa los huevos con el calor residual."}]'::jsonb, '{}'),
  ('sopas_cremas_008', 'Vichyssoise', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'verano', 192, 4, 22, 10, 2, true, true, '{"lactosa"}', '[{"name":"Puerro","amount":250,"unit":"g"},{"name":"Patata","amount":200,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Nata","amount":40,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pochar puerro y cebolla en aceite","Añadir patata y cubrir con agua","Cocer 20 min y triturar fino","Añadir nata, enfriar en nevera y servir fría"}', 'Crema fría de puerro y patata con nata', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"La Thermomix es perfecta para la Vichyssoise, ya que sofríe, cocina y tritura en un solo recipiente. Sofríe las verduras 5 min a 120°C, luego añade patatas y agua, cocina 15 min a 100°C y tritura progresivamente hasta obtener una crema fina con la nata."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"La olla express reduce drásticamente el tiempo de cocción de las verduras. Sofríe los puerros y cebolla en la olla, añade las patatas y agua, cierra y cocina 7-10 minutos a presión, luego tritura con la nata hasta lograr una crema suave."}]'::jsonb, '{}'),
  ('sopas_cremas_009', 'Crema de puerros', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'invierno', 172, 4, 18, 8, 2, true, true, '{}', '[{"name":"Puerro","amount":300,"unit":"g"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Limpiar puerros y trocear la parte blanca y verde claro","Pochar con cebolla en aceite","Añadir patata y agua, cocer 20 min","Triturar hasta textura cremosa"}', 'Crema caliente de puerros con patata', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Sofríe las verduras picadas con aceite 5 min/120°C/vel 1. Añade agua o caldo y cocina 15 min/100°C/vel 1. Tritura progresivamente 1 min/vel 5-10 hasta obtener una crema fina y homogénea."},{"appliance":"olla_express","time":18,"difficulty":"facil","prepSummary":"Sofríe las verduras en la olla con aceite. Añade agua o caldo hasta cubrir, cierra la olla y cocina 5-7 minutos desde que sube la válvula. Despresuriza y tritura hasta obtener una crema suave."}]'::jsonb, '{}'),
  ('sopas_cremas_010', 'Sopa de cebolla', 'sopas_cremas', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, 'horno', 40, 'facil', 'invierno', 218, 8, 22, 10, 2, false, false, '{"gluten","lactosa"}', '[{"name":"Cebolla","amount":400,"unit":"g"},{"name":"Caldo de carne","amount":500,"unit":"ml"},{"name":"Pan","amount":60,"unit":"g"},{"name":"Queso gruyère","amount":40,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Vino blanco","amount":40,"unit":"ml"}]'::jsonb, '{"Pochar la cebolla en juliana con mantequilla 20 min","Añadir vino y dejar evaporar","Incorporar el caldo y cocer 15 min","Servir con pan tostado y gratinar con queso"}', 'Sopa de cebolla caramelizada gratinada con queso', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Comienza caramelizando las cebollas lentamente en una olla a fuego medio-bajo. Luego, añade el vino y el caldo, y cocina a fuego suave. Sirve la sopa en cuencos individuales aptos para horno, cubre con el pan y el queso, y gratina a 200°C durante 5-10 minutos hasta que el queso esté fundido y dorado."},{"appliance":"thermomix","time":45,"difficulty":"facil","prepSummary":"Pica las cebollas y sofríelas con la mantequilla a 120°C, velocidad cuchara, durante 20 minutos. Añade el vino y el caldo, y cocina a 100°C, velocidad cuchara, durante 15 minutos. Sirve la sopa en cuencos aptos para horno, cubre con pan y queso, y gratina en el horno precalentado a 200°C durante 5-10 minutos hasta que el queso se funda y dore."},{"appliance":"olla_express","time":40,"difficulty":"normal","prepSummary":"Sofríe las cebollas con la mantequilla en la olla express abierta a fuego medio hasta que estén bien caramelizadas (aprox. 15-20 min). Añade el vino y el caldo, cierra la olla y cocina a presión durante 10-12 minutos. Sirve la sopa en cuencos individuales, cubre con pan y queso, y gratina en el horno a 200°C durante 5-10 minutos hasta que el queso se funda y dore."}]'::jsonb, '{}'),
  ('sopas_cremas_011', 'Crema de verduras', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'all', 148, 4, 16, 8, 2, true, true, '{}', '[{"name":"Calabacín","amount":150,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Puerro","amount":80,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pochar cebolla y puerro","Añadir el resto de verduras troceadas","Cubrir con agua y cocer 20 min","Triturar hasta textura fina"}', 'Crema suave de verduras variadas con patata', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Pica las verduras, sofríelas con el aceite, añade agua o caldo y cocina a 100°C durante 15-20 minutos. Luego, tritura a velocidad progresiva hasta obtener una crema fina."},{"appliance":"vaporera","time":25,"difficulty":"facil","prepSummary":"Corta las verduras y cocínalas al vapor hasta que estén muy tiernas (aprox. 15-20 min). Luego, tritura con un poco de agua o caldo y el aceite de oliva hasta obtener una crema suave."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el puerro en la olla. Añade el resto de verduras, agua o caldo y cocina a presión alta durante 5-7 minutos. Libera la presión y tritura con el aceite de oliva."},{"appliance":"microondas","time":20,"difficulty":"facil","prepSummary":"Corta las verduras y cocínalas en un recipiente apto para microondas con un poco de agua durante 10-15 minutos a máxima potencia hasta que estén tiernas. Luego, tritura con el aceite de oliva y un poco de líquido de cocción."}]'::jsonb, '{}'),
  ('sopas_cremas_012', 'Crema de champiñones', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'invierno', 186, 6, 12, 12, 2, true, true, '{"lactosa"}', '[{"name":"Champiñones","amount":300,"unit":"g"},{"name":"Patata","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Nata","amount":40,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"}]'::jsonb, '{"Sofreír cebolla y ajo, añadir champiñones","Incorporar patata y cubrir con agua","Cocer 15 min hasta que esté tierno","Triturar y añadir nata caliente"}', 'Crema de champiñones con nata y un toque de ajo', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Pica la cebolla y el ajo, sofríe con aceite. Añade los champiñones y la patata, cubre con agua/caldo y cocina 15-20 min a 100°C. Tritura a velocidad progresiva hasta obtener una crema fina, incorporando la nata al final."},{"appliance":"olla_express","time":18,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo en la olla con aceite. Añade los champiñones y la patata, cubre con agua/caldo y cocina a presión alta durante 5-7 minutos. Libera la presión, añade la nata y tritura con una batidora de mano."}]'::jsonb, '{}'),
  ('sopas_cremas_013', 'Puré de patatas gratinado', 'sopas_cremas', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 228, 4, 30, 10, 2, true, true, '{"lactosa"}', '[{"name":"Patata","amount":400,"unit":"g"},{"name":"Leche","amount":80,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Nuez moscada","amount":2,"unit":"g"}]'::jsonb, '{"Pelar y trocear las patatas","Cocer en agua con sal 20 min","Escurrir y aplastar con tenedor o pasapurés","Añadir leche caliente, mantequilla y nuez moscada"}', 'Puré de patatas cremoso con mantequilla y nuez moscada', '[{"appliance":"horno","time":55,"difficulty":"facil","prepSummary":"Asa las patatas enteras a 200°C durante unos 45-55 minutos hasta que estén muy tiernas. Luego pélalas, machácalas y mezcla con la leche, mantequilla y nuez moscada para un puré más seco y con sabor concentrado."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Cocina las patatas troceadas en el cestillo o varoma durante 20-25 minutos a temperatura Varoma, velocidad 1. Luego, tritúralas con la leche, mantequilla y nuez moscada a velocidad 4-5 hasta obtener la textura deseada."},{"appliance":"vaporera","time":30,"difficulty":"facil","prepSummary":"Corta las patatas en trozos y cuécelas al vapor durante 25-30 minutos hasta que estén muy tiernas. Machácalas bien y luego incorpora la leche caliente, la mantequilla y la nuez moscada para un puré ligero y sabroso."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Cocina las patatas troceadas con un poco de agua en la olla express durante 6-8 minutos desde que sube la válvula. Despresuriza, escurre y machaca, añadiendo luego la leche, mantequilla y nuez moscada para un puré muy rápido y cremoso."},{"appliance":"microondas","time":15,"difficulty":"facil","prepSummary":"Pincha las patatas enteras o trocéalas y cocínalas en el microondas a máxima potencia durante 10-12 minutos, volteando a mitad, hasta que estén muy tiernas. Luego machaca y mezcla con el resto de ingredientes para un puré exprés."}]'::jsonb, '{}'),
  ('sopas_cremas_014', 'Crema de espárragos', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'all', 142, 5, 12, 8, 2, true, true, '{}', '[{"name":"Espárragos trigueros","amount":300,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"}]'::jsonb, '{"Trocear espárragos desechando la parte leñosa","Pochar cebolla y ajo","Añadir espárragos y patata, cubrir con agua","Cocer 15 min y triturar fino"}', 'Crema de espárragos trigueros con patata', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Pica la cebolla y el ajo, sofríe con aceite. Añade los espárragos y patata troceados con agua o caldo. Cocina 12-15 minutos a 100°C, velocidad cuchara, luego tritura a velocidad progresiva hasta obtener una crema fina y homogénea."},{"appliance":"olla_express","time":18,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo en la olla. Incorpora los espárragos, patata y líquido. Cierra y cocina a presión alta 5-7 minutos. Despresuriza y tritura con una batidora de mano hasta lograr una crema suave."},{"appliance":"vaporera","time":28,"difficulty":"facil","prepSummary":"Cocina los espárragos, patata, cebolla y ajo al vapor hasta que estén muy tiernos (aprox. 20-25 minutos). Transfiere a una batidora, añade el aceite de oliva y un poco de agua o caldo de la cocción, y tritura hasta obtener una crema suave."},{"appliance":"microondas","time":15,"difficulty":"facil","prepSummary":"Corta las verduras y cocínalas en un recipiente apto para microondas con un poco de agua durante 10-12 minutos a máxima potencia, hasta que estén tiernas. Luego, tritura con el aceite de oliva y un poco de líquido hasta obtener una crema fina."}]'::jsonb, '{}'),
  ('sopas_cremas_015', 'Ajoblanco', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 15, 'facil', 'verano', 268, 8, 16, 20, 2, false, true, '{"gluten","frutos_secos","sulfitos"}', '[{"name":"Almendras crudas","amount":100,"unit":"g"},{"name":"Pan del día anterior","amount":60,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Vinagre de Jerez","amount":15,"unit":"ml"},{"name":"Uvas","amount":60,"unit":"g"}]'::jsonb, '{"Remojar pan y almendras peladas en agua fría","Triturar con ajo, aceite y vinagre hasta emulsionar","Ajustar consistencia con agua fría","Servir muy frío con uvas peladas"}', 'Sopa fría de almendras y ajo con uvas, típica de Málaga', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"La Thermomix es perfecta para el ajoblanco. Tritura todos los ingredientes (almendras, pan, ajo, agua, aceite, vinagre y sal) a velocidad progresiva hasta lograr una crema muy fina y emulsionada. Sirve bien frío con las uvas."}]'::jsonb, '{}'),
  ('sopas_cremas_016', 'Sopa de tomate', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'all', 162, 3, 16, 10, 2, true, true, '{}', '[{"name":"Tomate maduro","amount":500,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Orégano","amount":3,"unit":"g"}]'::jsonb, '{"Sofreír cebolla y ajo en aceite","Añadir tomate troceado y orégano","Cocer 15 min a fuego lento","Triturar y servir caliente"}', 'Sopa caliente de tomate natural con orégano', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Asa los tomates, cebolla y ajo en la airfryer a 190°C durante 15-20 minutos hasta que estén tiernos y ligeramente caramelizados. Luego, tritúralos con un poco de agua o caldo y el orégano hasta obtener una sopa cremosa."},{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Asa los tomates, cebolla y ajo en el horno a 180°C durante 30-40 minutos hasta que estén bien tiernos y con un ligero tostado. Después, tritúralos con el aceite de oliva, orégano y un poco de agua o caldo hasta conseguir una sopa suave."},{"appliance":"thermomix","time":22,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo con el aceite. Añade los tomates troceados y el orégano, cocina a temperatura Varoma durante 15 minutos y finalmente tritura a velocidad progresiva hasta obtener una crema fina y homogénea."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo en la olla express. Incorpora los tomates y el orégano, cierra la olla y cocina a presión durante 5-7 minutos. Una vez despresurizada, tritura todo hasta lograr una sopa cremosa."}]'::jsonb, '{}'),
  ('sopas_cremas_017', 'Crema de brócoli', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 20, 'facil', 'invierno', 152, 6, 12, 8, 2, true, true, '{}', '[{"name":"Brócoli","amount":350,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pochar cebolla y ajo","Añadir brócoli en ramilletes y patata","Cubrir con agua y cocer 12 min","Triturar hasta textura fina y cremosa"}', 'Crema de brócoli con patata, suave y nutritiva', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo, añade el resto de ingredientes y agua, cocina 18 min a 100°C, velocidad cuchara. Luego tritura 1 min a velocidad progresiva 5-10 hasta obtener una crema fina."},{"appliance":"vaporera","time":20,"difficulty":"facil","prepSummary":"Cocina el brócoli, la patata, cebolla y ajo al vapor durante 15-18 minutos hasta que estén tiernos. Luego, tritura los vegetales con el aceite de oliva y un poco del agua de cocción hasta lograr una crema suave."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo en la olla. Añade el brócoli, la patata y un poco de agua, cierra y cocina 5 minutos desde que sube la válvula. Libera la presión y tritura directamente en la olla hasta obtener una crema homogénea."},{"appliance":"microondas","time":18,"difficulty":"facil","prepSummary":"Coloca todos los vegetales troceados con un chorrito de agua en un recipiente apto para microondas. Cocina a máxima potencia durante 12-15 minutos hasta que estén muy tiernos. Luego, tritura con el aceite de oliva hasta obtener una crema suave."}]'::jsonb, '{}'),
